// NEW HSK 3.0 Cap 3 - Goi du lieu tai theo yeu cau (Dot 1: Bai 1-9)
const HSK30_3_FULL_DATA = {"1":{"pages":"1–9","titleZh":"我们去机场接你们","titlePy":"Wǒmen qù jīchǎng jiē nǐmen","titleVi":"Anh chị sẽ đến sân bay đón các em","goals":["能听懂并使用多项定语描述人或事物的特征。Có khả năng nghe hiểu và sử dụng được định ngữ đa tầng để miêu tả đặc điểm của người hoặc sự vật.","能听懂并解决物品丢失的问题。Có khả năng nghe hiểu và giải quyết các vấn đề liên quan đến việc thất lạc đồ vật.","掌握疑问代词的用法，能表达不确定的人、事物或地方等信息。Nắm vững cách sử dụng đại từ nghi vấn để diễn đạt thông tin về người, sự vật hoặc địa điểm không xác định."],"words":[{"zh":"以为","py":"yǐwéi","vi":"cho rằng, nghĩ rằng","pos":"đgt."},{"zh":"像","py":"xiàng","vi":"giống, giống như","pos":"đgt."},{"zh":"长","py":"zhǎng","vi":"phát triển, lớn lên","pos":"đgt."},{"zh":"身高","py":"shēngāo","vi":"chiều cao","pos":"dt."},{"zh":"米","py":"mǐ","vi":"mét (đơn vị đo lường)","pos":"lượng."},{"zh":"瘦","py":"shòu","vi":"gầy, ốm","pos":"tt."},{"zh":"接","py":"jiē","vi":"đón","pos":"đgt."},{"zh":"行李","py":"xíngli","vi":"hành lý","pos":"dt."},{"zh":"丢","py":"diū","vi":"làm mất, bị mất","pos":"đgt."},{"zh":"箱子","py":"xiāngzi","vi":"va li","pos":"dt."},{"zh":"号码","py":"hàomǎ","vi":"số, mã số","pos":"dt."},{"zh":"好像","py":"hǎoxiàng","vi":"dường như, có vẻ như","pos":"phó."},{"zh":"重要","py":"zhòngyào","vi":"quan trọng","pos":"tt."},{"zh":"着急","py":"zháojí","vi":"lo lắng, sốt ruột","pos":"tt."},{"zh":"护照","py":"hùzhào","vi":"hộ chiếu","pos":"dt."},{"zh":"服务台","py":"fúwùtái","vi":"quầy phục vụ","pos":"dt."},{"zh":"应该","py":"yīnggāi","vi":"nên","pos":"đtnn."},{"zh":"站","py":"zhàn","vi":"đứng","pos":"đgt."},{"zh":"中间","py":"zhōngjiān","vi":"ở giữa, trung gian","pos":"dt."},{"zh":"短","py":"duǎn","vi":"ngắn","pos":"tt."},{"zh":"头发","py":"tóufa","vi":"tóc","pos":"dt."},{"zh":"年轻","py":"niánqīng","vi":"trẻ, trẻ tuổi","pos":"tt."},{"zh":"发现","py":"fāxiàn","vi":"phát hiện, tìm thấy","pos":"đgt."},{"zh":"不见","py":"bújiàn","vi":"bị mất, không thấy","pos":"đgt."},{"zh":"带","py":"dài","vi":"mang, dẫn, đưa","pos":"đgt."},{"zh":"帮助","py":"bāngzhù","vi":"giúp, giúp đỡ","pos":"đgt."},{"zh":"照片","py":"zhàopiàn","vi":"ảnh (chụp)","pos":"dt."}],"dialog":[{"section":"Bài khóa 1","context":"在家里，刘明和王一雪在沙发上聊天儿。Lưu Minh và Vương Nhất Tuyết đang trò chuyện trên ghế sofa ở trong nhà.","audio":"01-1.mp3","speaker":"刘明","name":"Lưu Minh","zh":"这是杨同乐吗？他怎么跟白家月在一起？","py":"Zhè shì Yáng Tónglè ma? Tā zěnme gēn Bái Jiāyuè zài yìqǐ?","vi":"Đây có phải là Dương Đồng Lạc không nhỉ? Sao em ấy lại đi cùng Bạch Gia Nguyệt thế?"},{"section":"Bài khóa 1","context":"","audio":"01-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"他不是杨同乐，他叫李文，是白家月的好朋友。","py":"Tā bú shì Yáng Tónglè, tā jiào Lǐ Wén, shì Bái Jiāyuè de hǎo péngyou.","vi":"Em ấy không phải là Dương Đồng Lạc đâu. Em ấy tên là Lý Văn, là bạn thân của Bạch Gia Nguyệt."},{"section":"Bài khóa 1","context":"","audio":"01-1.mp3","speaker":"刘明","name":"Lưu Minh","zh":"我还以为是同乐呢，他们看上去有点儿像。","py":"Wǒ hái yǐwéi shì Tónglè ne, tāmen kàn shàngqu yǒudiǎnr xiàng.","vi":"Anh cứ tưởng là Đồng Lạc, trông họ hơi giống nhau."},{"section":"Bài khóa 1","context":"","audio":"01-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"是长得有点儿像，但是他比同乐高，身高有一米八。","py":"Shì zhǎng de yǒudiǎnr xiàng, dànshì tā bǐ Tónglè gāo, shēngāo yǒu yì mǐ bā.","vi":"Đúng là hơi giống thật, nhưng em ấy cao hơn Đồng Lạc, cao khoảng 1m8."},{"section":"Bài khóa 1","context":"","audio":"01-1.mp3","speaker":"刘明","name":"Lưu Minh","zh":"看起来也比同乐瘦一点儿。","py":"Kàn qǐlái yě bǐ Tónglè shòu yìdiǎnr.","vi":"Xem ra cũng có vẻ gầy hơn Đồng Lạc một chút."},{"section":"Bài khóa 1","context":"","audio":"01-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"下个星期家月和李文要来北京，我去机场接他们。","py":"Xià gè xīngqī Jiāyuè hé Lǐ Wén yào lái Běijīng, wǒ qù jīchǎng jiē tāmen.","vi":"Gia Nguyệt và Lý Văn sẽ đến Bắc Kinh vào tuần tới. Em định đi đón các em ấy ở sân bay."},{"section":"Bài khóa 1","context":"","audio":"01-1.mp3","speaker":"刘明","name":"Lưu Minh","zh":"他们哪天到北京？我跟你一起去机场接他们吧。","py":"Tāmen nǎ tiān dào Běijīng? Wǒ gēn nǐ yìqǐ qù jīchǎng jiē tāmen ba.","vi":"Các em ấy đến vào ngày nào? Anh sẽ đi đón cùng em."},{"section":"Bài khóa 2","context":"在机场，李文和白家月在行李领取处。Lý Văn và Bạch Gia Nguyệt đang ở khu vực nhận hành lý tại sân bay.","audio":"01-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我的行李怎么还没出来？是不是丢了？","py":"Wǒ de xíngli zěnme hái méi chūlai? Shì bu shì diū le?","vi":"Sao hành lý của em vẫn chưa thấy đâu nhỉ? Liệu có bị thất lạc không nhỉ?"},{"section":"Bài khóa 2","context":"","audio":"01-3.mp3","speaker":"李文","name":"Lý Văn","zh":"你的行李箱是什么样的？","py":"Nǐ de xínglixiāng shì shénme yàng de?","vi":"Va li của em trông như thế nào?"},{"section":"Bài khóa 2","context":"","audio":"01-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"是一个黑色的箱子，上面写着我的名字和电话号码。","py":"Shì yí gè hēisè de xiāngzi, shàngmian xiězhe wǒ de míngzi hé diànhuà hàomǎ.","vi":"Là một chiếc va li màu đen, trên đó có ghi tên em và số điện thoại."},{"section":"Bài khóa 2","context":"","audio":"01-3.mp3","speaker":"李文","name":"Lý Văn","zh":"我好像在哪儿看到过这个箱子，是不是有人拿错了？","py":"Wǒ hǎoxiàng zài nǎr kàndào guo zhège xiāngzi, shì bu shì yǒu rén ná cuò le?","vi":"Hình như anh đã nhìn thấy một cái giống như vậy ở đâu đó rồi, hay ai đó đã lấy nhầm mất rồi?"},{"section":"Bài khóa 2","context":"","audio":"01-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我们快找谁问一下吧，箱子里有不少重要的东西。","py":"Wǒmen kuài zhǎo shéi wèn yíxià ba, xiāngzi li yǒu bù shǎo zhòngyào de dōngxi.","vi":"Chúng ta mau tìm người để hỏi đi, trong va li có nhiều đồ quan trọng lắm."},{"section":"Bài khóa 2","context":"","audio":"01-3.mp3","speaker":"李文","name":"Lý Văn","zh":"别着急，我们拿着护照和机票，去服务台问问吧。","py":"Bié zháojí, wǒmen názhe hùzhào hé jīpiào, qù fúwùtái wènwen ba.","vi":"Đừng lo lắng. Chúng ta cầm theo hộ chiếu và vé máy bay đến quầy phục vụ để hỏi xem sao."},{"section":"Bài khóa 3","context":"在机场大厅，刘明和王一雪接机。Lưu Minh và Vương Nhất Tuyết đang đón người tại sảnh sân bay.","audio":"01-5.mp3","speaker":"刘明","name":"Lưu Minh","zh":"飞机早就到了，你看见白家月他们了吗？","py":"Fēijī zǎo jiù dào le, nǐ kànjiàn Bái Jiāyuè tāmen le ma?","vi":"Máy bay đã hạ cánh từ lâu rồi. Em đã nhìn thấy Bạch Gia Nguyệt và Lý Văn chưa?"},{"section":"Bài khóa 3","context":"","audio":"01-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"没有，他们应该快出来了。","py":"Méiyǒu, tāmen yīnggāi kuài chūlai le.","vi":"Chưa ạ, chắc các em ấy sẽ ra ngay bây giờ thôi."},{"section":"Bài khóa 3","context":"","audio":"01-5.mp3","speaker":"刘明","name":"Lưu Minh","zh":"我们站到中间去吧，这样他们好找一些。","py":"Wǒmen zhàn dào zhōngjiān qù ba, zhèyàng tāmen hǎo zhǎo yìxiē.","vi":"Chúng ta đứng ra giữa đi, như vậy các em ấy sẽ dễ nhìn thấy hơn."},{"section":"Bài khóa 3","context":"","audio":"01-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"你看那个高个子的人是李文吗？","py":"Nǐ kàn nàge gāo gèzi de rén shì Lǐ Wén ma?","vi":"Anh nhìn xem, có phải chàng trai cao cao kia là Lý Văn không?"},{"section":"Bài khóa 3","context":"","audio":"01-5.mp3","speaker":"刘明","name":"Lưu Minh","zh":"你说的是哪个？那个穿着黑衣服的短头发的年轻人？","py":"Nǐ shuō de shì nǎge? Nàge chuānzhe hēi yīfu de duǎn tóufa de niánqīngrén?","vi":"Em nói người nào vậy? Chàng trai tóc ngắn, mặc đồ đen kia phải không?"},{"section":"Bài khóa 3","context":"","audio":"01-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"对，那个人就是李文！你看，家月在他后面呢。","py":"Duì, nàge rén jiù shì Lǐ Wén! Nǐ kàn, Jiāyuè zài tā hòumian ne.","vi":"Đúng rồi, người đó chính là Lý Văn! Anh nhìn kìa, Gia Nguyệt ở ngay phía sau em ấy."},{"section":"Bài khóa 4","context":"在宾馆房间，李文在写日记。Lý Văn đang viết nhật ký ở trong phòng khách sạn.","audio":"01-7.mp3","speaker":"李文","name":"Lý Văn","zh":"昨天我到北京了。虽然路上花了十几个小时，但是跟家月坐在一起，我觉得时间过得很快。到机场的时候，家月发现行李箱不见了，我带她去服务台，帮助她找到了行李箱。走出机场的时候，已经八点多了，我们一出来就看见了王老师的姐姐，她看起来比照片上年轻。晚上，一雪姐带我们去吃了一家很好吃的中国菜。","py":"Zuótiān wǒ dào Běijīng le. Suīrán lùshang huāle shí jǐ gè xiǎoshí, dànshì gēn Jiāyuè zuò zài yìqǐ, wǒ juéde shíjiān guò de hěn kuài. Dào jīchǎng de shíhou, Jiāyuè fāxiàn xínglixiāng bújiàn le, wǒ dài tā qù fúwùtái, bāngzhù tā zhǎodàole xínglixiāng. Zǒuchū jīchǎng de shíhou, yǐjīng bā diǎn duō le, wǒmen yì chūlai jiù kànjiànle Wáng lǎoshī de jiějie, tā kàn qǐlái bǐ zhàopiàn shang niánqīng. Wǎnshang, Yīxuě jiě dài wǒmen qù chīle yì jiā hěn hǎochī de Zhōngguó cài.","vi":"Hôm qua tôi đã đến Bắc Kinh. Mặc dù trải qua hành trình hơn mười tiếng đồng hồ, nhưng vì ngồi cạnh Gia Nguyệt nên tôi cảm thấy thời gian trôi qua rất nhanh. Khi đến sân bay, Gia Nguyệt phát hiện va li của mình không thấy đâu, tôi đã đưa cô ấy đến quầy phục vụ, giúp cô ấy tìm lại va li. Đến lúc chúng tôi rời sân bay thì đã hơn 8 giờ tối. Khi vừa bước ra ngoài, chúng tôi liền nhìn thấy chị gái của cô Vương, chị ấy trông trẻ hơn so với trong ảnh. Buổi tối, chị Nhất Tuyết đã đưa chúng tôi đi ăn món Trung Quốc rất ngon."}],"dialogQuestions":[],"grammar":{"g1":{"han":"固定短语“看上去/看起来”","py":"Gùdìng duǎnyǔ “kàn shàngqu/kàn qǐlái”","title":"Cụm từ cố định “看上去/看起来”","explain":"固定短语“看上去”与“看起来”，可用来描述某人或某物的外观或状态。\nCụm từ cố định “看上去” và “看起来” có thể được sử dụng để miêu tả ngoại hình hoặc trạng thái của người hoặc sự vật.","examples":[{"zh":"他们看上去有点儿像。","py":"Tāmen kàn shàngqu yǒudiǎnr xiàng.","vi":"Trông họ hơi giống nhau.","hl":"看上去"},{"zh":"这些菜看起来都很好吃。","py":"Zhèxiē cài kàn qǐlái dōu hěn hǎochī.","vi":"Những món ăn này trông đều rất ngon.","hl":"看起来"},{"zh":"那个新来的老师看上去很年轻。","py":"Nàge xīn lái de lǎoshī kàn shàngqu hěn niánqīng.","vi":"Thầy/cô giáo mới đến kia trông rất trẻ.","hl":"看上去"}],"struct":"Chủ ngữ + 看上去 / 看起来 + Tính từ / Cụm động từ","note":"Dùng để nêu nhận xét, đánh giá qua quan sát bề ngoài."},"g2":{"han":"疑问代词的非疑问用法（1）","py":"Yíwèn dàicí de fēi yíwèn yòngfǎ (1)","title":"Cách dùng linh hoạt của đại từ nghi vấn (1)","explain":"疑问代词“哪儿”、“什么”、“谁”、“哪”等用在陈述句中，表示不知道或不需要指明的地点、事物或人等。\nCác đại từ nghi vấn như “哪儿”, “什么”, “谁”, “哪” dùng trong câu trần thuật biểu thị những địa điểm, sự vật hoặc con người không biết hoặc không cần chỉ rõ.","examples":[{"zh":"我好像在哪儿看到过这个箱子。","py":"Wǒ hǎoxiàng zài nǎr kàndào guo zhège xiāngzi.","vi":"Hình như anh đã từng nhìn thấy chiếc va li này ở đâu đó rồi.","hl":"哪儿"},{"zh":"你吃点儿什么再走吧。","py":"Nǐ chī diǎnr shénme zài zǒu ba.","vi":"Bạn ăn chút gì đó rồi hãy đi.","hl":"什么"},{"zh":"我们哪天一起去踢足球吧。","py":"Wǒmen nǎ tiān yìqǐ qù tī zúqiú ba.","vi":"Hôm nào chúng ta cùng đi đá bóng nhé.","hl":"哪天"}],"struct":"Câu trần thuật chứa 哪儿 / 什么 / 谁 / 哪 (+ lượng từ) (phiếm chỉ)","note":"Mang nghĩa phiếm chỉ: ở đâu đó, cái gì đó, ai đó, ngày nào đó."},"g3":{"han":"多项定语","py":"Duōxiàng dìngyǔ","title":"Định ngữ đa tầng","explain":"名词性中心语的前面可以同时有多个定语，这些定语一般按照时间/处所、动作/状态、特点的顺序进行排列，数量短语或指量短语位置比较灵活，可以放在表示动作或状态的定语的前面或者后面。\nTrước trung tâm ngữ danh từ có thể cùng xuất hiện nhiều định ngữ. Các định ngữ này thường được sắp xếp theo trật tự như sau: thời gian/địa điểm → hành động/trạng thái → đặc điểm; trong đó, cụm từ chỉ số lượng hoặc cụm từ chỉ lượng có vị trí tương đối linh hoạt, có thể đặt trước hoặc sau định ngữ biểu thị hành động hoặc trạng thái.","examples":[{"zh":"李文是那个穿着黑衣服的短头发的年轻人吗？","py":"Lǐ Wén shì nàge chuānzhe hēi yīfu de duǎn tóufa de niánqīngrén ma?","vi":"Lý Văn có phải là chàng trai trẻ tóc ngắn mặc áo đen kia không?","hl":"那个穿着黑衣服的短头发的"},{"zh":"昨天和家月一起看电影的两个人是我的朋友。","py":"Zuótiān hé Jiāyuè yìqǐ kàn diànyǐng de liǎng gè rén shì wǒ de péngyou.","vi":"Hai người hôm qua cùng xem phim với Gia Nguyệt là bạn của tôi.","hl":"昨天和家月一起看电影的两个人"},{"zh":"我那件新买的白色的衣服在哪儿？","py":"Wǒ nà jiàn xīn mǎi de báisè de yīfu zài nǎr?","vi":"Chiếc áo màu trắng mới mua của tôi ở đâu rồi?","hl":"我那件新买的白色的"}],"struct":"(Thời gian/Nơi chốn) + (Sở hữu/Chỉ thị/Số lượng) + Động tác/Trạng thái + Đặc điểm + (的) + Trung tâm ngữ","note":"Sắp xếp từ phạm vi lớn/xa đến gần/gắn với tính chất cốt lõi của danh từ trung tâm."}},"grammarQuiz":[{"id":"hsk3_b1_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"服务台 (____) 在前面，我们过去问问吧。","opts":[{"t":"应该","ok":true},{"t":"带","ok":false},{"t":"接","ok":false},{"t":"丢","ok":false},{"t":"重要","ok":false}],"exp":"Đáp án E (应该): ‘Quầy phục vụ chắc là ở phía trước, chúng ta qua hỏi thử xem.’"},{"id":"hsk3_b1_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"他已经到了，我们快出去 (____) 他吧。","opts":[{"t":"接","ok":true},{"t":"带","ok":false},{"t":"丢","ok":false},{"t":"重要","ok":false},{"t":"应该","ok":false}],"exp":"Đáp án B (接): ‘Anh ấy đến rồi, chúng ta mau ra đón anh ấy đi.’"},{"id":"hsk3_b1_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我的护照不见了，是不是在机场 (____) 了？","opts":[{"t":"丢","ok":true},{"t":"带","ok":false},{"t":"接","ok":false},{"t":"重要","ok":false},{"t":"应该","ok":false}],"exp":"Đáp án C (丢): ‘Hộ chiếu của tôi không thấy đâu, có phải làm mất ở sân bay rồi không?’"},{"id":"hsk3_b1_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"行李票很 (____)，你们出机场的时候有人看。","opts":[{"t":"重要","ok":true},{"t":"带","ok":false},{"t":"接","ok":false},{"t":"丢","ok":false},{"t":"应该","ok":false}],"exp":"Đáp án D (重要): ‘Cuống vé hành lý rất quan trọng, lúc các bạn ra khỏi sân bay sẽ có người kiểm tra.’"},{"id":"hsk3_b1_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我 (____) 了两个行李箱和一个大包，所以走得非常慢。","opts":[{"t":"带","ok":true},{"t":"接","ok":false},{"t":"丢","ok":false},{"t":"重要","ok":false},{"t":"应该","ok":false}],"exp":"Đáp án A (带): ‘Tôi mang theo hai chiếc va li và một túi lớn nên đi rất chậm.’"},{"id":"hsk3_b1_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 这个头发很短的男孩儿是我弟弟。\nB: 我 (____) 这个是你，你们长得太像了。","opts":[{"t":"以为","ok":true},{"t":"发现","ok":false},{"t":"好像","ok":false},{"t":"年轻","ok":false},{"t":"帮助","ok":false}],"exp":"Đáp án B (以为): ‘Tôi cứ tưởng người này là bạn, hai người trông giống nhau quá.’"},{"id":"hsk3_b1_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 我 (____) 坐飞机来北京的人非常多。\nB: 对，很多人这个时候来北京旅游。","opts":[{"t":"发现","ok":true},{"t":"以为","ok":false},{"t":"好像","ok":false},{"t":"年轻","ok":false},{"t":"帮助","ok":false}],"exp":"Đáp án A (发现): ‘Tôi nhận thấy người đi máy bay đến Bắc Kinh rất đông.’"},{"id":"hsk3_b1_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 这是我和哥哥的照片，你看我们像吗？\nB: 你们很像，你哥哥看起来也很 (____)。","opts":[{"t":"年轻","ok":true},{"t":"发现","ok":false},{"t":"以为","ok":false},{"t":"好像","ok":false},{"t":"帮助","ok":false}],"exp":"Đáp án D (年轻): ‘Hai người rất giống nhau, anh trai bạn trông cũng rất trẻ.’"},{"id":"hsk3_b1_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你的行李箱找到了，你看看是不是这个？\nB: 对，太好了！谢谢您的 (____)。","opts":[{"t":"帮助","ok":true},{"t":"发现","ok":false},{"t":"以为","ok":false},{"t":"好像","ok":false},{"t":"年轻","ok":false}],"exp":"Đáp án E (帮助): ‘Đúng rồi, tuyệt quá! Cảm ơn sự giúp đỡ của ngài.’"},{"id":"hsk3_b1_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 那个穿着黑衣服的高个子的人是王老师吗？\nB: (____) 是吧，我也不知道。","opts":[{"t":"好像","ok":true},{"t":"发现","ok":false},{"t":"以为","ok":false},{"t":"年轻","ok":false},{"t":"帮助","ok":false}],"exp":"Đáp án C (好像): ‘Hình như là vậy, tôi cũng không rõ.’"},{"id":"hsk3_b1_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"刘明和王一雪在做什么？","opts":[{"t":"B 看手机","ok":true},{"t":"A 看电视","ok":false},{"t":"C 去机场","ok":false}],"exp":"Trong tranh Bài khóa 1: Hai người đang ngồi trên ghế sofa xem điện thoại."},{"id":"hsk3_b1_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"刘明跟王一雪一起去机场做什么？","opts":[{"t":"C 接白家月","ok":true},{"t":"A 坐飞机","ok":false},{"t":"B 找朋友","ok":false}],"exp":"Lưu Minh nói: “我跟你一起去机场接他们吧” (đón Bạch Gia Nguyệt và Lý Văn)."},{"id":"hsk3_b1_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"李文和白家月在机场做什么？","opts":[{"t":"A 等箱子","ok":true},{"t":"B 等同学","ok":false},{"t":"C 等王一雪","ok":false}],"exp":"Hai người đang đứng ở khu nhận hành lý đợi va li ra."},{"id":"hsk3_b1_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"白家月为什么很着急？","opts":[{"t":"B 行李箱丢了","ok":true},{"t":"A 护照丢了","ok":false},{"t":"C 拿错行李箱了","ok":false}],"exp":"Bạch Gia Nguyệt lo hành lý bị thất lạc vì trong va li có nhiều đồ quan trọng."},{"id":"hsk3_b1_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"刘明和王一雪在机场做什么？","opts":[{"t":"A 接人","ok":true},{"t":"B 坐飞机","ok":false},{"t":"C 找行李箱","ok":false}],"exp":"Hai người đang đợi ở sảnh sân bay để đón Bạch Gia Nguyệt và Lý Văn."},{"id":"hsk3_b1_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"刘明为什么要站到中间？","opts":[{"t":"C 白家月好找他们","ok":true},{"t":"A 旁边人太多了","ok":false},{"t":"B 他看见白家月了","ok":false}],"exp":"Lưu Minh nói: “我们站到中间去吧，这样他们好找一些。”"},{"id":"hsk3_b1_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"李文回北京的路上花了多长时间？","opts":[{"t":"B 十几个小时","ok":true},{"t":"A 几个小时","ok":false},{"t":"C 几十个小时","ok":false}],"exp":"Bài khóa 4: “虽然路上花了十几个小时...”"},{"id":"hsk3_b1_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"李文觉得王老师的姐姐看起来怎么样？","opts":[{"t":"B 很年轻","ok":true},{"t":"A 很累","ok":false},{"t":"C 很像王老师","ok":false}],"exp":"Bài khóa 4: “她看起来比照片上年轻。”"}],"chars":["以","为","像","长","身","高","米","瘦","接","行","李","丢","箱","子","号","码","好","重","要","着","急","护","照","服","务","台","应","该","站","中","间","短","头","发","年","轻","现","不","见","带","帮","助","片","我","们","去","机","场","你"],"rhyme":null,"notes":["Câu hỏi thảo luận Bài khóa 1: (1) 刘明为什么以为李文是杨同乐？ (2) 李文长什么样？ (3) 白家月什么时候来中国？","Câu hỏi thảo luận Bài khóa 2: (1) 白家月的箱子是什么样的？ (2) 李文看到过白家月的箱子吗？ (3) 他们现在要做什么？","Câu hỏi thảo luận Bài khóa 3: (1) 王一雪为什么说白家月他们应该快出来了？ (2) 刘明看见的年轻人长什么样？ (3) 王一雪怎么知道那个年轻人就是李文？","Câu hỏi thảo luận Bài khóa 4: (1) 李文为什么觉得时间过得很快？ (2) 到机场的时候，白家月发现了什么问题？ (3) 王一雪带他们去做什么了？"],"workbook":null},"2":{"pages":"10–18","titleZh":"你们想吃什么就点什么","titlePy":"Nǐmen xiǎng chī shénme jiù diǎn shénme","titleVi":"Các em muốn ăn món gì thì gọi món đó","goals":["能听懂并谈论餐厅的菜品、服务和个人的饮食习惯。Có khả năng nghe hiểu và trao đổi về món ăn trong nhà hàng, dịch vụ và thói quen ẩm thực của cá nhân.","能听懂并使用疑问代词指代任何一个对象。Có khả năng nghe hiểu và sử dụng đại từ nghi vấn để chỉ bất kỳ đối tượng nào.","了解中国人就餐时使用的餐具。Hiểu về dụng cụ ăn uống mà người Trung Quốc sử dụng khi dùng bữa."],"words":[{"zh":"菜单","py":"càidān","vi":"thực đơn","pos":"dt."},{"zh":"又","py":"yòu","vi":"lại, vừa","pos":"phó."},{"zh":"饿","py":"è","vi":"đói","pos":"tt."},{"zh":"渴","py":"kě","vi":"khát","pos":"tt."},{"zh":"客气","py":"kèqi","vi":"khách sáo, khách khí","pos":"đgt./tt."},{"zh":"饮料","py":"yǐnliào","vi":"đồ uống","pos":"dt."},{"zh":"好久","py":"hǎojiǔ","vi":"lâu, rất lâu","pos":"tt."},{"zh":"服务","py":"fúwù","vi":"phục vụ","pos":"đgt."},{"zh":"员","py":"yuán","vi":"đặt sau danh từ hoặc động từ để chỉ người","pos":"htố."},{"zh":"双","py":"shuāng","vi":"đôi","pos":"lượng."},{"zh":"筷子","py":"kuàizi","vi":"đũa","pos":"dt."},{"zh":"勺子","py":"sháozi","vi":"thìa","pos":"dt."},{"zh":"碗","py":"wǎn","vi":"bát","pos":"dt."},{"zh":"马上","py":"mǎshàng","vi":"lập tức, ngay lập tức","pos":"phó."},{"zh":"热情","py":"rèqíng","vi":"nhiệt tình","pos":"tt."},{"zh":"尝","py":"cháng","vi":"nếm, thử","pos":"đgt."},{"zh":"记","py":"jì","vi":"nhớ, ghi nhớ","pos":"đgt."},{"zh":"用","py":"yòng","vi":"dùng, sử dụng","pos":"đgt."},{"zh":"鸡","py":"jī","vi":"gà","pos":"dt."},{"zh":"张","py":"zhāng","vi":"tờ, bức (dùng cho giấy, tranh...)","pos":"lượng."},{"zh":"不用","py":"búyòng","vi":"không cần","pos":"phó."},{"zh":"选","py":"xuǎn","vi":"chọn, lựa chọn","pos":"đgt."},{"zh":"外卖","py":"wàimài","vi":"đồ ăn giao tận nơi, đặt đồ ăn giao tận nơi","pos":"dt./đgt."},{"zh":"方便","py":"fāngbiàn","vi":"thuận tiện, tiện lợi","pos":"tt."},{"zh":"蛋糕","py":"dàngāo","vi":"bánh ngọt, bánh kem, bánh ga tô","pos":"dt."},{"zh":"只","py":"zhǐ","vi":"chỉ","pos":"phó."},{"zh":"方便面","py":"fāngbiànmiàn","vi":"mì ăn liền","pos":"dt."},{"zh":"简单","py":"jiǎndān","vi":"đơn giản","pos":"tt."}],"dialog":[{"section":"Bài khóa 1","context":"在饭馆，王一雪、刘明、白家月和李文在点菜。Vương Nhất Tuyết, Lưu Minh, Bạch Gia Nguyệt và Lý Văn đang gọi món tại nhà hàng.","audio":"02-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"家月、李文，你们看看菜单，想吃点儿什么？","py":"Jiāyuè, Lǐ Wén, nǐmen kànkan càidān, xiǎng chī diǎnr shénme?","vi":"Gia Nguyệt, Lý Văn, hai em xem thực đơn đi, muốn ăn món gì vậy?"},{"section":"Bài khóa 1","context":"","audio":"02-1.mp3","speaker":"李文","name":"Lý Văn","zh":"谢谢一雪姐，我都可以，你们点吧。","py":"Xièxie Yīxuě jiě, wǒ dōu kěyǐ, nǐmen diǎn ba.","vi":"Cảm ơn chị Nhất Tuyết, em ăn gì cũng được, chị gọi món đi ạ."},{"section":"Bài khóa 1","context":"","audio":"02-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"飞了这么远，现在还真是又饿又渴。","py":"Fēile zhème yuǎn, xiànzài hái zhēn shì yòu è yòu kě.","vi":"Sau chuyến bay dài như vậy, em thực sự vừa đói vừa khát."},{"section":"Bài khóa 1","context":"","audio":"02-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"那多点点儿，别客气。你们喝什么饮料？","py":"Nà duō diǎn diǎnr, bié kèqi. Nǐmen hē shénme yǐnliào?","vi":"Vậy thì hãy gọi nhiều một chút, đừng ngại nhé. Các em muốn uống gì nào?"},{"section":"Bài khóa 1","context":"","audio":"02-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"好久没喝中国茶，也好久没吃饺子了。我想喝绿茶、吃饺子，可以吗？","py":"Hǎojiǔ méi hē Zhōngguó chá, yě hǎojiǔ méi chī jiǎozi le. Wǒ xiǎng hē lǜchá, chī jiǎozi, kěyǐ ma?","vi":"Lâu rồi em không được uống trà Trung Quốc, cũng lâu lắm rồi không được ăn sủi cảo. Em muốn uống trà xanh và ăn sủi cảo, có được không chị?"},{"section":"Bài khóa 1","context":"","audio":"02-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"没问题。你们看看还想吃什么。","py":"Méi wèntí. Nǐmen kànkan hái xiǎng chī shénme.","vi":"Không vấn đề gì. Các em xem có còn muốn dùng thêm gì nữa không nhé."},{"section":"Bài khóa 2","context":"在饭馆，王一雪、刘明、白家月和李文一起吃饭。Vương Nhất Tuyết, Lưu Minh, Bạch Gia Nguyệt và Lý Văn đang ăn cùng nhau tại nhà hàng.","audio":"02-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"服务员，再给我们拿一双筷子、一个勺子和一个碗。","py":"Fúwùyuán, zài gěi wǒmen ná yì shuāng kuàizi, yí gè sháozi hé yí gè wǎn.","vi":"Em ơi, cho chị xin thêm một đôi đũa, một cái thìa và một cái bát nhé."},{"section":"Bài khóa 2","context":"","audio":"02-3.mp3","speaker":"服务员","name":"Nhân viên phục vụ","zh":"好的，请等一下，我马上去拿。","py":"Hǎo de, qǐng děng yíxià, wǒ mǎshàng qù ná.","vi":"Vâng ạ. Xin vui lòng đợi một lát, em sẽ mang ra ngay."},{"section":"Bài khóa 2","context":"","audio":"02-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"这家饭馆的服务很热情，菜也都做得很好吃。你们尝尝，看喜不喜欢这些菜。","py":"Zhè jiā fànguǎn de fúwù hěn rèqíng, cài yě dōu zuò de hěn hǎochī. Nǐmen chángchang, kàn xǐ bu xǐhuan zhèxiē cài.","vi":"Nhà hàng này phục vụ rất nhiệt tình, các món ăn đều rất ngon. Các em ăn thử đi, xem có thích những món ăn này không."},{"section":"Bài khóa 2","context":"","audio":"02-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"哪个菜都好吃。您点的这些菜真不错。","py":"Nǎge cài dōu hǎochī. Nín diǎn de zhèxiē cài zhēn búcuò.","vi":"Món nào cũng ngon cả. Những món chị gọi thực sự rất tuyệt."},{"section":"Bài khóa 2","context":"","audio":"02-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"这里的饭菜又便宜又好吃，我们经常来，服务员都记住我们爱吃的菜了。","py":"Zhèlǐ de fàncài yòu piányi yòu hǎochī, wǒmen jīngcháng lái, fúwùyuán dōu jìzhù wǒmen ài chī de cài le.","vi":"Đồ ăn ở đây vừa rẻ lại vừa ngon, bọn chị thường xuyên đến đây nên nhân viên phục vụ đều nhớ rõ các món yêu thích của bọn chị."},{"section":"Bài khóa 2","context":"","audio":"02-3.mp3","speaker":"服务员","name":"Nhân viên phục vụ","zh":"王姐，您经常来吃饭，今天送您一些水果，请慢用。","py":"Wáng jiě, nín jīngcháng lái chīfàn, jīntiān sòng nín yìxiē shuǐguǒ, qǐng mànyòng.","vi":"Chị Vương ơi, chị thường tới đây dùng bữa, hôm nay nhà hàng xin tặng chị một ít trái cây, chúc chị ngon miệng!"},{"section":"Bài khóa 3","context":"在饭馆，王一雪、刘明、白家月和李文继续边吃边聊。Vương Nhất Tuyết, Lưu Minh, Bạch Gia Nguyệt và Lý Văn tiếp tục vừa ăn vừa trò chuyện trong nhà hàng.","audio":"02-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"这个鸡肉饭太好吃了，我要再来吃一次。","py":"Zhège jīròufàn tài hǎochī le, wǒ yào zài lái chī yí cì.","vi":"Món cơm gà này ngon quá, nhất định em sẽ quay lại ăn một lần nữa."},{"section":"Bài khóa 3","context":"","audio":"02-5.mp3","speaker":"李文","name":"Lý Văn","zh":"你可以拿走这张菜单，看看下次还吃点儿什么。","py":"Nǐ kěyǐ názǒu zhè zhāng càidān, kànkan xià cì hái chī diǎnr shénme.","vi":"Em có thể cầm lấy thực đơn này, xem lần tới còn muốn gọi món gì nữa."},{"section":"Bài khóa 3","context":"","audio":"02-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"不用拿菜单，在手机上就能看到，也可以选好了让他们给你送。","py":"Búyòng ná càidān, zài shǒujī shang jiù néng kàndào, yě kěyǐ xuǎnhǎo le ràng tāmen gěi nǐ sòng.","vi":"Không cần lấy thực đơn đâu, có thể xem trên điện thoại, cũng có thể chọn xong rồi bảo họ giao hàng tận nơi."},{"section":"Bài khóa 3","context":"","audio":"02-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"他们家还能送外卖？","py":"Tāmen jiā hái néng sòng wàimài?","vi":"Quán này có giao đồ ăn tận nơi sao?"},{"section":"Bài khóa 3","context":"","audio":"02-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"对，现在很多饭馆都能送外卖，想吃什么就点什么。","py":"Duì, xiànzài hěn duō fànguǎn dōu néng sòng wàimài, xiǎng chī shénme jiù diǎn shénme.","vi":"Đúng vậy! Ngày nay có rất nhiều nhà hàng cung cấp dịch vụ giao đồ ăn tận nơi, muốn ăn gì thì đặt món đó."},{"section":"Bài khóa 3","context":"","audio":"02-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"那真是太方便了！","py":"Nà zhēn shì tài fāngbiàn le!","vi":"Vậy thì thật sự quá tiện lợi ạ!"},{"section":"Bài khóa 4","context":"在李文家，李文在写日记。Lý Văn đang viết nhật ký ở trong nhà mình.","audio":"02-7.mp3","speaker":"李文","name":"Lý Văn","zh":"这些年在国外，我很少自己做饭。早饭我吃一个面包，有时候吃一块蛋糕，再喝一杯咖啡。午饭和晚饭也都在外面吃。快要考试的时候又忙又累，没时间出去吃饭，家里又什么吃的都没有，我可能好几天只吃方便面。现在回到中国了，每天能吃到妈妈做的饭，我真是太高兴了！有时候妈妈只做几个简单的菜，我也非常爱吃，因为什么都没有妈妈做的饭好吃。","py":"Zhèxiē nián zài guówài, wǒ hěn shǎo zìjǐ zuòfàn. Zǎofàn wǒ chī yí gè miànbāo, yǒu shíhou chī yí kuài dàngāo, zài hē yì bēi kāfēi. Wǔfàn hé wǎnfàn yě dōu zài wàimiàn chī. Kuài yào kǎoshì de shíhou yòu máng yòu lèi, méi shíjiān chūqù chīfàn, jiālǐ yòu shénme chī de dōu méiyǒu, wǒ kěnéng hǎo jǐ tiān zhǐ chī fāngbiànmiàn. Xiànzài huídào Zhōngguó le, měitiān néng chīdào māma zuò de fàn, wǒ zhēn shì tài gāoxìng le! Yǒu shíhou māma zhǐ zuò jǐ gè jiǎndān de cài, wǒ yě fēicháng ài chī, yīnwèi shénme dōu méiyǒu māma zuò de fàn hǎochī.","vi":"Ở nước ngoài mấy năm nay, tôi hiếm khi tự nấu ăn. Bữa sáng, tôi thường ăn một ổ bánh mì, đôi khi ăn một miếng bánh ngọt rồi uống một tách cà phê. Bữa trưa và bữa tối cũng đều ăn ngoài. Lúc sắp thi cử, tôi vừa bận vừa mệt, không có thời gian đi ra ngoài ăn cơm, trong nhà cũng chẳng có gì để ăn, mấy ngày liền tôi chỉ có thể ăn mì ăn liền. Bây giờ về Trung Quốc rồi, ngày nào cũng được ăn cơm mẹ nấu, tôi thật sự rất hạnh phúc! Đôi khi mẹ chỉ làm vài món ăn đơn giản, nhưng tôi cũng rất thích ăn, bởi vì không có gì ngon bằng cơm mẹ nấu."}],"dialogQuestions":[],"grammar":{"g1":{"han":"并列复句“又……又……”","py":"Bìngliè fùjù “yòu... yòu...”","title":"Câu ghép đẳng lập “又……又……”","explain":"并列复句“又……又……”与形容词搭配使用，表示人或者事物同时具有两个特点。基本结构：又+形容词1+又+形容词2。\nCâu ghép đẳng lập “又……又……” được sử dụng kết hợp với tính từ, biểu thị người hoặc sự vật đồng thời mang hai đặc điểm. Cấu trúc cơ bản: 又 + tính từ 1 + 又 + tính từ 2.","examples":[{"zh":"我现在还真是又饿又渴。","py":"Wǒ xiànzài hái zhēn shì yòu è yòu kě.","vi":"Bây giờ em thực sự vừa đói vừa khát.","hl":"又饿又渴"},{"zh":"那个女孩儿又高又漂亮。","py":"Nàge nǚháir yòu gāo yòu piàoliang.","vi":"Cô gái kia vừa cao vừa xinh đẹp.","hl":"又高又漂亮"},{"zh":"这个饭馆的菜又便宜又好吃。","py":"Zhège fànguǎn de cài yòu piányi yòu hǎochī.","vi":"Món ăn ở nhà hàng này vừa rẻ vừa ngon.","hl":"又便宜又好吃"}],"struct":"又 + Tính từ 1 + 又 + Tính từ 2","note":"Hai tính từ phải cùng tính chất tích cực hoặc cùng tiêu cực (tránh trộn tốt với xấu)."},"g2":{"han":"疑问代词的非疑问用法（2）","py":"Yíwèn dàicí de fēi yíwèn yòngfǎ (2)","title":"Cách dùng linh hoạt của đại từ nghi vấn (2)","explain":"疑问代词“哪、哪儿、什么、谁、怎么”等还可以用来表示任指，比如“谁”指任何一个人，“什么”指任何一件东西，句中常用副词“都”与之呼应。\nĐại từ nghi vấn “哪”, “哪儿”, “什么”, “谁”, “怎么”... còn có thể dùng để biểu thị ý nghĩa chỉ chung, ví dụ “谁” chỉ bất kỳ người nào, “什么” chỉ bất kỳ sự vật nào; thường dùng kết hợp với phó từ “都” trong câu.","examples":[{"zh":"哪个菜都好吃。","py":"Nǎge cài dōu hǎochī.","vi":"Món nào cũng ngon.","hl":"哪个……都"},{"zh":"这次旅游，我去哪儿都可以。","py":"Zhè cì lǚyóu, wǒ qù nǎr dōu kěyǐ.","vi":"Chuyến du lịch lần này tôi đi đâu cũng được.","hl":"哪儿都"},{"zh":"我下午有时间，你想什么时候来都没问题。","py":"Wǒ xiàwǔ yǒu shíjiān, nǐ xiǎng shénme shíhou lái dōu méi wèntí.","vi":"Buổi chiều tôi rảnh, bạn muốn đến lúc nào cũng không vấn đề gì.","hl":"什么时候都"}],"struct":"Đại từ nghi vấn + (... ) + 都 / 也 + Vị ngữ","note":"Diễn tả phạm vi toàn bộ (bất kỳ ai, bất kỳ cái gì, bất kỳ đâu... đều...)."},"g3":{"han":"疑问代词的非疑问用法（3）","py":"Yíwèn dàicí de fēi yíwèn yòngfǎ (3)","title":"Cách dùng linh hoạt của đại từ nghi vấn (3)","explain":"两个相同的疑问代词可以表示任指，前后呼应，指同一个人、同一件事、同一种方式、同一个时间、同一个地点等。当前后两个分句的主语相同时，后一分句的主语可以省略。当前后两个分句的主语不同时，第二个主语要放在“就”的前面。\nHai đại từ nghi vấn giống nhau có thể dùng để biểu thị ý nghĩa chỉ chung, chúng có sự tương ứng trước sau, chỉ cùng một người, một sự việc, một phương thức, một thời điểm... Khi chủ ngữ của hai phân câu giống nhau, chủ ngữ của phân câu sau có thể được lược bỏ. Khi chủ ngữ của hai phân câu khác nhau, chủ ngữ thứ hai cần đặt trước “就”.","examples":[{"zh":"你们想吃什么就点什么。","py":"Nǐmen xiǎng chī shénme jiù diǎn shénme.","vi":"Các em muốn ăn món gì thì gọi món đó.","hl":"什么……就……什么"},{"zh":"你觉得哪个好看就买哪个。","py":"Nǐ juéde nǎge hǎokàn jiù mǎi nǎge.","vi":"Bạn thấy cái nào đẹp thì mua cái đó.","hl":"哪个……就……哪个"},{"zh":"你想去哪儿，我们就去哪儿。","py":"Nǐ xiǎng qù nǎr, wǒmen jiù qù nǎr.","vi":"Em muốn đi đâu thì chúng ta đi đó.","hl":"哪儿……就……哪儿"}],"struct":"... (Đại từ nghi vấn) + (Chủ ngữ 2 +) 就 + ... (Cùng đại từ nghi vấn)","note":"Hai vế tương ứng theo nguyên tắc đồng nhất đối tượng được chọn."}},"grammarQuiz":[{"id":"hsk3_b2_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我觉得 (____) 筷子吃饭更方便。","opts":[{"t":"用","ok":true},{"t":"尝","ok":false},{"t":"只","ok":false},{"t":"菜单","ok":false},{"t":"记","ok":false}],"exp":"Đáp án E (用): ‘Tôi thấy dùng đũa ăn cơm tiện hơn.’"},{"id":"hsk3_b2_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"你 (____) 住那个饭馆的名字了吗？","opts":[{"t":"记","ok":true},{"t":"尝","ok":false},{"t":"只","ok":false},{"t":"菜单","ok":false},{"t":"用","ok":false}],"exp":"Đáp án D (记): ‘Bạn đã nhớ tên nhà hàng kia chưa?’"},{"id":"hsk3_b2_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"她现在很饿，早上 (____) 吃了一块蛋糕。","opts":[{"t":"只","ok":true},{"t":"尝","ok":false},{"t":"菜单","ok":false},{"t":"记","ok":false},{"t":"用","ok":false}],"exp":"Đáp án B (只): ‘Cô ấy giờ rất đói, buổi sáng chỉ ăn có một miếng bánh ngọt.’"},{"id":"hsk3_b2_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"(____) 上有好几个新菜，你看看我们吃哪个？","opts":[{"t":"菜单","ok":true},{"t":"尝","ok":false},{"t":"只","ok":false},{"t":"记","ok":false},{"t":"用","ok":false}],"exp":"Đáp án C (菜单): ‘Trên thực đơn có khá nhiều món mới, bạn xem chúng ta ăn món nào?’"},{"id":"hsk3_b2_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我妈妈会做中国菜，下次你们来我家 (____) 一下她做的菜。","opts":[{"t":"尝","ok":true},{"t":"只","ok":false},{"t":"菜单","ok":false},{"t":"记","ok":false},{"t":"用","ok":false}],"exp":"Đáp án A (尝): ‘Mẹ tôi biết nấu món Trung Quốc, lần tới các bạn qua nhà tôi nếm thử món mẹ tôi nấu nhé.’"},{"id":"hsk3_b2_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 我还不太会用筷子，你们有勺子吗？\nB: 有，你等一下，我 (____) 给你拿。","opts":[{"t":"马上","ok":true},{"t":"饿","ok":false},{"t":"不用","ok":false},{"t":"简单","ok":false},{"t":"好久","ok":false}],"exp":"Đáp án E (马上): ‘Có ạ, bạn đợi một chút, tôi mang ra cho bạn ngay.’"},{"id":"hsk3_b2_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 我找服务员要一下菜单，咱们点菜。\nB: 在手机上就可以点菜，(____) 要菜单。","opts":[{"t":"不用","ok":true},{"t":"饿","ok":false},{"t":"简单","ok":false},{"t":"好久","ok":false},{"t":"马上","ok":false}],"exp":"Đáp án B (不用): ‘Trên điện thoại có thể gọi món được rồi, không cần xin thực đơn đâu.’"},{"id":"hsk3_b2_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 我太 (____) 了，不想做饭了，我们叫个外卖，怎么样？\nB: 没问题，你想吃什么，我们就点什么。","opts":[{"t":"饿","ok":true},{"t":"不用","ok":false},{"t":"简单","ok":false},{"t":"好久","ok":false},{"t":"马上","ok":false}],"exp":"Đáp án A (饿): ‘Tôi đói quá rồi, không muốn nấu cơm nữa, mình đặt đồ ăn giao tận nơi nhé?’"},{"id":"hsk3_b2_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你想去哪个饭馆吃饭？\nB: 我 (____) 没吃饺子了，去楼下的饺子馆吧。","opts":[{"t":"好久","ok":true},{"t":"饿","ok":false},{"t":"不用","ok":false},{"t":"简单","ok":false},{"t":"马上","ok":false}],"exp":"Đáp án D (好久): ‘Tôi lâu lắm rồi chưa ăn sủi cảo, xuống quán sủi cảo dưới tầng đi.’"},{"id":"hsk3_b2_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你下班回家自己做饭吗？\nB: 不做饭，我就吃碗方便面。方便面是最 (____) 的晚饭。","opts":[{"t":"简单","ok":true},{"t":"饿","ok":false},{"t":"不用","ok":false},{"t":"好久","ok":false},{"t":"马上","ok":false}],"exp":"Đáp án C (简单): ‘Mì ăn liền là bữa tối đơn giản nhất.’"},{"id":"hsk3_b2_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"他们在做什么？","opts":[{"t":"C 在饭馆吃饭","ok":true},{"t":"A 买东西","ok":false},{"t":"B 在家吃饭","ok":false}],"exp":"Bốn người đang ngồi gọi món ăn tại nhà hàng."},{"id":"hsk3_b2_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"白家月想吃什么中国菜？","opts":[{"t":"A 饺子","ok":true},{"t":"B 包子","ok":false},{"t":"C 面条儿","ok":false}],"exp":"Bạch Gia Nguyệt nói: “我想喝绿茶、吃饺子，可以吗？”"},{"id":"hsk3_b2_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"王一雪让服务员拿什么？","opts":[{"t":"C 勺子、筷子和碗","ok":true},{"t":"A 筷子和碗","ok":false},{"t":"B 勺子和筷子","ok":false}],"exp":"Vương Nhất Tuyết nói: “再给我们拿一双筷子、一个勺子和一个碗。”"},{"id":"hsk3_b2_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"这家饭馆的服务怎么样？","opts":[{"t":"B 很热情","ok":true},{"t":"A 很慢","ok":false},{"t":"C 不太好","ok":false}],"exp":"Vương Nhất Tuyết nhận xét: “这家饭馆的服务很热情”."},{"id":"hsk3_b2_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"在这家饭馆，白家月喜欢吃什么？","opts":[{"t":"B 鸡肉饭","ok":true},{"t":"A 包子","ok":false},{"t":"C 面条儿","ok":false}],"exp":"Bạch Gia Nguyệt nói: “这个鸡肉饭太好吃了”."},{"id":"hsk3_b2_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"王一雪为什么说“不用拿菜单”？","opts":[{"t":"C 手机上可以看菜单","ok":true},{"t":"A 她有菜单","ok":false},{"t":"B 她不想再来","ok":false}],"exp":"Vương Nhất Tuyết nói: “不用拿菜单，在手机上就能看到”."},{"id":"hsk3_b2_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"快要考试的时候，李文怎么吃饭？","opts":[{"t":"A 吃方便面","ok":true},{"t":"B 出去吃饭","ok":false},{"t":"C 回妈妈家吃","ok":false}],"exp":"Bài khóa 4: “快要考试的时候...我可能好几天只吃方便面。”"},{"id":"hsk3_b2_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"回到中国了，李文为什么很高兴？","opts":[{"t":"C 每天能吃到妈妈做的饭","ok":true},{"t":"A 妈妈每天做很多菜","ok":false},{"t":"B 可以经常去外面吃饭","ok":false}],"exp":"Bài khóa 4: “每天能吃到妈妈做的饭，我真是太高兴了！”"}],"chars":["菜","单","又","饿","渴","客","气","饮","料","好","久","服","务","员","双","筷","子","勺","碗","马","上","热","情","尝","记","用","鸡","张","不","选","外","卖","方","便","蛋","糕","只","面","简","你","们","想","吃","什","么","就","点"],"rhyme":null,"notes":["Tiểu Ngữ giúp sức (trang 14): “上/下+量词”主要用来表示时间顺序，“上”表示过去，“下”表示将来。例如：上次/下次、上周/下周、上个月/下个月。Cấu trúc “上/下 + lượng từ” chủ yếu được dùng để biểu thị trình tự thời gian; “上” biểu thị quá khứ, “下” biểu thị tương lai. Ví dụ: 上次 (lần trước)/下次 (lần sau), 上周 (tuần trước)/下周 (tuần sau), 上个月 (tháng trước)/下个月 (tháng sau).","Món quà của Tiểu Ngữ (trang 18, video 2-1): 筷子 — Đũa.","Câu hỏi thảo luận Bài khóa 1: (1) 白家月现在觉得怎么样？ (2) 白家月想喝什么？ (3) 王一雪要点什么？","Câu hỏi thảo luận Bài khóa 2: (1) 王一雪觉得这家饭馆怎么样？ (2) 白家月觉得饭馆的菜怎么样？ (3) 服务员为什么送了一些水果？","Câu hỏi thảo luận Bài khóa 3: (1) 白家月为什么要再来吃一次？ (2) 这家饭馆可以怎么点菜？ (3) 听说很多饭馆都能送外卖，白家月觉得怎么样？","Câu hỏi thảo luận Bài khóa 4: (1) 李文在国外经常做饭吗？ (2) 李文为什么好几天只吃方便面？ (3) 回到中国后什么事让他非常高兴？"],"workbook":null},"3":{"pages":"19–28","titleZh":"这个小区挺好的","titlePy":"Zhège xiǎoqū tǐng hǎo de","titleVi":"Khu dân cư này khá tốt","goals":["能听懂并谈论居住环境和居家情况。Có thể nghe hiểu và thảo luận được về môi trường sống và tình hình sinh hoạt trong gia đình.","能听懂并使用“挺”“坏了”表达程度。Có thể nghe hiểu và sử dụng được “挺” và “坏了” để biểu đạt mức độ.","掌握“就”和“才”的用法，能表达动作发生的早晚、快慢等信息。Nắm vững cách dùng của “就” và “才” để biểu đạt thời điểm sớm hay muộn, nhanh hay chậm của hành động."],"words":[{"zh":"初中","py":"chūzhōng","vi":"trung học cơ sở, cấp hai","pos":"dt."},{"zh":"咱们","py":"zánmen","vi":"chúng ta","pos":"đt."},{"zh":"换","py":"huàn","vi":"thay, thay đổi, đổi","pos":"đgt."},{"zh":"房子","py":"fángzi","vi":"nhà, căn nhà","pos":"dt."},{"zh":"小区","py":"xiǎoqū","vi":"khu dân cư, khu nhà ở","pos":"dt."},{"zh":"环境","py":"huánjìng","vi":"môi trường","pos":"dt."},{"zh":"挺","py":"tǐng","vi":"khá, rất","pos":"phó."},{"zh":"空调","py":"kōngtiáo","vi":"máy điều hoà","pos":"dt."},{"zh":"洗衣机","py":"xǐyījī","vi":"máy giặt","pos":"dt."},{"zh":"层","py":"céng","vi":"tầng","pos":"lượng."},{"zh":"花园","py":"huāyuán","vi":"vườn hoa","pos":"dt."},{"zh":"灯","py":"dēng","vi":"đèn","pos":"dt."},{"zh":"关","py":"guān","vi":"tắt, đóng","pos":"đgt."},{"zh":"冰箱","py":"bīngxiāng","vi":"tủ lạnh","pos":"dt."},{"zh":"卫生间","py":"wèishēngjiān","vi":"nhà vệ sinh","pos":"dt."},{"zh":"打扫","py":"dǎsǎo","vi":"dọn dẹp, quét dọn","pos":"đgt."},{"zh":"搬家","py":"bānjiā","vi":"chuyển nhà","pos":"đgt."},{"zh":"办","py":"bàn","vi":"làm, xử lý","pos":"đgt."},{"zh":"信用卡","py":"xìnyòngkǎ","vi":"thẻ tín dụng","pos":"dt."},{"zh":"还","py":"huán","vi":"trả, hoàn trả","pos":"đgt."},{"zh":"听说","py":"tīngshuō","vi":"nghe nói","pos":"đgt."},{"zh":"银行","py":"yínháng","vi":"ngân hàng","pos":"dt."},{"zh":"才","py":"cái","vi":"(mãi)... mới","pos":"phó."},{"zh":"纸","py":"zhǐ","vi":"giấy","pos":"dt."},{"zh":"搬","py":"bān","vi":"chuyển, mang, bê","pos":"đgt."},{"zh":"需要","py":"xūyào","vi":"cần, cần thiết, nhu cầu","pos":"đgt./dt."}],"dialog":[{"section":"Bài khóa 1","context":"在家里，刘明和王一雪在聊天儿。Lưu Minh và Vương Nhất Tuyết đang trò chuyện trong nhà.","audio":"03-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"小雪的初中离家有点儿远，咱们换一个近点儿的房子吧。","py":"Xiǎoxuě de chūzhōng lí jiā yǒudiǎnr yuǎn, zánmen huàn yí gè jìn diǎnr de fángzi ba.","vi":"Trường cấp 2 của Tiểu Tuyết khá xa nhà, chúng ta hãy chuyển nhà đến gần đó hơn đi."},{"section":"Bài khóa 1","context":"","audio":"03-1.mp3","speaker":"刘明","name":"Lưu Minh","zh":"好啊，我上网看看。你觉得这个小区怎么样？","py":"Hǎo a, wǒ shàngwǎng kànkan. Nǐ juéde zhège xiǎoqū zěnmeyàng?","vi":"Được em nhé, anh sẽ lên mạng xem. Em thấy khu dân cư này thế nào?"},{"section":"Bài khóa 1","context":"","audio":"03-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"环境挺好的，离地铁站还不远。","py":"Huánjìng tǐng hǎo de, lí dìtiězhàn hái bù yuǎn.","vi":"Môi trường khá ổn, cũng không xa ga tàu điện ngầm lắm."},{"section":"Bài khóa 1","context":"","audio":"03-1.mp3","speaker":"刘明","name":"Lưu Minh","zh":"房子里面也不错，空调和洗衣机都是新的。","py":"Fángzi lǐmian yě búcuò, kōngtiáo hé xǐyījī dōu shì xīn de.","vi":"Bên trong căn hộ trông cũng không tồi, điều hoà và máy giặt đều là đồ mới."},{"section":"Bài khóa 1","context":"","audio":"03-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"是不错，但是我不喜欢住一层。","py":"Shì búcuò, dànshì wǒ bù xǐhuan zhù yì céng.","vi":"Cũng khá ổn đấy, nhưng em không thích sống ở tầng một."},{"section":"Bài khóa 1","context":"","audio":"03-1.mp3","speaker":"刘明","name":"Lưu Minh","zh":"这个一层带一个小花园，我觉得咱们可以去看看。","py":"Zhège yì céng dài yí gè xiǎo huāyuán, wǒ juéde zánmen kěyǐ qù kànkan.","vi":"Căn hộ tầng một này có một khu vườn nhỏ, anh nghĩ chúng ta nên đến xem thử."},{"section":"Bài khóa 2","context":"在新家，王一雪在收拾房间，刘明进来了。Vương Nhất Tuyết đang dọn dẹp trong nhà mới thì Lưu Minh bước vào.","audio":"03-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"我今天早上来的时候，灯还开着。","py":"Wǒ jīntiān zǎoshang lái de shíhou, dēng hái kāizhe.","vi":"Sáng nay khi em tới, đèn vẫn còn đang bật."},{"section":"Bài khóa 2","context":"","audio":"03-3.mp3","speaker":"刘明","name":"Lưu Minh","zh":"我这几天忙坏了，可能走的时候忘关了。","py":"Wǒ zhè jǐ tiān máng huài le, kěnéng zǒu de shíhou wàng guān le.","vi":"Mấy ngày nay anh bận tối mắt tối mũi, chắc lúc đi quên tắt đèn rồi."},{"section":"Bài khóa 2","context":"","audio":"03-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"冰箱不能用，这些吃的东西放在哪儿？","py":"Bīngxiāng bù néng yòng, zhèxiē chī de dōngxi fàng zài nǎr?","vi":"Tủ lạnh không dùng được, đống đồ ăn này giờ phải để đâu đây?"},{"section":"Bài khóa 2","context":"","audio":"03-3.mp3","speaker":"刘明","name":"Lưu Minh","zh":"不可能吧？冰箱是新买的，我来看看。","py":"Bù kěnéng ba? Bīngxiāng shì xīn mǎi de, wǒ lái kànkan.","vi":"Không thể nào? Tủ lạnh vừa mới mua mà, để anh xem thử."},{"section":"Bài khóa 2","context":"","audio":"03-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"洗衣机也坏了吗？","py":"Xǐyījī yě huài le ma?","vi":"Có phải máy giặt cũng hỏng rồi không?"},{"section":"Bài khóa 2","context":"","audio":"03-3.mp3","speaker":"刘明","name":"Lưu Minh","zh":"没坏，但是卫生间没打扫好，还不能洗衣服。","py":"Méi huài, dànshì wèishēngjiān méi dǎsǎohǎo, hái bù néng xǐ yīfu.","vi":"Không, nhưng phòng vệ sinh vẫn chưa dọn sạch nên chưa thể giặt đồ được."},{"section":"Bài khóa 2","context":"","audio":"03-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"星期天我们真的能搬家吗？","py":"Xīngqītiān wǒmen zhēn de néng bānjiā ma?","vi":"Liệu Chủ nhật này chúng ta có thể dọn đến đây không?"},{"section":"Bài khóa 3","context":"在家里，刘明和王一雪在客厅聊天儿。Lưu Minh và Vương Nhất Tuyết đang trò chuyện trong phòng khách ở nhà.","audio":"03-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"这个月花了不少钱。","py":"Zhège yuè huāle bù shǎo qián.","vi":"Tháng này đã tiêu khá nhiều tiền rồi đấy."},{"section":"Bài khóa 3","context":"","audio":"03-5.mp3","speaker":"刘明","name":"Lưu Minh","zh":"是的，我们买了很多搬家时要用的东西。","py":"Shì de, wǒmen mǎile hěn duō bānjiā shí yào yòng de dōngxi.","vi":"Đúng vậy, mình đã mua rất nhiều thứ để dùng khi chuyển nhà mà."},{"section":"Bài khóa 3","context":"","audio":"03-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"咱们办张信用卡吧，花的钱可以慢慢还。听说中国银行的服务不错，办了信用卡买东西还能便宜。","py":"Zánmen bàn zhāng xìnyòngkǎ ba, huā de qián kěyǐ mànman huán. Tīngshuō Zhōngguó Yínháng de fúwù búcuò, bànle xìnyòngkǎ mǎi dōngxi hái néng piányi.","vi":"Chúng ta hãy làm thẻ tín dụng đi, như vậy tiền tiêu có thể trả dần được. Nghe nói dịch vụ của Ngân hàng Trung Quốc khá tốt, lại còn được giảm giá khi mua sắm bằng thẻ tín dụng nữa."},{"section":"Bài khóa 3","context":"","audio":"03-5.mp3","speaker":"刘明","name":"Lưu Minh","zh":"好啊！中国银行很近，走路几分钟就能到。咱们什么时候去？","py":"Hǎo a! Zhōngguó Yínháng hěn jìn, zǒulù jǐ fēnzhōng jiù néng dào. Zánmen shénme shíhou qù?","vi":"Tuyệt! Ngân hàng Trung Quốc rất gần đây, chỉ mất vài phút đi bộ thôi. Khi nào chúng ta đi vậy?"},{"section":"Bài khóa 3","context":"","audio":"03-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"今天下午？","py":"Jīntiān xiàwǔ?","vi":"Chiều nay thì sao?"},{"section":"Bài khóa 3","context":"","audio":"03-5.mp3","speaker":"刘明","name":"Lưu Minh","zh":"我下午要去医院，很晚才能回来。","py":"Wǒ xiàwǔ yào qù yīyuàn, hěn wǎn cái néng huílái.","vi":"Chiều nay anh phải đến bệnh viện, phải khá muộn anh mới về được."},{"section":"Bài khóa 3","context":"","audio":"03-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"那我下午自己去吧。","py":"Nà wǒ xiàwǔ zìjǐ qù ba.","vi":"Vậy chiều nay em sẽ tự đi vậy."},{"section":"Bài khóa 4","context":"在家里，刘明和王一雪讨论搬家计划。Lưu Minh và Vương Nhất Tuyết đang ở trong nhà thảo luận về kế hoạch chuyển nhà.","audio":"03-7.mp3","speaker":"刘明","name":"Lưu Minh","zh":"我觉得这个星期就能搬家。我明天去买一些纸箱，很快就能准备好。搬家那天，我想请几位朋友来帮忙，最多一天就能搬完。","py":"Wǒ juéde zhège xīngqī jiù néng bānjiā. Wǒ míngtiān qù mǎi yìxiē zhǐxiāng, hěn kuài jiù néng zhǔnbèi hǎo. Bānjiā nà tiān, wǒ xiǎng qǐng jǐ wèi péngyou lái bāngmáng, zuìduō yì tiān jiù néng bānwán.","vi":"Anh nghĩ chúng ta có thể chuyển nhà trong tuần này. Ngày mai anh sẽ mua một ít thùng giấy, chuẩn bị một lát là xong ngay. Vào ngày chuyển nhà, anh định nhờ vài người bạn đến giúp, nhiều nhất chỉ mất một ngày là chuyển xong."},{"section":"Bài khóa 4","context":"","audio":"03-7.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"我觉得下个月才能搬家。这周开始准备，下周去打扫新家，这么多事情最少需要两个星期才能做完。搬家那天，我们应该找一家搬家公司。","py":"Wǒ juéde xià gè yuè cái néng bānjiā. Zhè zhōu kāishǐ zhǔnbèi, xià zhōu qù dǎsǎo xīn jiā, zhème duō shìqing zuìshǎo xūyào liǎng gè xīngqī cái néng zuòwán. Bānjiā nà tiān, wǒmen yīnggāi zhǎo yì jiā bānjiā gōngsī.","vi":"Em nghĩ phải tháng sau chúng ta mới có thể chuyển nhà được. Tuần này mình bắt đầu chuẩn bị, tuần sau dọn dẹp nhà mới. Bao nhiêu việc phải làm nên chúng ta cần ít nhất hai tuần để hoàn tất mọi thứ. Vào ngày chuyển nhà, chúng ta nên thuê một công ty chuyển nhà."}],"dialogQuestions":[],"grammar":{"g1":{"han":"程度副词“挺”","py":"Chéngdù fùcí “tǐng”","title":"Phó từ chỉ mức độ “挺”","explain":"程度副词“挺”用在形容词或心理动词前，表示程度较高，常用于口语中。基本结构：挺+形容词/心理动词+的。\nPhó từ chỉ mức độ “挺” thường dùng trong văn nói, đặt trước tính từ hoặc động từ chỉ tâm lý để biểu thị mức độ tương đối cao. Cấu trúc cơ bản: 挺 + tính từ/động từ chỉ tâm lý + 的.","examples":[{"zh":"这个小区环境挺好的。","py":"Zhège xiǎoqū huánjìng tǐng hǎo de.","vi":"Môi trường khu dân cư này khá tốt.","hl":"挺好的"},{"zh":"这家饭馆的菜挺好吃的。","py":"Zhè jiā fànguǎn de cài tǐng hǎochī de.","vi":"Món ăn ở nhà hàng này khá ngon.","hl":"挺好吃的"},{"zh":"买这个吧，我挺喜欢这个颜色的。","py":"Mǎi zhège ba, wǒ tǐng xǐhuan zhège yánsè de.","vi":"Mua cái này đi, tôi khá thích màu này đấy.","hl":"挺喜欢……的"}],"struct":"挺 + Tính từ / Động từ tâm lý + 的","note":"Thường đi kèm trợ từ ngữ khí “的” ở cuối câu để câu nói tự nhiên hơn."},"g2":{"han":"程度补语（1）","py":"Chéngdù bǔyǔ (1)","title":"Bổ ngữ trình độ (1)","explain":"程度补语“坏了”用在形容词的后面，表示程度非常高，带有夸张的语气，常用在负面的情况中。\nBổ ngữ trình độ “坏了” đặt sau tính từ, biểu thị mức độ rất cao, mang ngữ khí cường điệu, thường dùng trong các tình huống tiêu cực.","examples":[{"zh":"我这几天忙坏了。","py":"Wǒ zhè jǐ tiān máng huài le.","vi":"Mấy ngày nay anh bận chết đi được (bận tối mắt tối mũi).","hl":"忙坏了"},{"zh":"我渴坏了，哪里能买水？","py":"Wǒ kě huài le, nǎlǐ néng mǎi shuǐ?","vi":"Tôi khát khô cổ rồi, ở đâu mua được nước thế?","hl":"渴坏了"},{"zh":"这几天非常忙，大家都累坏了。","py":"Zhè jǐ tiān fēicháng máng, dàjiā dōu lèi huài le.","vi":"Mấy hôm nay rất bận, mọi người đều mệt rã rời rồi.","hl":"累坏了"}],"struct":"Tính từ + 坏了","note":"Mang sắc thái nhấn mạnh cực độ (mệt rã rời, bận tối mặt, đói cồn cào...)."},"g3":{"han":"“就”和“才”","py":"“Jiù” hé “Cái”","title":"Phó từ “就” và “才”","explain":"副词“就”和“才”用在动词前面作状语，“就”表示说话人认为动作发生得早，进行得快、顺利；“才”表示说话人认为动作发生得晚，进行得慢、不顺利。\nPhó từ “就” và “才” đặt trước động từ làm trạng ngữ. “就” biểu thị hành động xảy ra sớm hoặc được thực hiện nhanh, thuận lợi theo nhận định của người nói; “才” biểu thị hành động xảy ra muộn hoặc được thực hiện chậm, không thuận lợi theo nhận định của người nói.","examples":[{"zh":"中国银行很近，走路几分钟就能到。","py":"Zhōngguó Yínháng hěn jìn, zǒulù jǐ fēnzhōng jiù néng dào.","vi":"Ngân hàng Trung Quốc rất gần, đi bộ vài phút là có thể đến ngay.","hl":"就"},{"zh":"我下午要去医院，很晚才能回来。","py":"Wǒ xiàwǔ yào qù yīyuàn, hěn wǎn cái néng huílái.","vi":"Chiều nay anh phải đến bệnh viện, rất muộn mới về được.","hl":"才"},{"zh":"我早上五点就起床了。","py":"Wǒ zǎoshang wǔ diǎn jiù qǐchuáng le.","vi":"Sáng 5 giờ tôi đã dậy rồi.","hl":"就"},{"zh":"坐火车去北京，五个小时才能到。","py":"Zuò huǒchē qù Běijīng, wǔ gè xiǎoshí cái néng dào.","vi":"Đi tàu hỏa đến Bắc Kinh, mất 5 tiếng mới tới được.","hl":"才"}],"struct":"Thời gian / Số lượng + 就 + Động từ (sớm/nhanh/dễ) | Thời gian / Số lượng + 才 + Động từ (muộn/lâu/khó)","note":"Lưu ý: Cuối câu dùng “才” thường không thêm trợ từ ngữ khí “了” khi diễn đạt thời gian muộn."}},"grammarQuiz":[{"id":"hsk3_b3_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"你走的时候要 (____) 灯。","opts":[{"t":"关","ok":true},{"t":"才","ok":false},{"t":"挺","ok":false},{"t":"办","ok":false},{"t":"还","ok":false}],"exp":"Đáp án D (关): ‘Lúc bạn đi nhớ tắt đèn.’"},{"id":"hsk3_b3_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我要去银行 (____) 一张信用卡。","opts":[{"t":"办","ok":true},{"t":"才","ok":false},{"t":"挺","ok":false},{"t":"关","ok":false},{"t":"还","ok":false}],"exp":"Đáp án C (办): ‘Tôi muốn ra ngân hàng làm một tấm thẻ tín dụng.’"},{"id":"hsk3_b3_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"搬家要准备的东西 (____) 多的。","opts":[{"t":"挺","ok":true},{"t":"才","ok":false},{"t":"办","ok":false},{"t":"关","ok":false},{"t":"还","ok":false}],"exp":"Đáp án B (挺): ‘Đồ đạc cần chuẩn bị khi chuyển nhà khá nhiều đấy.’"},{"id":"hsk3_b3_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"这本书不是我的，明天我要 (____) 给朋友。","opts":[{"t":"还","ok":true},{"t":"才","ok":false},{"t":"挺","ok":false},{"t":"办","ok":false},{"t":"关","ok":false}],"exp":"Đáp án E (还): ‘Quyển sách này không phải của tôi, ngày mai tôi phải trả lại cho bạn.’"},{"id":"hsk3_b3_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我太忙了，没时间打扫新家，可能下个月 (____) 搬家。","opts":[{"t":"才","ok":true},{"t":"挺","ok":false},{"t":"办","ok":false},{"t":"关","ok":false},{"t":"还","ok":false}],"exp":"Đáp án A (才): ‘Tôi bận quá, chưa có thời gian dọn nhà mới, có lẽ tháng sau mới chuyển nhà.’"},{"id":"hsk3_b3_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你去哪儿了？怎么这么晚才回来？\nB: 我一直在 (____) 新家，今天真是累坏了。","opts":[{"t":"打扫","ok":true},{"t":"环境","ok":false},{"t":"需要","ok":false},{"t":"搬家","ok":false},{"t":"听说","ok":false}],"exp":"Đáp án E (打扫): ‘Tôi luôn dọn dẹp nhà mới, hôm nay đúng là mệt rã rời.’"},{"id":"hsk3_b3_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 这个小区离学校有点儿远。\nB: 虽然有点儿远，但是我们很喜欢这个小区的 (____)。","opts":[{"t":"环境","ok":true},{"t":"需要","ok":false},{"t":"搬家","ok":false},{"t":"听说","ok":false},{"t":"打扫","ok":false}],"exp":"Đáp án A (环境): ‘Tuy hơi xa một chút nhưng chúng tôi rất thích môi trường của khu dân cư này.’"},{"id":"hsk3_b3_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你知道她为什么不喜欢这个房子吗？\nB: 我 (____) 她不喜欢住一层。","opts":[{"t":"听说","ok":true},{"t":"环境","ok":false},{"t":"需要","ok":false},{"t":"搬家","ok":false},{"t":"打扫","ok":false}],"exp":"Đáp án D (听说): ‘Tôi nghe nói cô ấy không thích ở tầng một.’"},{"id":"hsk3_b3_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 这个小区明天不能 (____)，你知道吗？\nB: 我知道，我已经告诉搬家公司的人了，他们下周一再来。","opts":[{"t":"搬家","ok":true},{"t":"环境","ok":false},{"t":"需要","ok":false},{"t":"听说","ok":false},{"t":"打扫","ok":false}],"exp":"Đáp án C (搬家): ‘Ngày mai khu dân cư này không cho chuyển nhà, bạn biết không?’"},{"id":"hsk3_b3_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 她家真大，还有个大花园。\nB: 因为她家人多，(____) 一个大房子。","opts":[{"t":"需要","ok":true},{"t":"环境","ok":false},{"t":"搬家","ok":false},{"t":"听说","ok":false},{"t":"打扫","ok":false}],"exp":"Đáp án B (需要): ‘Vì nhà cô ấy đông người nên cần một ngôi nhà lớn.’"},{"id":"hsk3_b3_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"王一雪和刘明想做什么？","opts":[{"t":"A 换房子","ok":true},{"t":"B 买空调","ok":false},{"t":"C 去女儿的初中","ok":false}],"exp":"Vương Nhất Tuyết nói: “咱们换一个近点儿的房子吧。”"},{"id":"hsk3_b3_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"王一雪为什么不喜欢这个房子？","opts":[{"t":"B 她不喜欢住一层","ok":true},{"t":"A 房子太远","ok":false},{"t":"C 她不喜欢这个小区","ok":false}],"exp":"Vương Nhất Tuyết nói: “是不错，但是我不喜欢住一层。”"},{"id":"hsk3_b3_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"灯为什么开着？","opts":[{"t":"C 刘明走的时候忘关了","ok":true},{"t":"A 灯坏了","ok":false},{"t":"B 是王一雪打开的","ok":false}],"exp":"Lưu Minh nói: “可能走的时候忘关了。”"},{"id":"hsk3_b3_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"现在新家是什么样的？","opts":[{"t":"C 卫生间没打扫好","ok":true},{"t":"A 冰箱是旧的","ok":false},{"t":"B 洗衣机是坏的","ok":false}],"exp":"Lưu Minh nói: “冰箱是新买的...没坏，但是卫生间没打扫好，还不能洗衣服。”"},{"id":"hsk3_b3_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"王一雪和刘明为什么这个月花了不少钱？","opts":[{"t":"C 买了很多搬家要用的东西","ok":true},{"t":"A 买衣服了","ok":false},{"t":"B 去饭店吃饭了","ok":false}],"exp":"Lưu Minh nói: “是的，我们买了很多搬家时要用的东西。”"},{"id":"hsk3_b3_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"王一雪想去中国银行做什么？","opts":[{"t":"C 办信用卡","ok":true},{"t":"A 买东西","ok":false},{"t":"B 还信用卡","ok":false}],"exp":"Vương Nhất Tuyết nói: “咱们办张信用卡吧...”"},{"id":"hsk3_b3_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"刘明想什么时候搬家？","opts":[{"t":"B 这个星期","ok":true},{"t":"A 明天","ok":false},{"t":"C 下个星期","ok":false}],"exp":"Lưu Minh nói: “我觉得这个星期就能搬家。”"},{"id":"hsk3_b3_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"王一雪想什么时候搬家？","opts":[{"t":"C 下个月","ok":true},{"t":"A 这周","ok":false},{"t":"B 下周","ok":false}],"exp":"Vương Nhất Tuyết nói: “我觉得下个月才能搬家。”"}],"chars":["初","中","咱","们","换","房","子","小","区","环","境","挺","空","调","洗","衣","机","层","花","园","灯","关","冰","箱","卫","生","间","打","扫","搬","家","办","信","用","卡","还","听","说","银","行","才","纸","需","要","这","个","好","的"],"rhyme":null,"notes":["Món quà của Tiểu Ngữ (trang 27, video 3-1): 在中国租房 — Thuê nhà tại Trung Quốc.","Tổng kết học tập Bài 1–3 (trang 27–28): 9 điểm ngữ pháp gồm 看上去/看起来, 疑问代词的非疑问用法(1)(2)(3), 多项定语, 又……又……, 挺, 程度补语(1) 坏了, 就 và 才.","Câu hỏi thảo luận Bài khóa 1: (1) 他们为什么要换房子？ (2) 王一雪觉得新小区怎么样？ (3) 刘明为什么喜欢这个房子？","Câu hỏi thảo luận Bài khóa 2: (1) 他们家的冰箱怎么了？ (2) 为什么不能洗衣服？ (3) 你觉得星期天他们能不能搬家？为什么？","Câu hỏi thảo luận Bài khóa 3: (1) 王一雪为什么想办信用卡？ (2) 王一雪想什么时候去银行？ (3) 刘明为什么今天不能去银行？","Câu hỏi thảo luận Bài khóa 4: (1) 刘明明天去买什么？ (2) 王一雪打算下周做什么？ (3) 刘明打算找谁搬家？王一雪呢？"],"workbook":null},"4":{"pages":"29–37","titleZh":"这家宾馆跟别的都不一样","titlePy":"Zhè jiā bīnguǎn gēn biéde dōu bù yíyàng","titleVi":"Khách sạn này không giống như những khách sạn khác","goals":["能听懂并谈论假期计划，能表达旅游过程中的感受。Có thể nghe hiểu và thảo luận kế hoạch kỳ nghỉ, có thể diễn đạt được cảm nhận trong quá trình du lịch.","能听懂并表达完全否定的意义。Có thể nghe hiểu và diễn đạt được ý nghĩa của phủ định hoàn toàn.","掌握“除了”的用法，能表达排除或补充的意义。Nắm vững cách sử dụng của “除了” để biểu đạt ý nghĩa loại trừ hoặc bổ sung."],"words":[{"zh":"假期","py":"jiàqī","vi":"kỳ nghỉ","pos":"dt."},{"zh":"海","py":"hǎi","vi":"biển","pos":"dt."},{"zh":"草原","py":"cǎoyuán","vi":"thảo nguyên","pos":"dt."},{"zh":"主意","py":"zhǔyi","vi":"ý tưởng","pos":"dt."},{"zh":"骑","py":"qí","vi":"cưỡi","pos":"đgt."},{"zh":"马","py":"mǎ","vi":"ngựa","pos":"dt."},{"zh":"羊","py":"yáng","vi":"cừu, dê","pos":"dt."},{"zh":"月亮","py":"yuèliang","vi":"mặt trăng","pos":"dt."},{"zh":"一定","py":"yídìng","vi":"nhất định, chắc chắn","pos":"phó."},{"zh":"刻","py":"kè","vi":"khắc (15 phút)","pos":"lượng."},{"zh":"起飞","py":"qǐfēi","vi":"cất cánh","pos":"đgt."},{"zh":"宾馆","py":"bīnguǎn","vi":"khách sạn","pos":"dt."},{"zh":"特别","py":"tèbié","vi":"đặc biệt, rất, vô cùng","pos":"tt./phó."},{"zh":"别的","py":"biéde","vi":"khác","pos":"đt."},{"zh":"一样","py":"yíyàng","vi":"giống nhau","pos":"tt."},{"zh":"牛","py":"niú","vi":"bò","pos":"dt."},{"zh":"相机","py":"xiàngjī","vi":"máy ảnh","pos":"dt."},{"zh":"欢迎","py":"huānyíng","vi":"chào đón, hoan nghênh","pos":"đgt."},{"zh":"司机","py":"sījī","vi":"tài xế","pos":"dt."},{"zh":"晚点","py":"wǎndiǎn","vi":"muộn, muộn giờ, trễ giờ","pos":"đgt."},{"zh":"久","py":"jiǔ","vi":"lâu","pos":"tt."},{"zh":"除了","py":"chúle","vi":"ngoài... (ra), trừ... (ra)","pos":"giới."},{"zh":"以外","py":"yǐwài","vi":"(ngoài)... ra","pos":"dt."},{"zh":"先","py":"xiān","vi":"trước, trước tiên","pos":"phó."},{"zh":"一直","py":"yìzhí","vi":"luôn luôn, suốt","pos":"phó."},{"zh":"干净","py":"gānjìng","vi":"sạch, sạch sẽ","pos":"tt."},{"zh":"满意","py":"mǎnyì","vi":"hài lòng","pos":"đgt."}],"dialog":[{"section":"Bài khóa 1","context":"在王一飞家客厅，杨同乐和王一飞在聊天儿。Dương Đồng Lạc và Vương Nhất Phi đang trò chuyện trong phòng khách nhà Vương Nhất Phi.","audio":"04-1.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"这个假期咱们去哪儿玩玩吧。","py":"Zhège jiàqī zánmen qù nǎr wánwan ba.","vi":"Kỳ nghỉ này mình đi đâu chơi đi."},{"section":"Bài khóa 1","context":"","audio":"04-1.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"好啊，你想去哪儿，咱们就去哪儿。","py":"Hǎo a, nǐ xiǎng qù nǎr, zánmen jiù qù nǎr.","vi":"Được đấy, anh muốn đi đâu thì mình sẽ đi đó."},{"section":"Bài khóa 1","context":"","audio":"04-1.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"你喜欢海，找个海边住几天，怎么样？","py":"Nǐ xǐhuan hǎi, zhǎo gè hǎibiān zhù jǐ tiān, zěnmeyàng?","vi":"Em thích biển, hay là mình tìm chỗ nào gần biển ở lại vài ngày nhé?"},{"section":"Bài khóa 1","context":"","audio":"04-1.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"现在去海边有点儿冷。","py":"Xiànzài qù hǎibiān yǒudiǎnr lěng.","vi":"Bây giờ mà đi biển thì hơi lạnh."},{"section":"Bài khóa 1","context":"","audio":"04-1.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"那去草原吧？草原一点儿也不冷。","py":"Nà qù cǎoyuán ba? Cǎoyuán yìdiǎnr yě bù lěng.","vi":"Vậy đi thảo nguyên đi. Ở vùng thảo nguyên không lạnh chút nào cả."},{"section":"Bài khóa 1","context":"","audio":"04-1.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"这个主意好！我好久没骑马了。","py":"Zhège zhǔyi hǎo! Wǒ hǎojiǔ méi qímǎ le.","vi":"Ý kiến này thật tuyệt! Đã lâu lắm rồi em không được cưỡi ngựa."},{"section":"Bài khóa 1","context":"","audio":"04-1.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"对，在草原上骑马、吃羊肉、看月亮，一定很有意思。","py":"Duì, zài cǎoyuán shang qímǎ, chī yángròu, kàn yuèliang, yídìng hěn yǒu yìsi.","vi":"Đúng rồi, cưỡi ngựa, ăn thịt cừu và ngắm trăng trên thảo nguyên chắc chắn sẽ rất tuyệt vời."},{"section":"Bài khóa 2","context":"在王一飞家客厅，杨同乐和王一飞在聊天儿。Dương Đồng Lạc và Vương Nhất Phi đang trò chuyện trong phòng khách nhà Vương Nhất Phi.","audio":"04-3.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"出去玩的机票买好了吗？","py":"Chūqù wán de jīpiào mǎihǎo le ma?","vi":"Em đã mua vé máy bay cho chuyến đi của chúng ta chưa?"},{"section":"Bài khóa 2","context":"","audio":"04-3.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"买好了。星期六上午十点一刻起飞。","py":"Mǎihǎo le. Xīngqīliù shàngwǔ shí diǎn yí kè qǐfēi.","vi":"Em mua xong rồi ạ. Chuyến bay khởi hành lúc 10 giờ 15 phút sáng thứ Bảy."},{"section":"Bài khóa 2","context":"","audio":"04-3.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"宾馆也选好了吗？","py":"Bīnguǎn yě xuǎnhǎo le ma?","vi":"Em đã chọn được khách sạn chưa?"},{"section":"Bài khóa 2","context":"","audio":"04-3.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"是的，这家宾馆很特别，跟别的都不一样，一出门就能看见牛和羊！","py":"Shì de, zhè jiā bīnguǎn hěn tèbié, gēn biéde dōu bù yíyàng, yì chūmén jiù néng kànjiàn niú hé yáng!","vi":"Rồi ạ, khách sạn này không giống những khách sạn khác, nó rất đặc biệt, bước ra khỏi khách sạn là có thể nhìn thấy bò và cừu!"},{"section":"Bài khóa 2","context":"","audio":"04-3.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"太好了！你看看要带什么东西？","py":"Tài hǎo le! Nǐ kànkan yào dài shénme dōngxi?","vi":"Tuyệt quá! Em xem chúng mình cần mang theo những gì nào."},{"section":"Bài khóa 2","context":"","audio":"04-3.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"我们不用带太多东西，别忘了拿上新买的相机。","py":"Wǒmen búyòng dài tài duō dōngxi, bié wàngle náshàng xīn mǎi de xiàngjī.","vi":"Mình không cần mang quá nhiều đồ đâu, đừng quên mang chiếc máy ảnh mới mua là được."},{"section":"Bài khóa 2","context":"","audio":"04-3.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"一定不会忘带的。我现在就去准备行李。","py":"Yídìng bú huì wàng dài de. Wǒ xiànzài jiù qù zhǔnbèi xíngli.","vi":"Chắc chắn sẽ không quên mang theo đâu. Bây giờ anh đi thu dọn hành lý đây."},{"section":"Bài khóa 3","context":"在机场，杨同乐和王一飞走出来，跟他们预约的司机兼导游见面。Dương Đồng Lạc và Vương Nhất Phi đi ra phía ngoài sân bay và gặp lái xe kiêm hướng dẫn viên mà họ đã đặt trước.","audio":"04-5.mp3","speaker":"小李","name":"Tiểu Lý","zh":"欢迎你们！我是你们的司机，我姓李，叫我小李就可以。","py":"Huānyíng nǐmen! Wǒ shì nǐmen de sījī, wǒ xìng Lǐ, jiào wǒ Xiǎo Lǐ jiù kěyǐ.","vi":"Chào mừng quý khách! Em là tài xế của anh chị, em họ Lý, cứ gọi em là Tiểu Lý."},{"section":"Bài khóa 3","context":"","audio":"04-5.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"您好！不好意思，飞机晚点了，让您久等了。","py":"Nín hǎo! Bù hǎoyìsi, fēijī wǎndiǎn le, ràng nín jiǔ děng le.","vi":"Chào em! Xin lỗi vì chuyến bay của chúng tôi bị hoãn nên em đã phải đợi lâu."},{"section":"Bài khóa 3","context":"","audio":"04-5.mp3","speaker":"小李","name":"Tiểu Lý","zh":"没关系。除了这个行李箱以外，还有别的东西吗？","py":"Méi guānxi. Chúle zhège xínglixiāng yǐwài, hái yǒu biéde dōngxi ma?","vi":"Không sao ạ. Ngoài chiếc va li này ra, anh chị còn đồ gì khác không?"},{"section":"Bài khóa 3","context":"","audio":"04-5.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"还有一个包，我自己拿就可以。","py":"Hái yǒu yí gè bāo, wǒ zìjǐ ná jiù kěyǐ.","vi":"Chỉ còn một chiếc túi nữa thôi, anh tự xách được."},{"section":"Bài khóa 3","context":"","audio":"04-5.mp3","speaker":"小李","name":"Tiểu Lý","zh":"车在一层，请跟我来。","py":"Chē zài yì céng, qǐng gēn wǒ lái.","vi":"Xe đang đỗ ở tầng một, mời anh chị đi theo em."},{"section":"Bài khóa 3","context":"","audio":"04-5.mp3","speaker":"杨同乐","name":"Dương Đồng Lạc","zh":"我们住的宾馆离机场远吗？","py":"Wǒmen zhù de bīnguǎn lí jīchǎng yuǎn ma?","vi":"Khách sạn của chúng tôi có xa sân bay không?"},{"section":"Bài khóa 3","context":"","audio":"04-5.mp3","speaker":"小李","name":"Tiểu Lý","zh":"不远，三十分钟就能到。两位到了可以先休息休息，晚饭的时候我叫你们。","py":"Bù yuǎn, sānshí fēnzhōng jiù néng dào. Liǎng wèi dào le kěyǐ xiān xiūxi xiūxi, wǎnfàn de shíhou wǒ jiào nǐmen.","vi":"Không xa đâu, khoảng ba mươi phút là đến. Sau khi đến nơi, anh chị có thể nghỉ ngơi một lát trước, em sẽ gọi cho anh chị khi đến giờ ăn tối."},{"section":"Bài khóa 4","context":"在宾馆房间，王一飞在写日记。Vương Nhất Phi đang viết nhật ký ở trong phòng khách sạn.","audio":"04-7.mp3","speaker":"王一飞","name":"Vương Nhất Phi","zh":"今天是我们旅游的第一天。我们很早就起床去机场了，没想到飞机晚点了。我们到的时候，天已经黑了，但是司机小李一直在机场等我们，一点儿也没着急。他特别热情，路上给我们介绍了很多东西，还准备了水果。宾馆的房间跟我想的一样漂亮，又大又干净，我非常满意。","py":"Jīntiān shì wǒmen lǚyóu de dì-yī tiān. Wǒmen hěn zǎo jiù qǐchuáng qù jīchǎng le, méi xiǎngdào fēijī wǎndiǎn le. Wǒmen dào de shíhou, tiān yǐjīng hēi le, dànshì sījī Xiǎo Lǐ yìzhí zài jīchǎng děng wǒmen, yìdiǎnr yě méi zháojí. Tā tèbié rèqíng, lùshang gěi wǒmen jièshàole hěn duō dōngxi, hái zhǔnbèile shuǐguǒ. Bīnguǎn de fángjiān gēn wǒ xiǎng de yíyàng piàoliang, yòu dà yòu gānjìng, wǒ fēicháng mǎnyì.","vi":"Hôm nay là ngày đầu tiên của chuyến du lịch. Chúng tôi đã dậy rất sớm để ra sân bay, nào ngờ đâu chuyến bay lại bị trễ. Khi chúng tôi tới nơi thì trời đã tối, nhưng tài xế của chúng tôi, Tiểu Lý, vẫn đợi chúng tôi ở sân bay mà không hề tỏ ra mất kiên nhẫn. Tiểu Lý vô cùng nhiệt tình, dọc đường đã kể cho chúng tôi nghe rất nhiều thứ, còn chuẩn bị sẵn một ít trái cây. Phòng khách sạn cũng đẹp đúng như tôi tưởng tượng, vừa rộng rãi, vừa sạch sẽ, tôi rất hài lòng về nó."}],"dialogQuestions":[],"grammar":{"g1":{"han":"固定格式“一……也/都+不/没……”","py":"Gùdìng géshì “yī... yě/dōu + bù/méi...”","title":"Cấu trúc cố định “一……也/都+不/没……”","explain":"固定格式“一……也/都+不/没……”表示完全否定。有时候，“一+量词”还可以用“一点儿”来表示。当谓语是形容词时，通常用“一点儿也/都+不/没+形容词”表示完全否定。\nCấu trúc cố định “一……也/都 + 不/没……” biểu thị ý nghĩa phủ định hoàn toàn. “一 + lượng từ” đôi khi có thể được thay bằng “一点儿”. Khi vị ngữ là tính từ, thường dùng cấu trúc “一点儿也/都 + 不/没 + tính từ” để biểu thị phủ định hoàn toàn.","examples":[{"zh":"她一件衣服都不想买。","py":"Tā yí jiàn yīfu dōu bù xiǎng mǎi.","vi":"Cô ấy một bộ quần áo cũng không muốn mua.","hl":"一件……都不"},{"zh":"我一个中国电影也没看过。","py":"Wǒ yí gè Zhōngguó diànyǐng yě méi kànguo.","vi":"Tôi chưa từng xem một bộ phim Trung Quốc nào cả.","hl":"一个……也没"},{"zh":"我一点儿东西也不想吃。","py":"Wǒ yìdiǎnr dōngxi yě bù xiǎng chī.","vi":"Tôi chẳng muốn ăn chút đồ nào cả.","hl":"一点儿……也不"},{"zh":"草原一点儿也不冷。","py":"Cǎoyuán yìdiǎnr yě bù lěng.","vi":"Thảo nguyên chẳng lạnh chút nào.","hl":"一点儿也不"}],"struct":"一 + Lượng từ + Danh từ + 也/都 + 不/没 + Động từ | 一点儿 + (Danh từ +) 也/都 + 不/没 + Động từ / Tính từ","note":"Nhấn mạnh mức độ phủ định tuyệt đối (hoàn toàn không)."},"g2":{"han":"比较句（9）","py":"Bǐjiàojù (9)","title":"Câu so sánh (9)","explain":"比较句“A跟B一样”表示A和B比较后，结果相同。“一样”的后面可以用形容词表示比较的某一方面，基本结构：A跟B一样+形容词。否定形式是在“一样”的前面加“不”。\nCâu so sánh “A 跟 B 一样” biểu đạt A và B có kết quả giống nhau sau khi so sánh. Sau “一样” có thể dùng tính từ để biểu thị một phương diện so sánh nào đó. Cấu trúc cơ bản: A 跟 B 一样 + tính từ. Hình thức phủ định thêm “不” trước “一样”.","examples":[{"zh":"这家宾馆跟别的都不一样。","py":"Zhè jiā bīnguǎn gēn biéde dōu bù yíyàng.","vi":"Khách sạn này không giống như những khách sạn khác.","hl":"跟……不一样"},{"zh":"他买的新手机跟我的一样。","py":"Tā mǎi de xīn shǒujī gēn wǒ de yíyàng.","vi":"Chiếc điện thoại mới anh ấy mua giống cái của tôi.","hl":"跟……一样"},{"zh":"这个房间跟那个房间一样大。","py":"Zhège fángjiān gēn nàge fángjiān yíyàng dà.","vi":"Căn phòng này rộng bằng căn phòng kia.","hl":"跟……一样大"}],"struct":"A + 跟 + B + (不) 一样 (+ Tính từ)","note":"Dùng “跟” hoặc “和” đều được; khi có từ chỉ tính chất, đặt tính từ ngay sau “一样”."},"g3":{"han":"固定格式“除了……（以外），……都/还/也……”","py":"Gùdìng géshì “chúle... (yǐwài), ... dōu/hái/yě...”","title":"Cấu trúc cố định “除了……（以外），……都/还/也……”","explain":"“除了……（以外），……都……”表示在一个范围内，排除一部分，其他的都存在相同的情况，其中“以外”可以省略。“除了……（以外），……还/也……”表示排除一部分，补充其他的。句子的主语放在句首，或者放在“还/也”的前面。\nCấu trúc “除了……（以外），……都……” dùng để diễn đạt ý nghĩa sau khi đã loại trừ một phần, những phần còn lại đều giống nhau trong một phạm vi nào đó, “以外” có thể lược bỏ. Cấu trúc “除了……（以外），……还/也……” biểu thị loại trừ một phần và bổ sung thêm phần khác.","examples":[{"zh":"除了我以外，大家都在玩手机。","py":"Chúle wǒ yǐwài, dàjiā dōu zài wán shǒujī.","vi":"Ngoài tôi ra, mọi người đều đang nghịch điện thoại.","hl":"除了……以外，……都"},{"zh":"除了这个汉字，别的汉字我都会写。","py":"Chúle zhège Hànzì, biéde Hànzì wǒ dōu huì xiě.","vi":"Trừ chữ Hán này ra, các chữ Hán khác tôi đều biết viết.","hl":"除了……，……都"},{"zh":"除了这个行李箱以外，还有别的东西吗？","py":"Chúle zhège xínglixiāng yǐwài, hái yǒu biéde dōngxi ma?","vi":"Ngoài chiếc va li này ra, còn đồ gì khác không?","hl":"除了……以外，还"},{"zh":"除了唱歌以外，他也喜欢跳舞。","py":"Chúle chànggē yǐwài, tā yě xǐhuan tiàowǔ.","vi":"Ngoài ca hát ra, anh ấy cũng thích nhảy múa.","hl":"除了……以外，……也"}],"struct":"除了 + A + (以外)，+ B + 都 + ... (loại trừ) | 除了 + A + (以外)，+ ... + 还/也 + ... (bổ sung)","note":"Phân biệt rõ cặp phó từ “都” (ngoại trừ A thì phần còn lại đều) và “还/也” (ngoài A ra còn có thêm)."}},"grammarQuiz":[{"id":"hsk3_b4_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"已经八点一 (____) 了，快起床吧。","opts":[{"t":"刻","ok":true},{"t":"先","ok":false},{"t":"久","ok":false},{"t":"满意","ok":false},{"t":"特别","ok":false}],"exp":"Đáp án C (刻): ‘Đã 8 giờ 15 phút rồi, mau dậy đi.’"},{"id":"hsk3_b4_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"飞机晚点了，小李在机场等了很 (____)。","opts":[{"t":"久","ok":true},{"t":"先","ok":false},{"t":"刻","ok":false},{"t":"满意","ok":false},{"t":"特别","ok":false}],"exp":"Đáp án B (久): ‘Máy bay bị trễ, Tiểu Lý đã đợi ở sân bay rất lâu.’"},{"id":"hsk3_b4_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我 (____) 打车过去，你们可以慢慢走过去。","opts":[{"t":"先","ok":true},{"t":"久","ok":false},{"t":"刻","ok":false},{"t":"满意","ok":false},{"t":"特别","ok":false}],"exp":"Đáp án A (先): ‘Tôi bắt xe đi sang trước, các bạn có thể thong thả đi bộ qua.’"},{"id":"hsk3_b4_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我对这里的服务非常 (____)，下次还会再来。","opts":[{"t":"满意","ok":true},{"t":"先","ok":false},{"t":"久","ok":false},{"t":"刻","ok":false},{"t":"特别","ok":false}],"exp":"Đáp án D (满意): ‘Tôi rất hài lòng với dịch vụ ở đây, lần sau sẽ lại đến.’"},{"id":"hsk3_b4_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我们这次在草原上住的宾馆很 (____)，跟别的都不一样。","opts":[{"t":"特别","ok":true},{"t":"先","ok":false},{"t":"久","ok":false},{"t":"刻","ok":false},{"t":"满意","ok":false}],"exp":"Đáp án E (特别): ‘Khách sạn lần này chúng tôi ở trên thảo nguyên rất đặc biệt, không giống những nơi khác.’"},{"id":"hsk3_b4_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 草原真是太漂亮了，跟我想的 (____)。\nB: 我觉得草原比我想的更漂亮。","opts":[{"t":"一样","ok":true},{"t":"一直","ok":false},{"t":"一定","ok":false},{"t":"欢迎","ok":false},{"t":"别的","ok":false}],"exp":"Đáp án B (一样): ‘Thảo nguyên đẹp quá, giống hệt như tôi tưởng tượng.’"},{"id":"hsk3_b4_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 我们搬家了，(____) 你来我们的新家玩。\nB: 好啊，有时间我一定去。","opts":[{"t":"欢迎","ok":true},{"t":"一直","ok":false},{"t":"一样","ok":false},{"t":"一定","ok":false},{"t":"别的","ok":false}],"exp":"Đáp án D (欢迎): ‘Chúng tôi chuyển nhà rồi, chào đón bạn đến nhà mới của chúng tôi chơi.’"},{"id":"hsk3_b4_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 除了要买几个纸箱，还买 (____) 东西吗？\nB: 没有了，谢谢你帮我买。","opts":[{"t":"别的","ok":true},{"t":"一直","ok":false},{"t":"一样","ok":false},{"t":"一定","ok":false},{"t":"欢迎","ok":false}],"exp":"Đáp án E (别的): ‘Ngoài mấy thùng giấy ra có mua đồ gì khác nữa không?’"},{"id":"hsk3_b4_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 喂，小李，这边天气不好，我们还没起飞呢。\nB: 没关系，我会 (____) 在机场等您。","opts":[{"t":"一直","ok":true},{"t":"一样","ok":false},{"t":"一定","ok":false},{"t":"欢迎","ok":false},{"t":"别的","ok":false}],"exp":"Đáp án A (一直): ‘Không sao đâu, em sẽ luôn đợi anh chị ở sân bay.’"},{"id":"hsk3_b4_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 行李准备好了，你看看还需要带什么东西？\nB: (____) 别忘了带护照。","opts":[{"t":"一定","ok":true},{"t":"一直","ok":false},{"t":"一样","ok":false},{"t":"欢迎","ok":false},{"t":"别的","ok":false}],"exp":"Đáp án C (一定): ‘Nhất định đừng quên mang hộ chiếu.’"},{"id":"hsk3_b4_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"王一飞和杨同乐在说什么？","opts":[{"t":"C 假期做什么","ok":true},{"t":"A 明天的天气","ok":false},{"t":"B 喜欢吃什么","ok":false}],"exp":"Hai người đang bàn bạc kỳ nghỉ này đi đâu chơi (“这个假期咱们去哪儿玩玩吧”)."},{"id":"hsk3_b4_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"杨同乐觉得草原怎么样？","opts":[{"t":"C 草原很有意思","ok":true},{"t":"A 草原天气不好","ok":false},{"t":"B 草原比海边冷","ok":false}],"exp":"Dương Đồng Lạc nói: “在草原上骑马、吃羊肉、看月亮，一定很有意思。”"},{"id":"hsk3_b4_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"王一飞觉得这次出去玩要带什么东西？","opts":[{"t":"B 带新买的相机","ok":true},{"t":"A 什么都不用带","ok":false},{"t":"C 要带很多东西","ok":false}],"exp":"Vương Nhất Phi nói: “我们不用带太多东西，别忘了拿上新买的相机。”"},{"id":"hsk3_b4_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"杨同乐现在去做什么？","opts":[{"t":"C 准备行李","ok":true},{"t":"A 买机票","ok":false},{"t":"B 选宾馆","ok":false}],"exp":"Dương Đồng Lạc nói: “我现在就去准备行李。”"},{"id":"hsk3_b4_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"小李是谁？","opts":[{"t":"B 同乐的司机","ok":true},{"t":"A 同乐的朋友","ok":false},{"t":"C 宾馆的服务员","ok":false}],"exp":"Tiểu Lý tự giới thiệu: “我是你们的司机，我姓李，叫我小李就可以。”"},{"id":"hsk3_b4_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"他们到宾馆后先做什么？","opts":[{"t":"A 休息","ok":true},{"t":"B 吃晚饭","ok":false},{"t":"C 等朋友","ok":false}],"exp":"Tiểu Lý nói: “两位到了可以先休息休息，晚饭的时候我叫你们。”"},{"id":"hsk3_b4_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"飞机晚点后，司机做什么了？","opts":[{"t":"C 一直在机场等","ok":true},{"t":"A 去宾馆了","ok":false},{"t":"B 去买水果了","ok":false}],"exp":"Bài khóa 4: “但是司机小李一直在机场等我们，一点儿也没着急。”"},{"id":"hsk3_b4_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"他们是什么时候到的？","opts":[{"t":"C 晚上","ok":true},{"t":"A 上午","ok":false},{"t":"B 中午","ok":false}],"exp":"Bài khóa 4: “我们到的时候，天已经黑了...” (trời đã tối tức buổi tối)."}],"chars":["假","期","海","草","原","主","意","骑","马","羊","月","亮","一","定","刻","起","飞","宾","馆","特","别","的","样","牛","相","机","欢","迎","司","晚","点","久","除","了","以","外","先","直","干","净","满","这","家","跟","都","不"],"rhyme":null,"notes":["Câu hỏi thảo luận Bài khóa 1: (1) 王一飞为什么不想去海边？ (2) 王一飞为什么觉得去草原好？ (3) 他们在草原上可以做什么？","Câu hỏi thảo luận Bài khóa 2: (1) 他们什么时候坐飞机出去玩？ (2) 王一飞选的宾馆怎么样？ (3) 杨同乐说一定不会忘带什么？","Câu hỏi thảo luận Bài khóa 3: (1) 他们为什么到晚了？ (2) 他们有几个行李箱？ (3) 宾馆离机场远吗？","Câu hỏi thảo luận Bài khóa 4: (1) 他们是怎么去宾馆的？ (2) 王一飞为什么觉得小李很热情？ (3) 宾馆的房间怎么样？"],"workbook":null},"5":{"pages":"38–46","titleZh":"这样的照片才好看","titlePy":"Zhèyàng de zhàopiàn cái hǎokàn","titleVi":"Những bức ảnh như thế này mới đẹp","goals":["能听懂并介绍自己喜欢的休闲生活。Có thể nghe hiểu và giới thiệu được về hoạt động giải trí yêu thích của bản thân.","能听懂并表达两个动作行为接连发生。Có thể nghe hiểu và diễn đạt được hai hành động xảy ra liên tiếp.","掌握存现句（3）的用法，能表达人或事物的出现或消失。Nắm vững cách dùng của câu tồn hiện (3) để miêu tả sự xuất hiện hoặc biến mất của người hoặc sự vật."],"words":[{"zh":"总是","py":"zǒngshì","vi":"luôn luôn","pos":"phó."},{"zh":"终于","py":"zhōngyú","vi":"cuối cùng","pos":"phó."},{"zh":"爬","py":"pá","vi":"leo, leo trèo","pos":"đgt."},{"zh":"山","py":"shān","vi":"núi đồi","pos":"dt."},{"zh":"锻炼","py":"duànliàn","vi":"tập luyện, tập thể dục","pos":"đgt."},{"zh":"照","py":"zhào","vi":"chụp (ảnh)","pos":"đgt."},{"zh":"鞋","py":"xié","vi":"giầy","pos":"dt."},{"zh":"大衣","py":"dàyī","vi":"áo khoác","pos":"dt."},{"zh":"拍照","py":"pāizhào","vi":"chụp ảnh","pos":"đgt."},{"zh":"感兴趣","py":"gǎn xìngqù","vi":"hứng thú, có hứng thú (với)","pos":""},{"zh":"照相","py":"zhàoxiàng","vi":"chụp ảnh","pos":"đgt."},{"zh":"难看","py":"nánkàn","vi":"xấu, khó coi","pos":"tt."},{"zh":"比较","py":"bǐjiào","vi":"so sánh, tương đối","pos":"đgt./phó."},{"zh":"水平","py":"shuǐpíng","vi":"trình độ, mức","pos":"dt."},{"zh":"太阳","py":"tàiyáng","vi":"mặt trời","pos":"dt."},{"zh":"树","py":"shù","vi":"cây","pos":"dt."},{"zh":"干","py":"gàn","vi":"làm","pos":"đgt."},{"zh":"电","py":"diàn","vi":"điện","pos":"dt."},{"zh":"收到","py":"shōudào","vi":"nhận được","pos":"đgt."},{"zh":"封","py":"fēng","vi":"bức, lá (thư)","pos":"lượng."},{"zh":"邮件","py":"yóujiàn","vi":"email, thư điện tử","pos":"dt."},{"zh":"难过","py":"nánguò","vi":"buồn, buồn rầu","pos":"tt."},{"zh":"哈哈","py":"hāhā","vi":"ha ha (tiếng cười)","pos":""},{"zh":"音乐","py":"yīnyuè","vi":"âm nhạc","pos":"dt."},{"zh":"兴趣","py":"xìngqù","vi":"hứng thú","pos":"dt."},{"zh":"会","py":"huì","vi":"buổi gặp mặt, bữa tiệc","pos":"dt."},{"zh":"结束","py":"jiéshù","vi":"kết thúc","pos":"đgt."}],"dialog":[{"section":"Bài khóa 1","context":"在街上，白家月和李文边散步边聊天儿。Bạch Gia Nguyệt và Lý Văn vừa đi dạo vừa trò chuyện trên đường phố.","audio":"05-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"这个星期总是阴天，今天终于晴了。","py":"Zhège xīngqī zǒngshì yīntiān, jīntiān zhōngyú qíng le.","vi":"Cả tuần nay trời đều âm u, cuối cùng hôm nay hửng nắng lên rồi."},{"section":"Bài khóa 1","context":"","audio":"05-1.mp3","speaker":"李文","name":"Lý Văn","zh":"现在天气好得很！我们去爬山怎么样？","py":"Xiànzài tiānqì hǎo de hěn! Wǒmen qù páshān zěnmeyàng?","vi":"Thời tiết bây giờ thật tuyệt vời! Hôm nay chúng mình đi leo núi, em thấy thế nào?"},{"section":"Bài khóa 1","context":"","audio":"05-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"好啊！又能锻炼身体，又能照好看的照片。","py":"Hǎo a! Yòu néng duànliàn shēntǐ, yòu néng zhào hǎokàn de zhàopiàn.","vi":"Được nhé! Vừa có thể tập thể dục vừa có thể chụp được ảnh đẹp."},{"section":"Bài khóa 1","context":"","audio":"05-1.mp3","speaker":"李文","name":"Lý Văn","zh":"那我带点儿水和吃的，咱们现在就去？","py":"Nà wǒ dài diǎnr shuǐ hé chī de, zánmen xiànzài jiù qù?","vi":"Vậy anh sẽ mang theo một ít nước và đồ ăn nhé. Chúng mình đi luôn bây giờ à?"},{"section":"Bài khóa 1","context":"","audio":"05-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我回去穿上运动鞋，拿上大衣。要不要叫一雪姐一起去？","py":"Wǒ huíqù chuānshàng yùndòngxié, náshàng dàyī. Yào bu yào jiào Yīxuě jiě yìqǐ qù?","vi":"Em quay về thay giày thể thao, lấy áo khoác. Chúng mình có nên rủ chị Nhất Tuyết đi cùng không?"},{"section":"Bài khóa 1","context":"","audio":"05-1.mp3","speaker":"李文","name":"Lý Văn","zh":"好主意。给她打个电话吧。","py":"Hǎo zhǔyi. Gěi tā dǎ gè diànhuà ba.","vi":"Ý kiến hay đó. Hãy gọi điện cho chị ấy đi."},{"section":"Bài khóa 2","context":"在出租车上，王一雪和白家月在聊天儿。Vương Nhất Tuyết và Bạch Gia Nguyệt đang trò chuyện trên xe taxi.","audio":"05-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"这些照片是谁给您照的？张张都非常好看。","py":"Zhèxiē zhàopiàn shì shéi gěi nín zhào de? Zhāngzhāng dōu fēicháng hǎokàn.","vi":"Ai đã chụp những bức ảnh này cho chị vậy? Tấm nào trông cũng đẹp."},{"section":"Bài khóa 2","context":"","audio":"05-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"一飞。她对拍照一直很感兴趣，经常给我照相。","py":"Yīfēi. Tā duì pāizhào yìzhí hěn gǎn xìngqù, jīngcháng gěi wǒ zhàoxiàng.","vi":"Nhất Phi đấy. Em ấy luôn hứng thú với nhiếp ảnh và thường xuyên chụp ảnh cho chị."},{"section":"Bài khóa 2","context":"","audio":"05-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我喜欢您大笑的这张，看起来很漂亮。","py":"Wǒ xǐhuan nín dàxiào de zhè zhāng, kàn qǐlái hěn piàoliang.","vi":"Em thực sự thích tấm chị đang cười to này, trông chị rất xinh."},{"section":"Bài khóa 2","context":"","audio":"05-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"我觉得这张有点儿难看，那时候我不知道她在给我照相。","py":"Wǒ juéde zhè zhāng yǒudiǎnr nánkàn, nà shíhou wǒ bù zhīdào tā zài gěi wǒ zhàoxiàng.","vi":"Chị cảm thấy tấm này hơi xấu, lúc đó chị không biết Nhất Phi đang chụp ảnh chị."},{"section":"Bài khóa 2","context":"","audio":"05-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"这样的照片才好看。我也喜欢拍照，爬山的时候我给您照几张照片吧。","py":"Zhèyàng de zhàopiàn cái hǎokàn. Wǒ yě xǐhuan pāizhào, páshān de shíhou wǒ gěi nín zhào jǐ zhāng zhàopiàn ba.","vi":"Những bức ảnh như thế này mới đẹp ạ. Em cũng thích chụp ảnh, khi đi leo núi em sẽ chụp vài tấm cho chị nhé."},{"section":"Bài khóa 2","context":"","audio":"05-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"好，我可以比较一下你们两个谁的水平高。","py":"Hǎo, wǒ kěyǐ bǐjiào yíxià nǐmen liǎng gè shéi de shuǐpíng gāo.","vi":"Được, vậy chị có thể so sánh xem ai trong hai em có trình độ chụp ảnh cao hơn."},{"section":"Bài khóa 3","context":"在山上，王一雪和白家月边走边聊。Vương Nhất Tuyết và Bạch Gia Nguyệt vừa đi vừa trò chuyện ở trên núi.","audio":"05-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"家月，这里挺漂亮的，咱们在这里拍照吧。","py":"Jiāyuè, zhèlǐ tǐng piàoliang de, zánmen zài zhèlǐ pāizhào ba.","vi":"Gia Nguyệt, ở đây đẹp thật đấy, mình chụp vài tấm ở đây đi."},{"section":"Bài khóa 3","context":"","audio":"05-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"这边没有太阳，咱们去那边吧。","py":"Zhèbian méiyǒu tàiyáng, zánmen qù nàbian ba.","vi":"Bên này không có nắng, mình qua bên kia đi."},{"section":"Bài khóa 3","context":"","audio":"05-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"好。你觉得我站在这些树中间怎么样？","py":"Hǎo. Nǐ juéde wǒ zhàn zài zhèxiē shù zhōngjiān zěnmeyàng?","vi":"Được thôi. Em thấy chị đứng giữa những cái cây này thì thế nào?"},{"section":"Bài khóa 3","context":"","audio":"05-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"挺好的。等一下，后边走过去两个人。","py":"Tǐng hǎo de. Děng yíxià, hòubian zǒu guòqù liǎng gè rén.","vi":"Đẹp đấy. Chị đợi một lát, phía sau chị có hai người đang đi qua."},{"section":"Bài khóa 3","context":"","audio":"05-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"我准备好了，你照的时候告诉我。","py":"Wǒ zhǔnbèihǎo le, nǐ zhào de shíhou gàosu wǒ.","vi":"Chị sẵn sàng rồi, hãy nói cho chị biết khi nào em chụp nhé."},{"section":"Bài khóa 3","context":"","audio":"05-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"你不用看着我，想干什么都可以。","py":"Nǐ búyòng kànzhe wǒ, xiǎng gàn shénme dōu kěyǐ.","vi":"Chị không cần phải nhìn em đâu, cứ làm gì thấy tự nhiên nhất là được."},{"section":"Bài khóa 3","context":"","audio":"05-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"树上飞来了几只鸟，我就看它们吧。","py":"Shùshang fēi láile jǐ zhī niǎo, wǒ jiù kàn tāmen ba.","vi":"Có mấy con chim vừa bay tới đậu trên cây, vậy chị sẽ ngắm chúng nhé."},{"section":"Bài khóa 3","context":"","audio":"05-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"啊，手机没电了。","py":"A, shǒujī méi diàn le.","vi":"Ôi, điện thoại hết pin mất rồi."},{"section":"Bài khóa 4","context":"在咖啡厅里，王一雪给白家月发短信。Vương Nhất Tuyết gửi tin nhắn cho Bạch Gia Nguyệt trong quán cà phê.","audio":"05-7.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"家月，我收到了你的那封邮件，也看到了你给我照的照片，张张都很漂亮。我已经告诉了一飞，你的拍照水平比她高，她难过得很，哈哈。不知道你对中国的音乐有没有兴趣？我送你一张明天下午音乐会的门票。音乐会七点多结束，你听完了音乐会就来我家吃饭，尝尝我做的中国菜。你觉得怎么样？","py":"Jiāyuè, wǒ shōudàole nǐ de nà fēng yóujiàn, yě kàndàole nǐ gěi wǒ zhào de zhàopiàn, zhāngzhāng dōu hěn piàoliang. Wǒ yǐjīng gàosule Yīfēi, nǐ de pāizhào shuǐpíng bǐ tā gāo, tā nánguò de hěn, hāhā. Bù zhīdào nǐ duì Zhōngguó de yīnyuè yǒu méiyǒu xìngqù? Wǒ sòng nǐ yì zhāng míngtiān xiàwǔ yīnyuèhuì de ménpiào. Yīnyuèhuì qī diǎn duō jiéshù, nǐ tīngwánle yīnyuèhuì jiù lái wǒ jiā chīfàn, chángchang wǒ zuò de Zhōngguó cài. Nǐ juéde zěnmeyàng?","vi":"Chào Gia Nguyệt, chị đã nhận được email của em và xem những bức ảnh em chụp cho chị, tấm nào cũng đẹp cả. Chị đã nói với Nhất Phi rằng trình độ chụp ảnh của em tốt hơn cô ấy, cô ấy rất buồn về chuyện đó đấy, ha ha. Không biết em có hứng thú với âm nhạc Trung Hoa không. Chị tặng em một chiếc vé vào cửa của buổi hoà nhạc chiều mai. Buổi hoà nhạc hơn 7 giờ mới kết thúc, nghe xong buổi hoà nhạc thì em đến nhà chị ăn cơm nhé, thưởng thức món ăn Trung Quốc do chị nấu. Em thấy sao?"}],"dialogQuestions":[],"grammar":{"g1":{"han":"程度补语（2）","py":"Chéngdù bǔyǔ (2)","title":"Bổ ngữ trình độ (2)","explain":"程度补语“得很”用在形容词的后面，表示程度高，一般用在口语中。\nBổ ngữ trình độ “得很” thường dùng trong văn nói, đặt sau tính từ, biểu thị mức độ cao.","examples":[{"zh":"现在天气好得很。","py":"Xiànzài tiānqì hǎo de hěn.","vi":"Thời tiết bây giờ đẹp cực kỳ.","hl":"得很"},{"zh":"房间里面热得很。","py":"Fángjiān lǐmian rè de hěn.","vi":"Trong phòng nóng lắm.","hl":"得很"},{"zh":"我觉得爬山累得很。","py":"Wǒ juéde páshān lèi de hěn.","vi":"Tôi thấy leo núi mệt ơi là mệt.","hl":"得很"}],"struct":"Tính từ + 得很","note":"Thường dùng trong khẩu ngữ để tăng cường sắc thái biểu đạt mức độ cao."},"g2":{"han":"量词重叠","py":"Liàngcí chóngdié","title":"Lượng từ lặp lại","explain":"汉语中很多量词可以重叠，用来强调在某个范围内的每个成员都具有某种特征，后面一般用“都”。\nTrong tiếng Trung Quốc, nhiều lượng từ có thể lặp lại để nhấn mạnh mỗi thành viên trong một phạm vi nhất định đều có một đặc điểm nào đó, phía sau thường dùng “都”.","examples":[{"zh":"这些照片张张都非常好看。","py":"Zhèxiē zhàopiàn zhāngzhāng dōu fēicháng hǎokàn.","vi":"Những bức ảnh này tấm nào cũng vô cùng đẹp.","hl":"张张……都"},{"zh":"这些苹果个个都很大。","py":"Zhèxiē píngguǒ gègè dōu hěn dà.","vi":"Những quả táo này quả nào cũng rất to.","hl":"个个都"},{"zh":"我想出去拍照，但是天天下雨。","py":"Wǒ xiǎng chūqù pāizhào, dànshì tiāntiān xiàyǔ.","vi":"Tôi muốn ra ngoài chụp ảnh, nhưng ngày nào trời cũng mưa.","hl":"天天"}],"struct":"Lượng từ lặp (AA) (+ 都) + Vị ngữ","note":"Ý nghĩa tương đương với “每 + lượng từ” (mỗi / cái nào cũng...)."},"g3":{"han":"存现句（3）","py":"Cúnxiànjù (3)","title":"Câu tồn hiện (3)","explain":"汉语中，叙述某个处所有人、事物出现或消失，可以用存现句。基本结构：处所词语+动词+趋向补语/结果补语+（动态助词）+数量短语+人/物。\nTrong tiếng Trung Quốc, để miêu tả sự xuất hiện hoặc biến mất của người hoặc sự vật tại một địa điểm nhất định, người ta sử dụng câu tồn hiện. Cấu trúc cơ bản: Từ ngữ chỉ nơi chốn + động từ + bổ ngữ xu hướng/bổ ngữ kết quả + (trợ từ động thái) + cụm từ chỉ số lượng + danh từ chỉ người/sự vật.","examples":[{"zh":"后边走过去两个人。","py":"Hòubian zǒu guòqù liǎng gè rén.","vi":"Phía sau có hai người đang đi qua.","hl":"走过去两个人"},{"zh":"前面开过来很多车。","py":"Qiánmian kāi guòlái hěn duō chē.","vi":"Phía trước có rất nhiều xe chạy tới.","hl":"开过来很多车"},{"zh":"楼上下来了几个人。","py":"Lóushàng xiàlái le jǐ gè rén.","vi":"Trên lầu đi xuống mấy người.","hl":"下来了几个人"}],"struct":"Từ ngữ nơi chốn + Động từ + Bổ ngữ xu hướng/kết quả (+ 了/着) + Số lượng + Danh từ","note":"Danh từ chỉ người/vật xuất hiện hoặc biến mất ở cuối câu thường mang tính bất định (có số lượng từ)."},"g4":{"han":"紧缩复句“……了……就……”","py":"Jǐnsuō fùjù “...le... jiù...”","title":"Câu ghép rút gọn “……了……就……”","explain":"紧缩复句“……了……就……”表示两个动作行为紧接着发生。如果第二个动作行为也已经完成，则需要在句尾再加一个“了”。基本结构：动词1+了……就+动词2……。\nCâu ghép rút gọn sử dụng cấu trúc “……了……就……” biểu thị hai hành động xảy ra liên tiếp. Nếu hành động thứ hai cũng đã hoàn thành thì cần thêm “了” vào cuối câu. Cấu trúc cơ bản: Động từ 1 + 了……就 + động từ 2……","examples":[{"zh":"你听完了音乐会就来我家吃饭。","py":"Nǐ tīngwánle yīnyuèhuì jiù lái wǒ jiā chīfàn.","vi":"Nghe xong buổi hoà nhạc thì em đến nhà chị ăn cơm nhé.","hl":"听完了……就来"},{"zh":"我吃了早饭就去学校了。","py":"Wǒ chīle zǎofàn jiù qù xuéxiào le.","vi":"Tôi ăn sáng xong là đi học luôn rồi.","hl":"吃了……就去……了"},{"zh":"昨天我们下了课就回家了。","py":"Zuótiān wǒmen xiàle kè jiù huíjiā le.","vi":"Hôm qua chúng tôi tan học xong là về nhà luôn.","hl":"下了课就回家了"}],"struct":"(Chủ ngữ +) Động từ 1 + 了 + (Tân ngữ 1) + 就 + Động từ 2 (+ 了)","note":"Hành động 2 xảy ra nối tiếp ngay sau khi hành động 1 hoàn tất."}},"grammarQuiz":[{"id":"hsk3_b5_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"他的拍照 (____) 比我高多了。","opts":[{"t":"水平","ok":true},{"t":"照","ok":false},{"t":"干","ok":false},{"t":"难看","ok":false},{"t":"收到","ok":false}],"exp":"Đáp án C (水平): ‘Trình độ chụp ảnh của anh ấy cao hơn tôi nhiều.’"},{"id":"hsk3_b5_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我 (____) 了一封学校的邮件。","opts":[{"t":"收到","ok":true},{"t":"照","ok":false},{"t":"干","ok":false},{"t":"水平","ok":false},{"t":"难看","ok":false}],"exp":"Đáp án E (收到): ‘Tôi đã nhận được một bức email của nhà trường.’"},{"id":"hsk3_b5_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"明天又是星期天，我不知道应该 (____) 什么。","opts":[{"t":"干","ok":true},{"t":"照","ok":false},{"t":"水平","ok":false},{"t":"难看","ok":false},{"t":"收到","ok":false}],"exp":"Đáp án B (干): ‘Ngày mai lại là Chủ nhật rồi, tôi không biết nên làm gì.’"},{"id":"hsk3_b5_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我还没准备好呢，我看着你的时候你再 (____)。","opts":[{"t":"照","ok":true},{"t":"干","ok":false},{"t":"水平","ok":false},{"t":"难看","ok":false},{"t":"收到","ok":false}],"exp":"Đáp án A (照): ‘Tôi vẫn chưa chuẩn bị xong đâu, lúc tôi nhìn bạn thì bạn hãy chụp nhé.’"},{"id":"hsk3_b5_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我觉得前两张照片好看，第三张有点儿 (____)，你选前两张吧。","opts":[{"t":"难看","ok":true},{"t":"照","ok":false},{"t":"干","ok":false},{"t":"水平","ok":false},{"t":"收到","ok":false}],"exp":"Đáp án D (难看): ‘Tôi thấy hai tấm đầu đẹp, tấm thứ ba hơi xấu, bạn chọn hai tấm đầu đi.’"},{"id":"hsk3_b5_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 他们的飞机到了吗？\nB: (____) 到了，晚点了五个多小时。","opts":[{"t":"终于","ok":true},{"t":"结束","ok":false},{"t":"总是","ok":false},{"t":"感兴趣","ok":false},{"t":"比较","ok":false}],"exp":"Đáp án C (终于): ‘Cuối cùng cũng tới rồi, trễ mất hơn 5 tiếng đồng hồ.’"},{"id":"hsk3_b5_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 为什么我照的照片 (____) 不好看？\nB: 我姐姐会拍照，我让她教教你。","opts":[{"t":"总是","ok":true},{"t":"结束","ok":false},{"t":"终于","ok":false},{"t":"感兴趣","ok":false},{"t":"比较","ok":false}],"exp":"Đáp án B (总是): ‘Sao ảnh tôi chụp lúc nào cũng không đẹp nhỉ?’"},{"id":"hsk3_b5_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 喂，你在哪儿？怎么没接电话？\nB: 我在看电影呢，还有十分钟就 (____) 了。","opts":[{"t":"结束","ok":true},{"t":"总是","ok":false},{"t":"终于","ok":false},{"t":"感兴趣","ok":false},{"t":"比较","ok":false}],"exp":"Đáp án A (结束): ‘Tôi đang xem phim, còn 10 phút nữa là kết thúc rồi.’"},{"id":"hsk3_b5_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 假期我想去北京，也想去上海，不知道怎么选。\nB: 我帮你 (____) 一下。","opts":[{"t":"比较","ok":true},{"t":"结束","ok":false},{"t":"总是","ok":false},{"t":"终于","ok":false},{"t":"感兴趣","ok":false}],"exp":"Đáp án E (比较): ‘Để tôi giúp bạn so sánh một chút.’"},{"id":"hsk3_b5_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 我有两张音乐会的票，咱们一起去吧。\nB: 我对音乐不 (____)。家月喜欢，你问问她。","opts":[{"t":"感兴趣","ok":true},{"t":"结束","ok":false},{"t":"总是","ok":false},{"t":"终于","ok":false},{"t":"比较","ok":false}],"exp":"Đáp án D (感兴趣): ‘Tôi không hứng thú với âm nhạc lắm. Gia Nguyệt thích đấy, bạn hỏi cô ấy đi.’"},{"id":"hsk3_b5_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"今天天气怎么样？","opts":[{"t":"C 晴天","ok":true},{"t":"A 阴天","ok":false},{"t":"B 很热","ok":false}],"exp":"Bạch Gia Nguyệt nói: “这个星期总是阴天，今天终于晴了。”"},{"id":"hsk3_b5_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"白家月为什么要给王一雪打电话？","opts":[{"t":"C 找她爬山","ok":true},{"t":"A 找她吃饭","ok":false},{"t":"B 问她天气","ok":false}],"exp":"Hai người rủ chị Nhất Tuyết cùng đi leo núi."},{"id":"hsk3_b5_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"王一雪和白家月在做什么？","opts":[{"t":"C 看照片","ok":true},{"t":"A 拍照","ok":false},{"t":"B 买相机","ok":false}],"exp":"Hai người đang xem các bức ảnh trên xe taxi."},{"id":"hsk3_b5_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"白家月和王一飞都喜欢做什么？","opts":[{"t":"A 拍照","ok":true},{"t":"B 爬山","ok":false},{"t":"C 比较拍照水平","ok":false}],"exp":"Cả Vương Nhất Phi và Bạch Gia Nguyệt đều thích chụp ảnh."},{"id":"hsk3_b5_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"白家月和王一雪在做什么？","opts":[{"t":"A 拍照","ok":true},{"t":"B 看鸟","ok":false},{"t":"C 找手机","ok":false}],"exp":"Hai người đang chụp ảnh trên núi."},{"id":"hsk3_b5_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"拍照的时候，白家月让王一雪干什么？","opts":[{"t":"C 想干什么就干什么","ok":true},{"t":"A 看着她","ok":false},{"t":"B 看着鸟","ok":false}],"exp":"Bạch Gia Nguyệt nói: “你不用看着我，想干什么都可以。”"},{"id":"hsk3_b5_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"王一雪觉得照片怎么样？","opts":[{"t":"B 每张都很漂亮","ok":true},{"t":"A 她还没看到","ok":false},{"t":"C 没有一飞照得好","ok":false}],"exp":"Vương Nhất Tuyết viết: “也看到了你给我照的照片，张张都很漂亮。”"},{"id":"hsk3_b5_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"王一雪送给白家月什么了？","opts":[{"t":"B 一张门票","ok":true},{"t":"A 一些照片","ok":false},{"t":"C 她做的中国菜","ok":false}],"exp":"Vương Nhất Tuyết viết: “我送你一张明天下午音乐会的门票。”"}],"chars":["总","是","终","于","爬","山","锻","炼","照","鞋","大","衣","拍","感","兴","趣","相","难","看","比","较","水","平","太","阳","树","干","电","收","到","封","邮","件","过","哈","音","乐","会","结","束","这","样","的","片","才","好"],"rhyme":null,"notes":["Tiểu Ngữ giúp sức (trang 45): “又”在这个句子中表示这个情况规律性地重复出现。Từ “又” trong câu dùng để biểu thị tình huống lặp lại mang tính quy luật.","Món quà của Tiểu Ngữ (trang 46, video 5-1): 大银幕上的中国故事 — Câu chuyện Trung Hoa qua màn ảnh rộng.","Câu hỏi thảo luận Bài khóa 1: (1) 白家月觉得爬山怎么样？ (2) 李文要带什么东西？ (3) 白家月要先回去做什么？","Câu hỏi thảo luận Bài khóa 2: (1) 白家月喜欢哪张照片？为什么？ (2) 王一雪为什么不喜欢这张照片？ (3) 爬山的时候，白家月打算做什么？","Câu hỏi thảo luận Bài khóa 3: (1) 王一雪想站在哪儿拍照？ (2) 白家月为什么要等一下再照？ (3) 白家月的手机怎么了？","Câu hỏi thảo luận Bài khóa 4: (1) 王一雪觉得白家月的拍照水平怎么样？ (2) 音乐会什么时候结束？ (3) 听完音乐会，白家月可能做什么？"],"workbook":null},"6":{"pages":"47–56","titleZh":"高铁上还可以点外卖","titlePy":"Gāotiě shàng hái kěyǐ diǎn wàimài","titleVi":"Trên tàu cao tốc vẫn có thể đặt đồ ăn giao tận nơi","goals":["能听懂并介绍交通方式的特点和出行体验。Có thể nghe hiểu và giới thiệu được đặc điểm của các phương tiện giao thông và trải nghiệm đi lại.","能听懂并使用“如果”表达假设的情况和结果。Có thể nghe hiểu và sử dụng được “如果” để biểu đạt tình huống giả định và kết quả của nó.","掌握“越来越”短语，能描述事物的变化趋势。Nắm vững cấu trúc “越来越” để miêu tả xu hướng thay đổi của sự vật.","了解中国的现代交通方式——高铁。Hiểu về tàu cao tốc – phương thức giao thông hiện đại của Trung Quốc."],"words":[{"zh":"该","py":"gāi","vi":"nên","pos":"đtnn."},{"zh":"打算","py":"dǎsuàn","vi":"dự định, kế hoạch","pos":"đgt./dt."},{"zh":"高铁","py":"gāotiě","vi":"tàu cao tốc","pos":"dt."},{"zh":"行","py":"xíng","vi":"được, có thể","pos":"đgt./tt."},{"zh":"路口","py":"lùkǒu","vi":"giao lộ, lối rẽ, đầu đường","pos":"dt."},{"zh":"小心","py":"xiǎoxīn","vi":"cẩn thận, chú ý","pos":"đgt./tt."},{"zh":"迟到","py":"chídào","vi":"đến muộn","pos":"đgt."},{"zh":"红绿灯","py":"hóng-lǜdēng","vi":"đèn giao thông, đèn xanh đèn đỏ","pos":"dt."},{"zh":"后来","py":"hòulái","vi":"sau đó, về sau","pos":"dt."},{"zh":"急","py":"jí","vi":"gấp, lo lắng","pos":"tt./đgt."},{"zh":"如果","py":"rúguǒ","vi":"nếu","pos":"liên."},{"zh":"以前","py":"yǐqián","vi":"trước đây","pos":"dt."},{"zh":"耳机","py":"ěrjī","vi":"tai nghe","pos":"dt."},{"zh":"充电宝","py":"chōngdiànbǎo","vi":"sạc dự phòng","pos":"dt."},{"zh":"常用","py":"cháng yòng","vi":"thường dùng","pos":""},{"zh":"越","py":"yuè","vi":"càng... (càng...)","pos":"phó."},{"zh":"分开","py":"fēnkāi","vi":"tách ra","pos":"đgt."},{"zh":"检查","py":"jiǎnchá","vi":"kiểm tra","pos":"đgt."},{"zh":"刷","py":"shuā","vi":"quét (thẻ, mã QR...)","pos":"đgt."},{"zh":"检票","py":"jiǎnpiào","vi":"kiểm vé","pos":"đgt."},{"zh":"电梯","py":"diàntī","vi":"thang máy","pos":"dt."},{"zh":"放假","py":"fàngjià","vi":"nghỉ phép, nghỉ lễ","pos":"đgt."},{"zh":"沙发","py":"shāfā","vi":"ghế sofa","pos":"dt."},{"zh":"安静","py":"ānjìng","vi":"yên tĩnh","pos":"tt."},{"zh":"选择","py":"xuǎnzé","vi":"chọn, lựa chọn","pos":"đgt."},{"zh":"必须","py":"bìxū","vi":"phải, nhất định phải","pos":"phó."},{"zh":"北京南站","py":"Běijīng Nán Zhàn","vi":"ga Bắc Kinh Nam","pos":"dt. riêng"}],"dialog":[{"section":"Bài khóa 1","context":"在咖啡厅里，李文和白家月在聊天儿。Lý Văn và Bạch Gia Nguyệt đang trò chuyện trong quán cà phê.","audio":"06-1.mp3","speaker":"李文","name":"Lý Văn","zh":"家月，咱们该买去上海的票了。你打算怎么去上海？","py":"Jiāyuè, zánmen gāi mǎi qù Shànghǎi de piào le. Nǐ dǎsuàn zěnme qù Shànghǎi?","vi":"Gia Nguyệt, chúng ta nên mua vé đi Thượng Hải rồi. Em dự định đi bằng phương tiện gì?"},{"section":"Bài khóa 1","context":"","audio":"06-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我还没坐过高铁，咱们坐高铁去，怎么样？","py":"Wǒ hái méi zuò guo gāotiě, zánmen zuò gāotiě qù, zěnmeyàng?","vi":"Em chưa bao giờ đi tàu cao tốc cả. Hay là chúng mình đi bằng tàu cao tốc nhé?"},{"section":"Bài khóa 1","context":"","audio":"06-1.mp3","speaker":"李文","name":"Lý Văn","zh":"没问题，从北京到上海的高铁很多，非常方便。","py":"Méi wèntí, cóng Běijīng dào Shànghǎi de gāotiě hěn duō, fēicháng fāngbiàn.","vi":"Không vấn đề gì. Có rất nhiều chuyến tàu cao tốc từ Bắc Kinh đi Thượng Hải, rất thuận tiện."},{"section":"Bài khóa 1","context":"","audio":"06-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"行！怎么买高铁票？","py":"Xíng! Zěnme mǎi gāotiěpiào?","vi":"Được đó. Chúng mình mua vé tàu cao tốc như thế nào?"},{"section":"Bài khóa 1","context":"","audio":"06-1.mp3","speaker":"李文","name":"Lý Văn","zh":"用手机App就能买。给我你的护照，我帮你买。","py":"Yòng shǒujī App jiù néng mǎi. Gěi wǒ nǐ de hùzhào, wǒ bāng nǐ mǎi.","vi":"Có thể mua trên ứng dụng di động. Đưa hộ chiếu của em đây, anh sẽ mua giúp cho."},{"section":"Bài khóa 1","context":"","audio":"06-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"早就听说过高铁，终于可以坐上了。","py":"Zǎo jiù tīngshuō guo gāotiě, zhōngyú kěyǐ zuò shàng le.","vi":"Em đã nghe nói về tàu cao tốc từ lâu rồi, cuối cùng cũng được đi tàu cao tốc."},{"section":"Bài khóa 1","context":"","audio":"06-1.mp3","speaker":"李文","name":"Lý Văn","zh":"高铁又快又舒服，你一定会喜欢的。","py":"Gāotiě yòu kuài yòu shūfu, nǐ yídìng huì xǐhuan de.","vi":"Tàu cao tốc vừa nhanh vừa thoải mái, chắc chắn em sẽ thích thôi."},{"section":"Bài khóa 2","context":"在车上，刘明开车送白家月和李文去高铁站。Ở trên xe, Lưu Minh lái xe đưa Bạch Gia Nguyệt và Lý Văn đến ga tàu cao tốc.","audio":"06-3.mp3","speaker":"刘明","name":"Lưu Minh","zh":"过了前面的路口就到高铁站了。","py":"Guòle qiánmian de lùkǒu jiù dào gāotiězhàn le.","vi":"Đi qua giao lộ phía trước là tới ga tàu cao tốc rồi."},{"section":"Bài khóa 2","context":"","audio":"06-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我看见了。马上就到了，这条路车很多，您小心点儿。","py":"Wǒ kànjiàn le. Mǎshàng jiù dào le, zhè tiáo lù chē hěn duō, nín xiǎoxīn diǎnr.","vi":"Em thấy rồi. Sắp đến nơi rồi, đường này nhiều xe quá, anh đi cẩn thận một chút nhé."},{"section":"Bài khóa 2","context":"","audio":"06-3.mp3","speaker":"刘明","name":"Lưu Minh","zh":"好，你们还有一个小时，应该不会迟到的。","py":"Hǎo, nǐmen hái yǒu yí gè xiǎoshí, yīnggāi bú huì chídào de.","vi":"Được. Còn một tiếng nữa, nên chắc sẽ không bị muộn đâu."},{"section":"Bài khóa 2","context":"","audio":"06-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我发现这条路车多，红绿灯也多。","py":"Wǒ fāxiàn zhè tiáo lù chē duō, hóng-lǜdēng yě duō.","vi":"Em thấy con đường này nhiều xe, đèn giao thông cũng nhiều."},{"section":"Bài khóa 2","context":"","audio":"06-3.mp3","speaker":"刘明","name":"Lưu Minh","zh":"是啊，这条路我走过一次，后来再也不走了。","py":"Shì a, zhè tiáo lù wǒ zǒu guo yí cì, hòulái zài yě bù zǒu le.","vi":"Đúng vậy, anh đã đi đường này một lần, về sau không bao giờ đi nữa."},{"section":"Bài khóa 2","context":"","audio":"06-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"那您今天为什么走了这条路？","py":"Nà nín jīntiān wèi shénme zǒule zhè tiáo lù?","vi":"Vậy tại sao hôm nay anh lại đi đường này?"},{"section":"Bài khóa 2","context":"","audio":"06-3.mp3","speaker":"刘明","name":"Lưu Minh","zh":"我一急就走错了。如果没走错，二十分钟以前就到了。","py":"Wǒ yì jí jiù zǒu cuò le. Rúguǒ méi zǒu cuò, èrshí fēnzhōng yǐqián jiù dào le.","vi":"Tại anh bị cuống nên đã đi nhầm. Nếu không đi nhầm thì chúng ta đã đến từ 20 phút trước rồi."},{"section":"Bài khóa 3","context":"在高铁站，李文和白家月排队安检、检票。Lý Văn và Bạch Gia Nguyệt xếp hàng kiểm tra an ninh và soát vé ở ga tàu cao tốc.","audio":"06-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"李文，我的耳机没电了，你有充电宝吗？","py":"Lǐ Wén, wǒ de ěrjī méi diàn le, nǐ yǒu chōngdiànbǎo ma?","vi":"Lý Văn, tai nghe của em hết pin rồi. Anh có sạc dự phòng không?"},{"section":"Bài khóa 3","context":"","audio":"06-5.mp3","speaker":"李文","name":"Lý Văn","zh":"有，这些常用的东西我都放在包里了，我给你拿。","py":"Yǒu, zhèxiē cháng yòng de dōngxi wǒ dōu fàng zài bāo li le, wǒ gěi nǐ ná.","vi":"Có, những đồ thường dùng anh đều để trong túi, để anh lấy cho em."},{"section":"Bài khóa 3","context":"","audio":"06-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"前面的人越来越多。","py":"Qiánmian de rén yuèláiyuè duō.","vi":"Phía trước ngày càng có nhiều người hơn."},{"section":"Bài khóa 3","context":"","audio":"06-5.mp3","speaker":"李文","name":"Lý Văn","zh":"对，马上就进高铁站了。咱们一起走，别分开。","py":"Duì, mǎshàng jiù jìn gāotiězhàn le. Zánmen yìqǐ zǒu, bié fēnkāi.","vi":"Đúng vậy, chúng mình sắp tới ga tàu cao tốc rồi. Hãy đi cùng nhau, đừng để bị lạc nhau nhé."},{"section":"Bài khóa 3","context":"","audio":"06-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"好，你检查一下，高铁票都拿好了吗？","py":"Hǎo, nǐ jiǎnchá yíxià, gāotiěpiào dōu náhǎo le ma?","vi":"Được, anh kiểm tra thử xem vé tàu cao tốc đã mang theo chưa?"},{"section":"Bài khóa 3","context":"","audio":"06-5.mp3","speaker":"李文","name":"Lý Văn","zh":"不用拿票，刷护照就能检票进站。","py":"Búyòng ná piào, shuā hùzhào jiù néng jiǎnpiào jìn zhàn.","vi":"Không cần cầm vé đâu, chỉ cần quét hộ chiếu của mình để vào ga."},{"section":"Bài khóa 3","context":"","audio":"06-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"去哪里检票？","py":"Qù nǎlǐ jiǎnpiào?","vi":"Vậy soát vé ở đâu?"},{"section":"Bài khóa 3","context":"","audio":"06-5.mp3","speaker":"李文","name":"Lý Văn","zh":"检票口在二层，我们一会儿坐电梯上去。","py":"Jiǎnpiàokǒu zài èr céng, wǒmen yíhuìr zuò diàntī shàngqù.","vi":"Cửa soát vé ở tầng hai, lát nữa chúng mình sẽ đi thang máy lên."},{"section":"Bài khóa 4","context":"在家里，白家月给安妮打电话介绍自己的旅行。Trong nhà, Bạch Gia Nguyệt gọi điện cho Annie để giới thiệu về chuyến đi của mình.","audio":"06-7.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"这次放假，我去了北京，还去了上海。我是从北京南站坐高铁去的上海。我觉得坐在高铁上跟坐在家里的沙发上一样，又安静又舒服。坐累了就站一会儿，饿了就点外卖。对，你没听错，高铁上可以点外卖，只需要选择好车站和想吃的东西，到站时不用下车，服务员就会给你拿过来。现在喜欢坐高铁的人越来越多。我爸妈来中国旅游的时候，必须带他们也坐一次高铁。","py":"Zhè cì fàngjià, wǒ qùle Běijīng, hái qùle Shànghǎi. Wǒ shì cóng Běijīng Nán Zhàn zuò gāotiě qù de Shànghǎi. Wǒ juéde zuò zài gāotiě shang gēn zuò zài jiālǐ de shāfā shang yíyàng, yòu ānjìng yòu shūfu. Zuò lèi le jiù zhàn yíhuìr, è le jiù diǎn wàimài. Duì, nǐ méi tīngcuò, gāotiě shang kěyǐ diǎn wàimài, zhǐ xūyào xuǎnzé hǎo chēzhàn hé xiǎng chī de dōngxi, dào zhàn shí búyòng xiàchē, fúwùyuán jiù huì gěi nǐ ná guòlái. Xiànzài xǐhuan zuò gāotiě de rén yuèláiyuè duō. Wǒ bàmā lái Zhōngguó lǚyóu de shíhou, bìxū dài tāmen yě zuò yí cì gāotiě.","vi":"Trong kỳ nghỉ lần này, tôi đã đến Bắc Kinh và cũng ghé thăm Thượng Hải. Tôi đi tàu cao tốc từ ga Bắc Kinh Nam đến Thượng Hải. Tôi cảm thấy, ngồi trên tàu có cảm giác giống hệt như đang ngồi trên ghế sofa ở nhà vậy, vừa yên tĩnh vừa thoải mái. Ngồi mỏi rồi thì đứng dậy một lát, đói rồi thì đặt đồ ăn giao tận nơi. Đúng rồi, bạn không nghe nhầm đâu, bạn có thể đặt đồ ăn giao tận nơi ở trên tàu cao tốc. Chỉ cần chọn ga bạn đến và món ăn bạn muốn, bạn không cần phải xuống tàu khi tàu đến ga, nhân viên sẽ mang đến tận chỗ cho bạn. Hiện nay, ngày càng có nhiều người thích đi du lịch bằng tàu cao tốc. Khi bố mẹ tôi đến Trung Quốc chơi, tôi nhất định sẽ đưa họ đi thử tàu cao tốc một chuyến."}],"dialogQuestions":[],"grammar":{"g1":{"han":"固定格式“该……了”","py":"Gùdìng géshì “gāi... le”","title":"Cấu trúc cố định “该……了”","explain":"固定格式“该……了”表示到了需要做某事的时候，多在口语中使用。\nCấu trúc cố định “该……了” thường dùng trong văn nói, biểu thị đã đến lúc cần làm một việc gì đó.","examples":[{"zh":"咱们该买去上海的票了。","py":"Zánmen gāi mǎi qù Shànghǎi de piào le.","vi":"Chúng ta nên mua vé đi Thượng Hải rồi.","hl":"该……了"},{"zh":"八点了，该上课了。","py":"Bā diǎn le, gāi shàngkè le.","vi":"8 giờ rồi, đến giờ vào học rồi.","hl":"该……了"},{"zh":"已经很晚了，我该睡觉了。","py":"Yǐjīng hěn wǎn le, wǒ gāi shuìjiào le.","vi":"Đã muộn lắm rồi, tôi nên đi ngủ thôi.","hl":"该……了"}],"struct":"(Chủ ngữ +) 该 + Động từ / Cụm động từ + 了","note":"Thường dùng với ý nhắc nhở đã đến thời điểm thích hợp để làm việc gì."},"g2":{"han":"假设复句“如果……，就……”","py":"Jiǎshè fùjù “rúguǒ..., jiù...”","title":"Câu ghép giả định “如果……，就……”","explain":"假设复句“如果……，就……”中，“如果”后面的分句是一个假设，“就”后面的分句是在这种假设情况下产生的结果。注意，第二个分句的主语要放在“就”的前面。\nTrong câu ghép giả định “如果……，就……”, mệnh đề đứng sau “如果” là giả thuyết, mệnh đề đứng sau “就” là kết quả có được dựa trên giả thuyết đó. Lưu ý, chủ ngữ của mệnh đề thứ hai phải đặt trước “就”.","examples":[{"zh":"如果没走错，二十分钟以前就到了。","py":"Rúguǒ méi zǒu cuò, èrshí fēnzhōng yǐqián jiù dào le.","vi":"Nếu không đi nhầm thì 20 phút trước đã tới rồi.","hl":"如果……，……就"},{"zh":"如果你需要帮忙，就给我打电话。","py":"Rúguǒ nǐ xūyào bāngmáng, jiù gěi wǒ dǎ diànhuà.","vi":"Nếu bạn cần giúp đỡ thì gọi điện cho tôi.","hl":"如果……，就"},{"zh":"如果有时间，我就去上海玩几天。","py":"Rúguǒ yǒu shíjiān, wǒ jiù qù Shànghǎi wán jǐ tiān.","vi":"Nếu có thời gian, tôi sẽ đi Thượng Hải chơi vài ngày.","hl":"如果……，……就"}],"struct":"如果 + Mệnh đề giả thuyết，(Chủ ngữ 2 +) 就 + Mệnh đề kết quả","note":"Chú ý vị trí chủ ngữ thứ hai luôn đặt trước “就”."},"g3":{"han":"固定短语“越来越”","py":"Gùdìng duǎnyǔ “yuèláiyuè”","title":"Cụm từ cố định “越来越”","explain":"固定短语“越来越”的后面加上形容词或心理动词，表示随着时间的推移而在程度上发生变化。形容词或心理动词前都不能再加程度副词。\nCụm từ cố định “越来越” đứng trước tính từ hoặc động từ chỉ tâm lý, biểu thị mức độ thay đổi theo thời gian. Trước tính từ hoặc động từ chỉ tâm lý không được thêm phó từ chỉ mức độ.","examples":[{"zh":"前面的人越来越多。","py":"Qiánmian de rén yuèláiyuè duō.","vi":"Người phía trước ngày càng đông.","hl":"越来越多"},{"zh":"我越来越喜欢这里的生活了。","py":"Wǒ yuèláiyuè xǐhuan zhèlǐ de shēnghuó le.","vi":"Tôi ngày càng thích cuộc sống ở đây rồi.","hl":"越来越喜欢"},{"zh":"她越来越高，也越来越漂亮了。","py":"Tā yuèláiyuè gāo, yě yuèláiyuè piàoliang le.","vi":"Cô ấy ngày càng cao và cũng ngày càng xinh đẹp hơn.","hl":"越来越……"}],"struct":"Chủ ngữ + 越来越 + Tính từ / Động từ tâm lý (+ 了)","note":"Không dùng thêm các phó từ mức độ như 很, 非常 trước tính từ sau “越来越”."}},"grammarQuiz":[{"id":"hsk3_b6_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我没带钱，可以 (____) 信用卡吗？","opts":[{"t":"刷","ok":true},{"t":"该","ok":false},{"t":"急","ok":false},{"t":"后来","ok":false},{"t":"以前","ok":false}],"exp":"Đáp án B (刷): ‘Tôi không mang tiền mặt, có thể quẹt thẻ tín dụng không?’"},{"id":"hsk3_b6_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"不用太早，星期五 (____) 买票就可以。","opts":[{"t":"以前","ok":true},{"t":"该","ok":false},{"t":"刷","ok":false},{"t":"急","ok":false},{"t":"后来","ok":false}],"exp":"Đáp án E (以前): ‘Không cần quá sớm, mua vé trước thứ Sáu là được rồi.’"},{"id":"hsk3_b6_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"飞机马上就要起飞了，你的手机 (____) 关机了。","opts":[{"t":"该","ok":true},{"t":"刷","ok":false},{"t":"急","ok":false},{"t":"后来","ok":false},{"t":"以前","ok":false}],"exp":"Đáp án A (该): ‘Máy bay sắp cất cánh rồi, điện thoại của bạn đến lúc phải tắt nguồn rồi.’"},{"id":"hsk3_b6_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"前面的路口人很多，你开慢一点儿，别 (____)。","opts":[{"t":"急","ok":true},{"t":"该","ok":false},{"t":"刷","ok":false},{"t":"后来","ok":false},{"t":"以前","ok":false}],"exp":"Đáp án C (急): ‘Ngã tư phía trước rất đông người, bạn lái chậm chút, đừng vội.’"},{"id":"hsk3_b6_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"她开始的时候说要来，(____) 打电话说不来了。","opts":[{"t":"后来","ok":true},{"t":"该","ok":false},{"t":"刷","ok":false},{"t":"急","ok":false},{"t":"以前","ok":false}],"exp":"Đáp án D (后来): ‘Ban đầu cô ấy bảo sẽ đến, sau đó gọi điện nói không đến nữa.’"},{"id":"hsk3_b6_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你一个人开车，路上要 (____)。\nB: 好的，谢谢。","opts":[{"t":"小心","ok":true},{"t":"选择","ok":false},{"t":"检查","ok":false},{"t":"必须","ok":false},{"t":"打算","ok":false}],"exp":"Đáp án C (小心): ‘Bạn tự lái xe một mình, đi đường phải cẩn thận nhé.’"},{"id":"hsk3_b6_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 马上就要出门了，你再 (____) 一下，护照什么的都带了吧？\nB: 都带了，放在包里了。","opts":[{"t":"检查","ok":true},{"t":"选择","ok":false},{"t":"小心","ok":false},{"t":"必须","ok":false},{"t":"打算","ok":false}],"exp":"Đáp án B (检查): ‘Sắp ra khỏi nhà rồi, bạn kiểm tra lại lần nữa xem hộ chiếu các thứ mang đủ chưa?’"},{"id":"hsk3_b6_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 明天晚上六点的火车，你几点出门？\nB: 我 (____) 四点半出门，晚一点儿也没关系。","opts":[{"t":"打算","ok":true},{"t":"选择","ok":false},{"t":"检查","ok":false},{"t":"小心","ok":false},{"t":"必须","ok":false}],"exp":"Đáp án E (打算): ‘Tôi dự định 4 giờ rưỡi ra khỏi nhà, muộn hơn chút cũng không sao.’"},{"id":"hsk3_b6_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 坐高铁四个多小时，坐飞机两个小时，你想坐什么？\nB: 高铁站比机场近多了，我还是想 (____) 高铁。","opts":[{"t":"选择","ok":true},{"t":"检查","ok":false},{"t":"小心","ok":false},{"t":"必须","ok":false},{"t":"打算","ok":false}],"exp":"Đáp án A (选择): ‘Ga tàu cao tốc gần hơn sân bay nhiều, tôi vẫn muốn chọn đi tàu cao tốc.’"},{"id":"hsk3_b6_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 我能坐在你旁边吗？\nB: 不行，咱们的票是分开的，你 (____) 坐在前面。","opts":[{"t":"必须","ok":true},{"t":"选择","ok":false},{"t":"检查","ok":false},{"t":"小心","ok":false},{"t":"打算","ok":false}],"exp":"Đáp án D (必须): ‘Không được, vé của chúng ta tách rời nhau, bạn bắt buộc phải ngồi ở phía trước.’"},{"id":"hsk3_b6_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"李文和白家月打算怎么去上海？","opts":[{"t":"C 坐高铁","ok":true},{"t":"A 开车","ok":false},{"t":"B 坐飞机","ok":false}],"exp":"Bạch Gia Nguyệt đề nghị: “咱们坐高铁去，怎么样？”"},{"id":"hsk3_b6_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"李文觉得高铁怎么样？","opts":[{"t":"B 又快又舒服","ok":true},{"t":"A 高铁票很贵","ok":false},{"t":"C 买票不方便","ok":false}],"exp":"Lý Văn nói: “高铁又快又舒服，你一定会喜欢的。”"},{"id":"hsk3_b6_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"李文和白家月现在在哪儿？","opts":[{"t":"C 在刘明的车上","ok":true},{"t":"A 在高铁站","ok":false},{"t":"B 在出租车上","ok":false}],"exp":"Bối cảnh: Lưu Minh đang lái xe đưa hai người đến ga tàu cao tốc."},{"id":"hsk3_b6_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"如果没走错，他们什么时候到？","opts":[{"t":"B 二十分钟以前就到了","ok":true},{"t":"A 马上就到了","ok":false},{"t":"C 一个小时以前就到了","ok":false}],"exp":"Lưu Minh nói: “如果没走错，二十分钟以前就到了。”"},{"id":"hsk3_b6_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"常用的东西李文放在哪里？","opts":[{"t":"B 包里","ok":true},{"t":"A 手里","ok":false},{"t":"C 行李箱里","ok":false}],"exp":"Lý Văn nói: “这些常用的东西我都放在包里了”."},{"id":"hsk3_b6_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"他们在哪里检票进站？","opts":[{"t":"C 二层检票口","ok":true},{"t":"A 车站门口","ok":false},{"t":"B 一层门口","ok":false}],"exp":"Lý Văn nói: “检票口在二层，我们一会儿坐电梯上去。”"},{"id":"hsk3_b6_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"白家月觉得坐高铁怎么样？","opts":[{"t":"B 高铁上很舒服","ok":true},{"t":"A 高铁站很远","ok":false},{"t":"C 高铁上人很多","ok":false}],"exp":"Bài khóa 4: “我觉得坐在高铁上跟坐在家里的沙发上一样，又安静又舒服。”"},{"id":"hsk3_b6_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"喜欢坐高铁的人多不多？","opts":[{"t":"C 越来越多","ok":true},{"t":"A 不太多","ok":false},{"t":"B 有点儿多","ok":false}],"exp":"Bài khóa 4: “现在喜欢坐高铁的人越来越多。”"}],"chars":["该","打","算","高","铁","行","路","口","小","心","迟","到","红","绿","灯","后","来","急","如","果","以","前","耳","机","充","电","宝","常","用","越","分","开","检","查","刷","票","梯","放","假","沙","发","安","静","选","择","必","须","北","京","南","站","上","还","可","点","外","卖"],"rhyme":null,"notes":["Tiểu Ngữ giúp sức (trang 48): “上”在这里不是表示方向，而是表示实现了某个目标或愿望。Từ “上” ở đây không biểu thị phương hướng, mà biểu thị đạt được một mục tiêu hoặc mong muốn nào đó (ví dụ: 坐上了).","Món quà của Tiểu Ngữ (trang 55, video 6-1): 12306是什么？ — 12306 là gì? (nền tảng đặt vé đường sắt chính thức của Trung Quốc).","Tổng kết học tập Bài 4–6 (trang 55–56): 10 điểm ngữ pháp gồm 一……也/都+不/没……, 比较句(9) 跟……一样, 除了……(以外)，……都/还/也……, 程度补语(2) 得很, 量词重叠, 存现句(3), 紧缩复句 ……了……就……, 该……了, 如果……，就…… và 越来越.","Câu hỏi thảo luận Bài khóa 1: (1) 李文和白家月打算去哪个城市？ (2) 白家月为什么想坐高铁？ (3) 他们打算怎么买高铁票？","Câu hỏi thảo luận Bài khóa 2: (1) 刘明为什么说“应该不会迟到”？ (2) 白家月觉得这条路有什么问题？ (3) 刘明为什么今天走了这条路？","Câu hỏi thảo luận Bài khóa 3: (1) 白家月为什么要用充电宝？ (2) 他们怎么检票进站？ (3) 他们怎么去检票口？","Câu hỏi thảo luận Bài khóa 4: (1) 白家月是怎么去上海的？ (2) 高铁上怎么点外卖？ (3) 白家月想带谁坐高铁？"],"workbook":null},"7":{"pages":"57–66","titleZh":"那条裙子比短裤更好看","titlePy":"Nà tiáo qúnzi bǐ duǎnkù gèng hǎokàn","titleVi":"Chiếc váy đó đẹp hơn quần soóc","goals":["能听懂并介绍购物的经历。Có thể nghe hiểu và giới thiệu được trải nghiệm mua sắm.","能听懂并评价商品的特点。Có thể nghe hiểu và đánh giá được đặc điểm của sản phẩm.","掌握比较句（10）的用法，能对商品进行比较。Nắm vững cách dùng câu so sánh (10), có thể tiến hành so sánh sản phẩm.","了解中国人的购物方式。Hiểu về phương thức mua sắm của người Trung Quốc."],"words":[{"zh":"辆","py":"liàng","vi":"chiếc (dùng cho xe cộ)","pos":"lượng."},{"zh":"自行车","py":"zìxíngchē","vi":"xe đạp","pos":"dt."},{"zh":"旧","py":"jiù","vi":"cũ","pos":"tt."},{"zh":"矮","py":"ǎi","vi":"thấp, lùn","pos":"tt."},{"zh":"试","py":"shì","vi":"thử","pos":"đgt."},{"zh":"黄色","py":"huángsè","vi":"màu vàng","pos":"dt."},{"zh":"短裤","py":"duǎnkù","vi":"quần soóc","pos":"dt."},{"zh":"大小","py":"dàxiǎo","vi":"kích cỡ","pos":"dt."},{"zh":"合适","py":"héshì","vi":"phù hợp","pos":"tt."},{"zh":"裙子","py":"qúnzi","vi":"váy, đầm","pos":"dt."},{"zh":"更","py":"gèng","vi":"càng, hơn","pos":"phó."},{"zh":"决定","py":"juédìng","vi":"quyết định","pos":"đgt./dt."},{"zh":"西瓜","py":"xīguā","vi":"dưa hấu","pos":"dt."},{"zh":"新鲜","py":"xīnxiān","vi":"tươi, tươi mới","pos":"tt."},{"zh":"甜","py":"tián","vi":"ngọt","pos":"tt."},{"zh":"公斤","py":"gōngjīn","vi":"kilôgam","pos":"lượng."},{"zh":"冰","py":"bīng","vi":"đông, đá","pos":"đgt./dt."},{"zh":"极","py":"jí","vi":"cực kỳ","pos":"phó."},{"zh":"斤","py":"jīn","vi":"cân (0,5 kilôgam)","pos":"lượng."},{"zh":"香蕉","py":"xiāngjiāo","vi":"chuối tiêu","pos":"dt."},{"zh":"一共","py":"yígòng","vi":"tổng cộng","pos":"phó."},{"zh":"毛","py":"máo","vi":"hào (đơn vị tiền tệ)","pos":"lượng."},{"zh":"结婚","py":"jiéhūn","vi":"kết hôn","pos":"đgt."},{"zh":"不但","py":"búdàn","vi":"không những","pos":"liên."},{"zh":"而且","py":"érqiě","vi":"mà còn","pos":"liên."},{"zh":"声","py":"shēng","vi":"tiếng (dùng cho âm thanh), âm thanh","pos":"lượng./dt."},{"zh":"开机","py":"kāijī","vi":"mở máy, bật máy","pos":"đgt."}],"dialog":[{"section":"Bài khóa 1","context":"在家里，王一雪和刘明商量去买东西。Vương Nhất Tuyết và Lưu Minh đang ở trong nhà bàn bạc về việc đi mua đồ.","audio":"07-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"这辆自行车是小雪八岁的时候买的，看起来有点儿旧了。","py":"Zhè liàng zìxíngchē shì Xiǎoxuě bā suì de shíhou mǎi de, kàn qǐlái yǒudiǎnr jiù le.","vi":"Chiếc xe đạp này mua khi Tiểu Tuyết được 8 tuổi, nhìn cũng hơi cũ rồi."},{"section":"Bài khóa 1","context":"","audio":"07-1.mp3","speaker":"刘明","name":"Lưu Minh","zh":"是啊，她现在长高了，这辆车已经太矮了。","py":"Shì a, tā xiànzài zhǎnggāo le, zhè liàng chē yǐjīng tài ǎi le.","vi":"Ừ, con bé cao lên rồi, chiếc xe này giờ bị thấp quá."},{"section":"Bài khóa 1","context":"","audio":"07-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"商场里开了一家自行车店，咱们给她买辆新的吧。","py":"Shāngchǎng li kāile yì jiā zìxíngchēdiàn, zánmen gěi tā mǎi liàng xīn de ba.","vi":"Có cửa hàng xe đạp mới mở trong trung tâm thương mại, mình hãy mua cho con một cái mới đi."},{"section":"Bài khóa 1","context":"","audio":"07-1.mp3","speaker":"刘明","name":"Lưu Minh","zh":"好，咱们带小雪一起去，让她试一下。","py":"Hǎo, zánmen dài Xiǎoxuě yìqǐ qù, ràng tā shì yíxià.","vi":"Được, mình hãy đưa Tiểu Tuyết đi cùng để con bé có thể đi thử."},{"section":"Bài khóa 1","context":"","audio":"07-1.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"那今天就去吧！我也想再看看衣服。咱们怎么去？","py":"Nà jīntiān jiù qù ba! Wǒ yě xiǎng zài kànkan yīfu. Zánmen zěnme qù?","vi":"Vậy thì đi luôn hôm nay đi! Em cũng muốn xem quần áo. Chúng ta đi bằng gì nhỉ?"},{"section":"Bài khóa 1","context":"","audio":"07-1.mp3","speaker":"刘明","name":"Lưu Minh","zh":"商场不远，咱们可以走着去。","py":"Shāngchǎng bù yuǎn, zánmen kěyǐ zǒuzhe qù.","vi":"Trung tâm thương mại không xa lắm, mình có thể đi bộ đến đó."},{"section":"Bài khóa 2","context":"在商场，刘明和王一雪买完自行车，又来挑选衣服。Ở trung tâm thương mại, Lưu Minh và Vương Nhất Tuyết mua xong xe đạp rồi lại chọn quần áo.","audio":"07-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"你看我穿这条黄色的短裤好看吗？","py":"Nǐ kàn wǒ chuān zhè tiáo huángsè de duǎnkù hǎokàn ma?","vi":"Anh có nghĩ chiếc quần soóc màu vàng này hợp với em không?"},{"section":"Bài khóa 2","context":"","audio":"07-3.mp3","speaker":"刘明","name":"Lưu Minh","zh":"大小合适，但我觉得那条裙子比短裤更好看。","py":"Dàxiǎo héshì, dàn wǒ juéde nà tiáo qúnzi bǐ duǎnkù gèng hǎokàn.","vi":"Kích cỡ thì vừa đấy, nhưng anh nghĩ chiếc váy kia trông đẹp hơn chiếc quần soóc này."},{"section":"Bài khóa 2","context":"","audio":"07-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"裙子比短裤贵一点儿。","py":"Qúnzi bǐ duǎnkù guì yìdiǎnr.","vi":"Váy đắt hơn quần soóc một chút."},{"section":"Bài khóa 2","context":"","audio":"07-3.mp3","speaker":"刘明","name":"Lưu Minh","zh":"贵多少？","py":"Guì duōshao?","vi":"Đắt hơn bao nhiêu?"},{"section":"Bài khóa 2","context":"","audio":"07-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"裙子480，短裤400。","py":"Qúnzi sìbǎi bāshí, duǎnkù sìbǎi.","vi":"Váy giá 480 đồng, còn quần soóc giá 400 đồng."},{"section":"Bài khóa 2","context":"","audio":"07-3.mp3","speaker":"刘明","name":"Lưu Minh","zh":"裙子不比短裤贵多少，还是买裙子吧，你穿裙子更好看。","py":"Qúnzi bù bǐ duǎnkù guì duōshao, háishi mǎi qúnzi ba, nǐ chuān qúnzi gèng hǎokàn.","vi":"Váy không đắt hơn quần soóc bao nhiêu cả, hãy lấy chiếc váy đi, em mặc váy trông đẹp hơn."},{"section":"Bài khóa 2","context":"","audio":"07-3.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"我多看看再决定。你看，那边有买二送一！","py":"Wǒ duō kànkan zài juédìng. Nǐ kàn, nàbian yǒu mǎi èr sòng yī!","vi":"Em sẽ xem thêm một chút nữa trước khi quyết định. Anh nhìn xem, đằng kia có chương trình “Mua hai tặng một” kìa!"},{"section":"Bài khóa 3","context":"在商店，王一雪在买东西。Vương Nhất Tuyết đang mua đồ ở cửa hàng.","audio":"07-5.mp3","speaker":"店员","name":"Người bán hàng","zh":"西瓜又大又新鲜，不甜不要钱！","py":"Xīguā yòu dà yòu xīnxiān, bù tián bú yào qián!","vi":"Dưa hấu vừa to vừa tươi. Không ngọt không lấy tiền!"},{"section":"Bài khóa 3","context":"","audio":"07-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"西瓜看起来不错，怎么卖？","py":"Xīguā kàn qǐlái búcuò, zěnme mài?","vi":"Dưa hấu trông ngon đấy, bán như thế nào vậy?"},{"section":"Bài khóa 3","context":"","audio":"07-5.mp3","speaker":"店员","name":"Người bán hàng","zh":"五块钱一公斤。来，您先尝尝这块冰西瓜，甜极了！","py":"Wǔ kuài qián yì gōngjīn. Lái, nín xiān chángchang zhè kuài bīng xīguā, tián jíle!","vi":"Năm đồng một cân. Đây, cô hãy thử miếng dưa hấu ướp lạnh này đi, nó cực kỳ ngọt!"},{"section":"Bài khóa 3","context":"","audio":"07-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"是挺甜的！帮我选个大点儿的，再来两斤香蕉。","py":"Shì tǐng tián de! Bāng wǒ xuǎn gè dà diǎnr de, zài lái liǎng jīn xiāngjiāo.","vi":"Đúng là ngọt thật! Phiền anh chọn giúp tôi một quả to hơn, thêm hai cân chuối nữa nhé."},{"section":"Bài khóa 3","context":"","audio":"07-5.mp3","speaker":"店员","name":"Người bán hàng","zh":"一共五十八块五毛。","py":"Yígòng wǔshíbā kuài wǔ máo.","vi":"Tổng cộng là 58,5 đồng ạ."},{"section":"Bài khóa 3","context":"","audio":"07-5.mp3","speaker":"王一雪","name":"Vương Nhất Tuyết","zh":"我买了这么多，便宜点儿吧。","py":"Wǒ mǎile zhème duō, piányi diǎnr ba.","vi":"Tôi mua nhiều như vậy. Anh có thể giảm giá cho tôi không?"},{"section":"Bài khóa 3","context":"","audio":"07-5.mp3","speaker":"店员","name":"Người bán hàng","zh":"您给我五十五吧，不能再便宜了。","py":"Nín gěi wǒ wǔshíwǔ ba, bù néng zài piányi le.","vi":"Thôi tính cô 55 đồng nhé, không thể rẻ hơn được nữa đâu ạ."},{"section":"Bài khóa 4","context":"在家里，刘明在看电视。Lưu Minh đang xem ti vi ở trong nhà.","audio":"07-7.mp3","speaker":"刘明","name":"Lưu Minh","zh":"这几天我们在新家坐着看电视的时候，又发现了新问题。房子大了，电视看起来就有点儿小。这个电视是我们结婚时买的，是时候换个新电视了。今天我一直在网上选电视，没想到，现在的电视不但便宜，而且用着非常方便，有的电视叫它一声就能开机。我看了好几个，都很满意，晚上让一雪来决定吧。","py":"Zhè jǐ tiān wǒmen zài xīn jiā zuòzhe kàn diànshì de shíhou, yòu fāxiànle xīn wèntí. Fángzi dà le, diànshì kàn qǐlái jiù yǒudiǎnr xiǎo. Zhège diànshì shì wǒmen jiéhūn shí mǎi de, shì shíhou huàn gè xīn diànshì le. Jīntiān wǒ yìzhí zài wǎngshang xuǎn diànshì, méi xiǎngdào, xiànzài de diànshì búdàn piányi, érqiě yòngzhe fēicháng fāngbiàn, yǒude diànshì jiào tā yì shēng jiù néng kāijī. Wǒ kànle hǎo jǐ gè, dōu hěn mǎnyì, wǎnshang ràng Yīxuě lái juédìng ba.","vi":"Mấy ngày nay, khi ngồi xem ti vi trong căn nhà mới, chúng tôi đã phát hiện ra một vấn đề mới. Nhà rộng hơn nên chiếc ti vi trông có vẻ hơi nhỏ. Chiếc ti vi này chúng tôi mua khi mới kết hôn, cũng đã đến lúc phải mua cái mới rồi. Tôi đã tìm mua ti vi trên mạng cả ngày, không ngờ rằng ti vi bây giờ không những rẻ mà còn tiện dụng hơn rất nhiều, có loại ti vi bạn chỉ cần gọi một tiếng là mở máy. Tôi đã xem vài chiếc, đều rất hài lòng. Tôi sẽ để Nhất Tuyết quyết định vào tối nay."}],"dialogQuestions":[],"grammar":{"g1":{"han":"连动句（2）","py":"Liándòngjù (2)","title":"Câu liên động (2)","explain":"动态助词“着”用于连动句的第一个动词后面，表示进行第二个动作时的状态或方式。基本结构：动词1+着+（宾语1）+动词2+（宾语2）。\nTrợ từ động thái “着” được dùng sau động từ thứ nhất trong câu liên động, biểu thị trạng thái hoặc cách thức khi thực hiện hành động thứ hai. Cấu trúc cơ bản: động từ 1 + 着 + (tân ngữ 1) + động từ 2 + (tân ngữ 2).","examples":[{"zh":"咱们可以走着去。","py":"Zánmen kěyǐ zǒuzhe qù.","vi":"Chúng ta có thể đi bộ đến đó.","hl":"走着去"},{"zh":"弟弟吃着苹果写作业。","py":"Dìdi chīzhe píngguǒ xiě zuòyè.","vi":"Em trai vừa ăn táo vừa làm bài tập.","hl":"吃着苹果写作业"},{"zh":"他们坐着看电视。","py":"Tāmen zuòzhe kàn diànshì.","vi":"Họ ngồi xem ti vi.","hl":"坐着看电视"}],"struct":"Chủ ngữ + Động từ 1 + 着 (+ Tân ngữ 1) + Động từ 2 (+ Tân ngữ 2)","note":"Động từ 1 + 着 làm phương thức/trạng thái kèm theo của động từ 2."},"g2":{"han":"比较句（10）","py":"Bǐjiàojù (10)","title":"Câu so sánh (10)","explain":"“A不比B+形容词”的意思是A和B差不多。这个结构通常用于强调两者情况接近，或反驳别人说法的语境中。\nCấu trúc “A 不比 B + tính từ” có nghĩa là A và B gần giống nhau. Cấu trúc này thường dùng trong ngữ cảnh nhấn mạnh sự tương đồng giữa hai sự vật hoặc để phản bác ý kiến của người khác.","examples":[{"zh":"裙子不比短裤贵多少。","py":"Qúnzi bù bǐ duǎnkù guì duōshao.","vi":"Váy không đắt hơn quần soóc bao nhiêu.","hl":"不比……贵多少"},{"zh":"他的中文不比你好。","py":"Tā de Zhōngwén bù bǐ nǐ hǎo.","vi":"Tiếng Trung của anh ấy chẳng giỏi hơn bạn đâu.","hl":"不比……好"},{"zh":"他跑得不比我快多少。","py":"Tā pǎo de bù bǐ wǒ kuài duōshao.","vi":"Anh ấy chạy chẳng nhanh hơn tôi bao nhiêu.","hl":"不比……快多少"}],"struct":"A + 不比 + B + Tính từ (+ 多少/一点儿)","note":"Khác với “A没有B…” (A kém B); “A不比B…” nhấn mạnh A không vượt hơn B (hoặc ngang bằng/kém một chút)."},"g3":{"han":"程度补语（3）","py":"Chéngdù bǔyǔ (3)","title":"Bổ ngữ trình độ (3)","explain":"程度补语“极了”用在形容词或心理动词后面，表示人或事物的性质或者状态，或人的心理感受达到很高的程度。\nBổ ngữ trình độ “极了” đặt sau tính từ hoặc động từ chỉ tâm lý, biểu thị tính chất, trạng thái của người hoặc sự vật, hoặc cảm xúc của con người đạt đến mức độ rất cao.","examples":[{"zh":"这块冰西瓜甜极了。","py":"Zhè kuài bīng xīguā tián jíle.","vi":"Miếng dưa hấu ướp lạnh này ngọt cực kỳ.","hl":"甜极了"},{"zh":"今年夏天热极了。","py":"Jīnnián xiàtiān rè jíle.","vi":"Mùa hè năm nay nóng vô cùng.","hl":"热极了"},{"zh":"这本书我喜欢极了。","py":"Zhè běn shū wǒ xǐhuan jíle.","vi":"Quyển sách này tôi thích cực kỳ.","hl":"喜欢极了"}],"struct":"Tính từ / Động từ tâm lý + 极了","note":"Có thể dùng cho cả cảm xúc tích cực và tiêu cực để diễn đạt mức độ cao."},"g4":{"han":"递进复句“不但……，而且……”","py":"Dìjìn fùjù “búdàn..., érqiě...”","title":"Câu ghép tăng tiến “不但……，而且……”","explain":"递进复句“不但……，而且……”连接两个分句，表示递进关系。如果两个分句的主语相同，那么“不但”要放在第一个主语后面；如果两个分句的主语不同，那么“不但”要放在第一个主语的前面。\nCâu ghép tăng tiến “不但……，而且……” dùng để nối hai mệnh đề, biểu thị quan hệ tăng tiến. Nếu chủ ngữ của hai mệnh đề giống nhau thì “不但” đặt sau chủ ngữ thứ nhất; nếu chủ ngữ của hai mệnh đề khác nhau thì “不但” đặt trước chủ ngữ thứ nhất.","examples":[{"zh":"现在的电视不但便宜，而且用着非常方便。","py":"Xiànzài de diànshì búdàn piányi, érqiě yòngzhe fēicháng fāngbiàn.","vi":"Ti vi bây giờ không những rẻ mà dùng còn rất tiện.","hl":"不但……，而且"},{"zh":"家月不但喜欢唱歌，而且唱得很好听。","py":"Jiāyuè búdàn xǐhuan chànggē, érqiě chàng de hěn hǎotīng.","vi":"Gia Nguyệt không chỉ thích hát mà hát còn rất hay.","hl":"不但……，而且"},{"zh":"不但家月会说汉语，而且天中也会说汉语。","py":"Búdàn Jiāyuè huì shuō Hànyǔ, érqiě Tiānzhōng yě huì shuō Hànyǔ.","vi":"Không chỉ Gia Nguyệt biết nói tiếng Hán mà Thiên Trung cũng biết nói tiếng Hán.","hl":"不但……，而且……也"}],"struct":"Chủ ngữ + 不但……，而且…… (cùng chủ ngữ) | 不但 + Chủ ngữ 1……，而且 + Chủ ngữ 2…… (khác chủ ngữ)","note":"Chú ý vị trí của “不但” phụ thuộc vào việc hai phân câu có cùng chủ ngữ hay không."}},"grammarQuiz":[{"id":"hsk3_b7_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"你的手机很 (____)，买个新的吧。","opts":[{"t":"旧","ok":true},{"t":"试","ok":false},{"t":"更","ok":false},{"t":"矮","ok":false},{"t":"声","ok":false}],"exp":"Đáp án D (旧): ‘Điện thoại của bạn cũ lắm rồi, mua cái mới đi.’"},{"id":"hsk3_b7_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"她比我大两岁，但是比我还 (____) 一点儿。","opts":[{"t":"矮","ok":true},{"t":"试","ok":false},{"t":"更","ok":false},{"t":"旧","ok":false},{"t":"声","ok":false}],"exp":"Đáp án C (矮): ‘Cô ấy lớn hơn tôi hai tuổi, nhưng lại thấp hơn tôi một chút.’"},{"id":"hsk3_b7_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"这条短裤比那条 (____) 合适，买这条吧。","opts":[{"t":"更","ok":true},{"t":"试","ok":false},{"t":"矮","ok":false},{"t":"旧","ok":false},{"t":"声","ok":false}],"exp":"Đáp án B (更): ‘Chiếc quần soóc này phù hợp hơn chiếc kia, mua chiếc này đi.’"},{"id":"hsk3_b7_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我们都听见了他在教室外面的笑 (____)。","opts":[{"t":"声","ok":true},{"t":"试","ok":false},{"t":"更","ok":false},{"t":"矮","ok":false},{"t":"旧","ok":false}],"exp":"Đáp án E (声): ‘Chúng tôi đều nghe thấy tiếng cười của cậu ấy bên ngoài lớp học.’"},{"id":"hsk3_b7_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"上网买东西很方便，你应该 (____) 一下。","opts":[{"t":"试","ok":true},{"t":"更","ok":false},{"t":"矮","ok":false},{"t":"旧","ok":false},{"t":"声","ok":false}],"exp":"Đáp án A (试): ‘Mua đồ qua mạng rất tiện, bạn nên thử một lần xem.’"},{"id":"hsk3_b7_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 假期的时候你们去哪儿旅游？\nB: 我想去看海，不知道这个时间是不是 (____)。","opts":[{"t":"合适","ok":true},{"t":"一共","ok":false},{"t":"决定","ok":false},{"t":"结婚","ok":false},{"t":"开机","ok":false}],"exp":"Đáp án B (合适): ‘Tôi muốn đi ngắm biển, không biết thời điểm này có thích hợp không.’"},{"id":"hsk3_b7_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你们两个准备什么时候 (____)？\nB: 可能今年10月，到时候一定告诉你。","opts":[{"t":"结婚","ok":true},{"t":"一共","ok":false},{"t":"合适","ok":false},{"t":"决定","ok":false},{"t":"开机","ok":false}],"exp":"Đáp án D (结婚): ‘Hai người định khi nào kết hôn?’"},{"id":"hsk3_b7_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你帮我看看，我的手机为什么不能 (____)？\nB: 让小李帮你看，你新买的这个手机跟他的一样。","opts":[{"t":"开机","ok":true},{"t":"一共","ok":false},{"t":"合适","ok":false},{"t":"决定","ok":false},{"t":"结婚","ok":false}],"exp":"Đáp án E (开机): ‘Bạn xem giúp tôi sao điện thoại của tôi không bật nguồn lên được?’"},{"id":"hsk3_b7_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 网上的房子太多了，我还没有 (____) 去看哪一个。\nB: 你可以先在网上看房，我教你。","opts":[{"t":"决定","ok":true},{"t":"一共","ok":false},{"t":"合适","ok":false},{"t":"结婚","ok":false},{"t":"开机","ok":false}],"exp":"Đáp án C (决定): ‘Nhà trên mạng nhiều quá, tôi vẫn chưa quyết định đi xem căn nào.’"},{"id":"hsk3_b7_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 请问，这些水果多少钱？\nB: 苹果两斤，八块；香蕉四斤，十二块。(____) 二十块。","opts":[{"t":"一共","ok":true},{"t":"合适","ok":false},{"t":"决定","ok":false},{"t":"结婚","ok":false},{"t":"开机","ok":false}],"exp":"Đáp án A (一共): ‘Táo hai cân 8 đồng; chuối bốn cân 12 đồng. Tổng cộng 20 đồng.’"},{"id":"hsk3_b7_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"小雪的自行车是什么时候买的？","opts":[{"t":"C 她八岁的时候买的","ok":true},{"t":"A 昨天买的","ok":false},{"t":"B 今天买的","ok":false}],"exp":"Vương Nhất Tuyết nói: “这辆自行车是小雪八岁的时候买的...”"},{"id":"hsk3_b7_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"他们怎么去商场？","opts":[{"t":"A 走路","ok":true},{"t":"B 打车","ok":false},{"t":"C 骑自行车","ok":false}],"exp":"Lưu Minh nói: “商场不远，咱们可以走着去。”"},{"id":"hsk3_b7_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"课文里说，下面哪个更贵？","opts":[{"t":"B 裙子","ok":true},{"t":"A 短裤","ok":false},{"t":"C 运动鞋","ok":false}],"exp":"Váy 480 đồng đắt hơn quần soóc 400 đồng."},{"id":"hsk3_b7_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"王一雪后来是怎么决定的？","opts":[{"t":"C 看看再说","ok":true},{"t":"A 买裙子","ok":false},{"t":"B 买裤子","ok":false}],"exp":"Vương Nhất Tuyết nói: “我多看看再决定。”"},{"id":"hsk3_b7_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"王一雪在买什么？","opts":[{"t":"C 西瓜和香蕉","ok":true},{"t":"A 苹果","ok":false},{"t":"B 牛奶","ok":false}],"exp":"Vương Nhất Tuyết chọn mua một quả dưa hấu to và hai cân chuối."},{"id":"hsk3_b7_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"这些水果一共花了多少钱？","opts":[{"t":"A 五十五块","ok":true},{"t":"B 五十八块","ok":false},{"t":"C 五十八块五毛","ok":false}],"exp":"Sau khi mặc cả, người bán hàng đồng ý tính giá 55 đồng (“您给我五十五吧”)."},{"id":"hsk3_b7_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"刘明发现了什么新问题？","opts":[{"t":"C 电视有点儿小","ok":true},{"t":"A 电视太旧了","ok":false},{"t":"B 房子太大了","ok":false}],"exp":"Bài khóa 4: “房子大了，电视看起来就有点儿小。”"},{"id":"hsk3_b7_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"刘明选电视的时候发现了什么？","opts":[{"t":"A 新电视很方便","ok":true},{"t":"B 新电视不便宜","ok":false},{"t":"C 不能在网上选电视","ok":false}],"exp":"Bài khóa 4: “现在的电视不但便宜，而且用着非常方便...”"}],"chars":["辆","自","行","车","旧","矮","试","黄","色","短","裤","大","小","合","适","裙","子","更","决","定","西","瓜","新","鲜","甜","公","斤","冰","极","香","蕉","一","共","毛","结","婚","不","但","而","且","声","开","机","那","条","比","好","看"],"rhyme":null,"notes":["Tiểu Ngữ giúp sức (trang 60): 比较句中的形容词前面可以用副词“还”或者“更”表示程度加深。Trong câu so sánh, phó từ “还” hoặc “更” có thể đứng trước tính từ để làm tăng thêm mức độ.","Tiểu Ngữ giúp sức (trang 60): “买二送一”是商店打折时常用的表达，意思是“你买两个东西，我送你一个东西”。当然有时候你也会看到“买一送一”“买三送一”这样的打折活动。“买二送一” là cách nói thường dùng khi cửa hàng có chương trình khuyến mãi, nghĩa là “Bạn mua hai món thì được tặng một món”.","Tiểu Ngữ giúp sức (trang 62): “不甜不要钱”常用在广告语中，这句话省略了主语，完整语句应该是：“如果这个西瓜不甜，我们就不要钱。”","Món quà của Tiểu Ngữ (trang 66, video 7-1): 中国人购物方式的转变 — Sự thay đổi về phương thức mua sắm của người Trung Quốc.","Câu hỏi thảo luận Bài khóa 1: (1) 他们为什么想给小雪买新自行车？ (2) 他们为什么想带小雪一起去？ (3) 王一雪还想买什么？","Câu hỏi thảo luận Bài khóa 2: (1) 刘明觉得短裤怎么样？ (2) 王一雪为什么不想买裙子？ (3) 裙子比短裤贵多少？","Câu hỏi thảo luận Bài khóa 3: (1) 西瓜多少钱一斤？ (2) 王一雪买了什么水果？ (3) 店员给王一雪便宜了多少钱？","Câu hỏi thảo luận Bài khóa 4: (1) 刘明家的电视是什么时候买的？ (2) 刘明想在哪儿买新电视？ (3) 刘明为什么觉得新电视用着很方便？"],"workbook":null},"8":{"pages":"67–75","titleZh":"今天我出院了","titlePy":"Jīntiān wǒ chūyuàn le","titleVi":"Hôm nay tôi xuất viện rồi","goals":["能听懂并描述看病经历及用药方法。Có thể nghe hiểu và miêu tả được kinh nghiệm đi khám bệnh và cách dùng thuốc.","能听懂并交流身体状况和健康习惯。Có thể nghe hiểu và trao đổi được về tình trạng sức khoẻ và thói quen lành mạnh.","掌握时量补语（2）的用法，能表达动作结束后延续到现在的时长。Nắm vững cách dùng của bổ ngữ thời lượng (2), để diễn đạt khoảng thời gian kéo dài từ khi hành động kết thúc đến hiện tại."],"words":[{"zh":"最近","py":"zuìjìn","vi":"gần đây","pos":"dt."},{"zh":"常","py":"cháng","vi":"thường, thường xuyên","pos":"phó."},{"zh":"体育馆","py":"tǐyùguǎn","vi":"nhà thi đấu","pos":"dt."},{"zh":"习惯","py":"xíguàn","vi":"thói quen, quen với","pos":"dt./đgt."},{"zh":"胖","py":"pàng","vi":"béo","pos":"tt."},{"zh":"健康","py":"jiànkāng","vi":"khoẻ mạnh","pos":"tt."},{"zh":"以后","py":"yǐhòu","vi":"sau, sau này, về sau","pos":"dt."},{"zh":"羽毛球","py":"yǔmáoqiú","vi":"cầu lông","pos":"dt."},{"zh":"耳朵","py":"ěrduo","vi":"tai","pos":"dt."},{"zh":"感冒","py":"gǎnmào","vi":"bị cảm, cảm","pos":"đgt./dt."},{"zh":"发烧","py":"fāshāo","vi":"sốt","pos":"đgt."},{"zh":"低","py":"dī","vi":"thấp","pos":"tt."},{"zh":"关心","py":"guānxīn","vi":"quan tâm","pos":"đgt."},{"zh":"注意","py":"zhùyì","vi":"chú ý","pos":"đgt."},{"zh":"突然","py":"tūrán","vi":"đột nhiên, đột ngột","pos":"tt."},{"zh":"住院","py":"zhùyuàn","vi":"nằm viện","pos":"đgt."},{"zh":"担心","py":"dānxīn","vi":"lo lắng","pos":"đgt."},{"zh":"腿","py":"tuǐ","vi":"chân","pos":"dt."},{"zh":"病人","py":"bìngrén","vi":"bệnh nhân","pos":"dt."},{"zh":"差不多","py":"chàbuduō","vi":"gần như, tương tự, xấp xỉ","pos":"phó./tt."},{"zh":"得","py":"děi","vi":"phải, cần","pos":"đtnn."},{"zh":"开心","py":"kāixīn","vi":"vui vẻ","pos":"tt."},{"zh":"出院","py":"chūyuàn","vi":"xuất viện","pos":"đgt."},{"zh":"开","py":"kāi","vi":"kê (đơn thuốc)","pos":"đgt."},{"zh":"种","py":"zhǒng","vi":"loại","pos":"lượng."},{"zh":"方法","py":"fāngfǎ","vi":"phương pháp","pos":"dt."},{"zh":"其他","py":"qítā","vi":"khác","pos":"đt."},{"zh":"心里","py":"xīnlǐ","vi":"trong lòng","pos":"dt."}],"dialog":[{"section":"Bài khóa 1","context":"在学校的体育馆，李文遇到了陈天中。Lý Văn đã gặp Trần Thiên Trung ở nhà thi đấu của trường.","audio":"08-1.mp3","speaker":"李文","name":"Lý Văn","zh":"天中，最近常看见你来体育馆。","py":"Tiānzhōng, zuìjìn cháng kànjiàn nǐ lái tǐyùguǎn.","vi":"Thiên Trung, dạo này mình hay thấy bạn ở nhà thi đấu."},{"section":"Bài khóa 1","context":"","audio":"08-1.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"我每天下午都来跑一个小时步。","py":"Wǒ měitiān xiàwǔ dōu lái pǎo yí gè xiǎoshí bù.","vi":"Chiều nào mình cũng đến đây chạy bộ một tiếng."},{"section":"Bài khóa 1","context":"","audio":"08-1.mp3","speaker":"李文","name":"Lý Văn","zh":"你的运动习惯真不错。","py":"Nǐ de yùndòng xíguàn zhēn búcuò.","vi":"Thói quen tập luyện của bạn rất tốt."},{"section":"Bài khóa 1","context":"","audio":"08-1.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"因为我今年胖了十多斤，不能再胖下去了，有点儿不健康。","py":"Yīnwèi wǒ jīnnián pàngle shí duō jīn, bù néng zài pàng xiàqù le, yǒudiǎnr bú jiànkāng.","vi":"Bởi vì năm nay mình đã tăng hơn mười cân, mình thực sự không thể để béo thêm được nữa, như vậy không khoẻ đâu."},{"section":"Bài khóa 1","context":"","audio":"08-1.mp3","speaker":"李文","name":"Lý Văn","zh":"我下课以后常去打羽毛球，你也来玩吧。","py":"Wǒ xiàkè yǐhòu cháng qù dǎ yǔmáoqiú, nǐ yě lái wán ba.","vi":"Mình thường chơi cầu lông sau giờ học, bạn cũng đến chơi cùng chúng mình nhé!"},{"section":"Bài khóa 1","context":"","audio":"08-1.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"我知道，但是你们的水平太高了，我打得不怎么样。","py":"Wǒ zhīdào, dànshì nǐmen de shuǐpíng tài gāo le, wǒ dǎ de bù zěnmeyàng.","vi":"Mình biết, nhưng trình độ của các bạn cao quá, mình chơi không được tốt lắm."},{"section":"Bài khóa 1","context":"","audio":"08-1.mp3","speaker":"李文","name":"Lý Văn","zh":"没关系，我可以教你。","py":"Méi guānxi, wǒ kěyǐ jiāo nǐ.","vi":"Không sao đâu mà. Mình có thể dạy bạn."},{"section":"Bài khóa 2","context":"在教室，安妮问候陈天中。Annie hỏi thăm Trần Thiên Trung ở trong lớp học.","audio":"08-3.mp3","speaker":"安妮","name":"Annie","zh":"你怎么了？看上去有点儿不舒服。","py":"Nǐ zěnme le? Kàn shàngqu yǒudiǎnr bù shūfu.","vi":"Bạn bị làm sao vậy? Trông bạn không được khoẻ lắm."},{"section":"Bài khóa 2","context":"","audio":"08-3.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"昨天游完泳以后，耳朵一直有点儿疼。","py":"Zuótiān yóuwán yǒng yǐhòu, ěrduo yìzhí yǒudiǎnr téng.","vi":"Hôm qua, sau khi bơi xong, mình cứ bị đau tai."},{"section":"Bài khóa 2","context":"","audio":"08-3.mp3","speaker":"安妮","name":"Annie","zh":"是不是感冒了？发烧吗？","py":"Shì bu shì gǎnmào le? Fāshāo ma?","vi":"Liệu có phải bị cảm rồi không? Bạn có bị sốt không?"},{"section":"Bài khóa 2","context":"","audio":"08-3.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"好像发低烧了。","py":"Hǎoxiàng fā dīshāo le.","vi":"Hình như sốt nhẹ rồi."},{"section":"Bài khóa 2","context":"","audio":"08-3.mp3","speaker":"安妮","name":"Annie","zh":"我送你去医院，让医生检查一下吧。","py":"Wǒ sòng nǐ qù yīyuàn, ràng yīshēng jiǎnchá yíxià ba.","vi":"Mình đưa bạn đến bệnh viện để bác sĩ kiểm tra nhé."},{"section":"Bài khóa 2","context":"","audio":"08-3.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"我先回去睡一觉，可能休息休息就好了。","py":"Wǒ xiān huíqù shuì yí jiào, kěnéng xiūxi xiūxi jiù hǎo le.","vi":"Mình sẽ về nhà chợp mắt một lát trước đã, chắc là nghỉ ngơi xong thì sẽ ổn thôi."},{"section":"Bài khóa 2","context":"","audio":"08-3.mp3","speaker":"安妮","name":"Annie","zh":"好吧，如果下午还发烧，就一定要去看医生。","py":"Hǎo ba, rúguǒ xiàwǔ hái fāshāo, jiù yídìng yào qù kàn yīshēng.","vi":"Được rồi, nếu chiều nay vẫn còn sốt thì nhất định phải đi khám bác sĩ đấy nhé."},{"section":"Bài khóa 2","context":"","audio":"08-3.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"谢谢关心，我会注意的。","py":"Xièxie guānxīn, wǒ huì zhùyì de.","vi":"Cảm ơn sự quan tâm của bạn, mình sẽ chú ý hơn."},{"section":"Bài khóa 3","context":"在医院病房，安妮探望陈天中。Annie đến thăm Trần Thiên Trung ở phòng bệnh của bệnh viện.","audio":"08-5.mp3","speaker":"安妮","name":"Annie","zh":"你怎么突然住院了？大家都很担心你。","py":"Nǐ zěnme tūrán zhùyuàn le? Dàjiā dōu hěn dānxīn nǐ.","vi":"Tại sao bạn đột nhiên lại phải nhập viện thế? Mọi người thực sự rất lo lắng cho bạn."},{"section":"Bài khóa 3","context":"","audio":"08-5.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"我的腿疼了几个星期了，医生说需要住院做检查。","py":"Wǒ de tuǐ téngle jǐ gè xīngqī le, yīshēng shuō xūyào zhùyuàn zuò jiǎnchá.","vi":"Mình đã bị đau chân mấy tuần nay rồi, bác sĩ nói mình cần nhập viện để làm một số xét nghiệm."},{"section":"Bài khóa 3","context":"","audio":"08-5.mp3","speaker":"安妮","name":"Annie","zh":"你看起来一点儿也不像病人。","py":"Nǐ kàn qǐlái yìdiǎnr yě bú xiàng bìngrén.","vi":"Trông bạn chẳng giống bệnh nhân chút nào cả."},{"section":"Bài khóa 3","context":"","audio":"08-5.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"是啊，我很少生病。我上次来医院已经过去差不多两年了。","py":"Shì a, wǒ hěn shǎo shēngbìng. Wǒ shàng cì lái yīyuàn yǐjīng guòqù chàbuduō liǎng nián le.","vi":"Đúng vậy, mình hiếm khi bị ốm. Lần cuối mình đến bệnh viện là gần hai năm trước rồi."},{"section":"Bài khóa 3","context":"","audio":"08-5.mp3","speaker":"安妮","name":"Annie","zh":"你每天跑步，有时候还去游泳，是不是运动太多了？","py":"Nǐ měitiān pǎobù, yǒu shíhou hái qù yóuyǒng, shì bu shì yùndòng tài duō le?","vi":"Ngày nào bạn cũng chạy bộ, có lúc còn đi bơi nữa, liệu có phải do bạn đã tập luyện quá sức không?"},{"section":"Bài khóa 3","context":"","audio":"08-5.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"医生也这么说，但是还得做完检查才能知道。","py":"Yīshēng yě zhème shuō, dànshì hái děi zuòwán jiǎnchá cái néng zhīdào.","vi":"Bác sĩ cũng nói như vậy, tuy nhiên chúng ta sẽ phải đợi kết quả kiểm tra thì mới biết chắc chắn được."},{"section":"Bài khóa 3","context":"","audio":"08-5.mp3","speaker":"安妮","name":"Annie","zh":"别担心！听医生的话，好好休息，你的腿一定能好。","py":"Bié dānxīn! Tīng yīshēng de huà, hǎohāo xiūxi, nǐ de tuǐ yídìng néng hǎo.","vi":"Đừng lo lắng! Chỉ cần làm theo lời khuyên của bác sĩ, nghỉ ngơi thật nhiều, chân của bạn sẽ sớm hồi phục thôi."},{"section":"Bài khóa 3","context":"","audio":"08-5.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"谢谢。有人来看我，我就开心多了。","py":"Xièxie. Yǒu rén lái kàn wǒ, wǒ jiù kāixīn duō le.","vi":"Cảm ơn bạn. Có người tới thăm mình, mình đã vui lắm rồi."},{"section":"Bài khóa 4","context":"在家里，陈天中吃药、休息。Trần Thiên Trung uống thuốc và nghỉ ngơi ở nhà.","audio":"08-7.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"今天我出院了。出院前，医生给我开了几种药，而且告诉了我吃药的方法。有一种药需要每天睡前吃一次，其他几种每天吃三次，饭后吃。除了吃药，医生还说最重要的是多休息。我都记在心里了，回家以后一定会多注意。希望我的腿能快一点儿好。","py":"Jīntiān wǒ chūyuàn le. Chūyuàn qián, yīshēng gěi wǒ kāile jǐ zhǒng yào, érqiě gàosule wǒ chīyào de fāngfǎ. Yǒu yì zhǒng yào xūyào měitiān shuìqián chī yí cì, qítā jǐ zhǒng měitiān chī sān cì, fànhòu chī. Chúle chīyào, yīshēng hái shuō zuì zhòngyào de shì duō xiūxi. Wǒ dōu jì zài xīnlǐ le, huíjiā yǐhòu yídìng huì duō zhùyì. Xīwàng wǒ de tuǐ néng kuài yìdiǎnr hǎo.","vi":"Hôm nay tôi xuất viện rồi. Trước khi ra viện, bác sĩ đã kê cho tôi vài loại thuốc, đồng thời hướng dẫn cách uống thuốc cho tôi. Có một loại thuốc mỗi tối cần uống một lần trước khi đi ngủ, những loại khác uống ba lần một ngày sau bữa ăn. Ngoài việc uống thuốc, bác sĩ còn nói với tôi rằng nghỉ ngơi đầy đủ là điều quan trọng nhất. Tôi đã ghi nhớ điều đó trong lòng rồi, sau khi về nhà nhất định sẽ chăm sóc bản thân thật tốt. Hy vọng chân tôi sẽ sớm khỏi."}],"dialogQuestions":[],"grammar":{"g1":{"han":"趋向补语的引申用法（1）","py":"Qūxiàng bǔyǔ de yǐnshēn yòngfǎ (1)","title":"Cách dùng mở rộng của bổ ngữ xu hướng (1)","explain":"趋向补语“下去”用在动词或形容词后面，表示已经开始的动作或者状态还要继续。\nBổ ngữ xu hướng “下去” đặt sau động từ hoặc tính từ, biểu thị hành động hoặc trạng thái đã bắt đầu và sẽ tiếp tục diễn ra.","examples":[{"zh":"我今年胖了十多斤，不能再胖下去了。","py":"Wǒ jīnnián pàngle shí duō jīn, bù néng zài pàng xiàqù le.","vi":"Năm nay mình tăng hơn chục cân rồi, không thể tiếp tục béo thêm được nữa.","hl":"胖下去"},{"zh":"她读完了第一个问题，后面的你读下去。","py":"Tā dúwánle dì-yī gè wèntí, hòumian de nǐ dú xiàqù.","vi":"Cô ấy đọc xong câu hỏi thứ nhất rồi, phần sau bạn đọc tiếp đi.","hl":"读下去"},{"zh":"这几天太热了，如果再热下去就不能出门了。","py":"Zhè jǐ tiān tài rè le, rúguǒ zài rè xiàqù jiù bù néng chūmén le.","vi":"Mấy hôm nay nóng quá, nếu cứ nóng tiếp thế này thì không ra ngoài được mất.","hl":"热下去"}],"struct":"Động từ / Tính từ + 下去","note":"Mang nghĩa tiếp tục duy trì hoặc phát triển theo hướng hiện tại."},"g2":{"han":"离合词（2）","py":"Líhécí (2)","title":"Từ li hợp (2)","explain":"离合词一般不能直接加宾语。使用离合词的句子中如果有补语，一般都放在离合词的中间。\nTừ li hợp thường không thể trực tiếp mang tân ngữ. Trong câu sử dụng từ li hợp, nếu có bổ ngữ thì thường đặt bổ ngữ ở giữa hai phần của từ li hợp.","examples":[{"zh":"昨天游完泳以后，我的耳朵一直有点儿疼。","py":"Zuótiān yóuwán yǒng yǐhòu, wǒ de ěrduo yìzhí yǒudiǎnr téng.","vi":"Hôm qua sau khi bơi xong, tai mình cứ hơi đau.","hl":"游完泳"},{"zh":"今年夏天只下了两次雨。","py":"Jīnnián xiàtiān zhǐ xiàle liǎng cì yǔ.","vi":"Mùa hè năm nay trời chỉ mưa có hai lần.","hl":"下了两次雨"},{"zh":"小张下个月跟他女朋友结婚。","py":"Xiǎo Zhāng xià gè yuè gēn tā nǚpéngyou jiéhūn.","vi":"Tháng sau Tiểu Trương kết hôn với bạn gái cậu ấy.","hl":"跟……结婚"}],"struct":"Động tố + (了/过/完/bổ ngữ/số lượng từ...) + Danh tố (vd: 游完泳, 跑一个小时步, 下两次雨)","note":"Từ li hợp như 游泳, 跑步, 结婚, 见面 không mang tân ngữ trực tiếp mà tách ra để chèn bổ ngữ vào giữa."},"g3":{"han":"时量补语（2）","py":"Shíliàng bǔyǔ (2)","title":"Bổ ngữ thời lượng (2)","explain":"时量补语用在动词的后面，表示动作或者状态持续时间的长短。有些动词不能持续，这时动词后的时量补语表示动作从完成到说话时过了多长时间。\nBổ ngữ thời lượng đặt sau động từ, biểu thị khoảng thời gian mà hành động hoặc trạng thái duy trì. Có một số động từ không thể duy trì thì bổ ngữ thời lượng đứng sau động từ biểu thị khoảng thời gian từ lúc hành động hoàn thành đến thời điểm nói.","examples":[{"zh":"我上次来医院已经过去差不多两年了。","py":"Wǒ shàng cì lái yīyuàn yǐjīng guòqù chàbuduō liǎng nián le.","vi":"Lần trước mình đến bệnh viện đã trôi qua gần hai năm rồi.","hl":"差不多两年了"},{"zh":"她回家两个月了。","py":"Tā huíjiā liǎng gè yuè le.","vi":"Cô ấy về nhà được hai tháng rồi.","hl":"两个月了"},{"zh":"开学已经三个多星期了。","py":"Kāixué yǐjīng sān gè duō xīngqī le.","vi":"Khai giảng đã hơn ba tuần rồi.","hl":"三个多星期了"}],"struct":"Động từ (không kéo dài) (+ Tân ngữ) + Khoảng thời gian + 了","note":"Dùng với các động từ kết thúc ngay (毕业, 结婚, 来, 到, 离开, 出院...) để tính thời gian từ lúc xảy ra tới hiện tại."},"g4":{"han":"固定格式“……以前/以后/前/后”","py":"Gùdìng géshì “...yǐqián/yǐhòu/qián/hòu”","title":"Cấu trúc cố định “……以前/以后/前/后”","explain":"“时间/事件+以前/前”表示某个时间或事件之前；“时间/事件+以后/后”表示某个时间或事件之后。\n“Thời gian/sự việc + 以前/前” biểu thị trước một thời điểm hoặc một sự kiện nào đó; “Thời gian/sự việc + 以后/后” biểu thị sau một thời điểm hoặc một sự kiện nào đó.","examples":[{"zh":"这种药需要每天睡前吃一次。","py":"Zhè zhǒng yào xūyào měitiān shuìqián chī yí cì.","vi":"Loại thuốc này mỗi ngày cần uống một lần trước khi đi ngủ.","hl":"睡前"},{"zh":"我们决定下班后一起去看个电影。","py":"Wǒmen juédìng xiàbān hòu yìqǐ qù kàn gè diànyǐng.","vi":"Chúng tôi quyết định sau khi tan làm cùng đi xem một bộ phim.","hl":"下班后"},{"zh":"考完试以后，咱们一起去旅游吧。","py":"Kǎowán shì yǐhòu, zánmen yìqǐ qù lǚyóu ba.","vi":"Sau khi thi xong, chúng ta cùng đi du lịch nhé.","hl":"考完试以后"}],"struct":"Thời điểm / Động từ / Cụm chủ vị + 以前/前 | 以后/后","note":"Trong tiếng Trung mốc thời gian/sự việc đứng trước 以前/以后, ngược trật tự với tiếng Việt (“trước/sau khi...”)."}},"grammarQuiz":[{"id":"hsk3_b8_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"李医生特别 (____) 病人。","opts":[{"t":"关心","ok":true},{"t":"开","ok":false},{"t":"得","ok":false},{"t":"种","ok":false},{"t":"方法","ok":false}],"exp":"Đáp án D (关心): ‘Bác sĩ Lý đặc biệt quan tâm đến bệnh nhân.’"},{"id":"hsk3_b8_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"医生说你下个星期 (____) 回来检查一下。","opts":[{"t":"得","ok":true},{"t":"开","ok":false},{"t":"种","ok":false},{"t":"关心","ok":false},{"t":"方法","ok":false}],"exp":"Đáp án B (得): ‘Bác sĩ bảo tuần sau bạn cần phải quay lại kiểm tra một lần.’"},{"id":"hsk3_b8_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"您一直很健康，有什么好的锻炼 (____) 吗？","opts":[{"t":"方法","ok":true},{"t":"开","ok":false},{"t":"得","ok":false},{"t":"种","ok":false},{"t":"关心","ok":false}],"exp":"Đáp án E (方法): ‘Ngài luôn khoẻ mạnh như vậy, có phương pháp rèn luyện nào hay không?’"},{"id":"hsk3_b8_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"如果你的病好了，医生就不会给你 (____) 药了。","opts":[{"t":"开","ok":true},{"t":"得","ok":false},{"t":"种","ok":false},{"t":"关心","ok":false},{"t":"方法","ok":false}],"exp":"Đáp án A (开): ‘Nếu bệnh của bạn khỏi rồi thì bác sĩ sẽ không kê thuốc cho bạn nữa.’"},{"id":"hsk3_b8_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"感冒的时候能吃这 (____) 药吗？你再问一下医生。","opts":[{"t":"种","ok":true},{"t":"开","ok":false},{"t":"得","ok":false},{"t":"关心","ok":false},{"t":"方法","ok":false}],"exp":"Đáp án C (种): ‘Lúc bị cảm có uống được loại thuốc này không? Bạn hỏi lại bác sĩ thử xem.’"},{"id":"hsk3_b8_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你什么时候能出院？\nB: 可能两天 (____)，我还需要做几个检查。","opts":[{"t":"以后","ok":true},{"t":"注意","ok":false},{"t":"突然","ok":false},{"t":"差不多","ok":false},{"t":"其他","ok":false}],"exp":"Đáp án E (以后): ‘Có lẽ hai ngày nữa, tôi còn cần làm vài xét nghiệm.’"},{"id":"hsk3_b8_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你是不是生病了？\nB: 是，我昨天晚上 (____) 头疼、发烧，吃完药好多了。","opts":[{"t":"突然","ok":true},{"t":"注意","ok":false},{"t":"差不多","ok":false},{"t":"其他","ok":false},{"t":"以后","ok":false}],"exp":"Đáp án B (突然): ‘Đúng vậy, tối qua tôi đột nhiên đau đầu, sốt, uống thuốc xong đỡ nhiều rồi.’"},{"id":"hsk3_b8_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你的腿可以走路，但是还不能运动。\nB: 我知道了，我会 (____) 的。","opts":[{"t":"注意","ok":true},{"t":"突然","ok":false},{"t":"差不多","ok":false},{"t":"其他","ok":false},{"t":"以后","ok":false}],"exp":"Đáp án A (注意): ‘Tôi biết rồi, tôi sẽ chú ý.’"},{"id":"hsk3_b8_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 刘医生，您下个星期来医院吗？\nB: 我下个星期一不来，(____) 时间都在。","opts":[{"t":"其他","ok":true},{"t":"注意","ok":false},{"t":"突然","ok":false},{"t":"差不多","ok":false},{"t":"以后","ok":false}],"exp":"Đáp án D (其他): ‘Thứ Hai tuần sau tôi không tới, các thời gian khác đều có mặt.’"},{"id":"hsk3_b8_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你疼了多长时间了？\nB: 有时候疼，有时候不疼，(____) 一个月吧。","opts":[{"t":"差不多","ok":true},{"t":"注意","ok":false},{"t":"突然","ok":false},{"t":"其他","ok":false},{"t":"以后","ok":false}],"exp":"Đáp án C (差不多): ‘Lúc đau lúc không, xấp xỉ một tháng rồi.’"},{"id":"hsk3_b8_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"陈天中为什么每天运动？","opts":[{"t":"C 他不想再胖下去了","ok":true},{"t":"A 他喜欢跑步","ok":false},{"t":"B 他要学打羽毛球","ok":false}],"exp":"Trần Thiên Trung nói: “因为我今年胖了十多斤，不能再胖下去了...”"},{"id":"hsk3_b8_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"李文要教陈天中做什么？","opts":[{"t":"C 打羽毛球","ok":true},{"t":"A 跑步","ok":false},{"t":"B 打篮球","ok":false}],"exp":"Lý Văn nói anh hay chơi cầu lông và có thể dạy Trần Thiên Trung."},{"id":"hsk3_b8_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"陈天中怎么了？","opts":[{"t":"C 耳朵不舒服","ok":true},{"t":"A 头疼","ok":false},{"t":"B 发高烧","ok":false}],"exp":"Trần Thiên Trung nói: “昨天游完泳以后，耳朵一直有点儿疼。”"},{"id":"hsk3_b8_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"如果下午还发烧，应该怎么办？","opts":[{"t":"A 去看医生","ok":true},{"t":"B 吃点儿药","ok":false},{"t":"C 回家休息","ok":false}],"exp":"Annie dặn: “如果下午还发烧，就一定要去看医生。”"},{"id":"hsk3_b8_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"陈天中上次来医院是什么时候？","opts":[{"t":"C 两年前","ok":true},{"t":"A 几个星期前","ok":false},{"t":"B 一个月前","ok":false}],"exp":"Trần Thiên Trung nói: “我上次来医院已经过去差不多两年了。”"},{"id":"hsk3_b8_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"陈天中为什么觉得开心多了？","opts":[{"t":"A 有人来看他","ok":true},{"t":"B 他的腿不疼了","ok":false},{"t":"C 马上就能回家了","ok":false}],"exp":"Trần Thiên Trung nói: “有人来看我，我就开心多了。”"},{"id":"hsk3_b8_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"陈天中现在怎么样了？","opts":[{"t":"A 出院了","ok":true},{"t":"B 病都好了","ok":false},{"t":"C 还不能回家","ok":false}],"exp":"Bài khóa 4: “今天我出院了。”"},{"id":"hsk3_b8_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"医生说什么最重要？","opts":[{"t":"B 多休息","ok":true},{"t":"A 多走路","ok":false},{"t":"C 吃药的方法","ok":false}],"exp":"Bài khóa 4: “医生还说最重要的是多休息。”"}],"chars":["最","近","常","体","育","馆","习","惯","胖","健","康","以","后","羽","毛","球","耳","朵","感","冒","发","烧","低","关","心","注","意","突","然","住","院","担","腿","病","人","差","不","多","得","开","出","种","方","法","其","他","里","今","天","我","了"],"rhyme":null,"notes":["Tiểu Ngữ giúp sức (trang 68): “不怎么样”是一个口语表达，意思是不太好、很一般，带有谦虚或评价不高的语气。Cụm từ “不怎么样” là cách diễn đạt dùng trong văn nói, có nghĩa “không được tốt lắm, không ổn lắm, bình thường thôi”, thường mang ngữ khí khiêm tốn hoặc đánh giá không cao.","Món quà của Tiểu Ngữ (trang 75, video 8-1): 在中国看病 — Đi khám bệnh ở Trung Quốc.","Câu hỏi thảo luận Bài khóa 1: (1) 陈天中每天下午去体育馆做什么？ (2) 李文下课以后经常做什么？ (3) 陈天中羽毛球打得怎么样？","Câu hỏi thảo luận Bài khóa 2: (1) 陈天中是什么时候开始不舒服的？ (2) 安妮想怎么帮助他？ (3) 陈天中想不想去医院？他想做什么？","Câu hỏi thảo luận Bài khóa 3: (1) 陈天中为什么住院了？ (2) 安妮觉得陈天中为什么腿疼？ (3) 医生是怎么说陈天中的腿的？","Câu hỏi thảo luận Bài khóa 4: (1) 陈天中出院前，医生做了什么？ (2) 医生给陈天中开的药应该怎么吃？ (3) 陈天中回家以后应该注意什么？"],"workbook":null},"9":{"pages":"76–85","titleZh":"打不好没关系","titlePy":"Dǎ bu hǎo méi guānxi","titleVi":"Chơi không tốt cũng không sao","goals":["能听懂并介绍体育比赛的名称、运动员、影响等信息。Có thể nghe hiểu và giới thiệu được các thông tin như tên các cuộc thi thể thao, vận động viên và ảnh hưởng của nó...","能听懂并使用可能补语说明情况的可能性。Có thể nghe hiểu và sử dụng được bổ ngữ khả năng để diễn đạt khả năng xảy ra sự việc.","掌握“越A越B”格式的用法，能说明事物或情况的变化。Nắm vững cách dùng của cấu trúc “越 A 越 B” để diễn đạt sự thay đổi của sự vật hoặc tình huống."],"words":[{"zh":"校园","py":"xiàoyuán","vi":"khuôn viên trường","pos":"dt."},{"zh":"卡","py":"kǎ","vi":"thẻ","pos":"dt."},{"zh":"球场","py":"qiúchǎng","vi":"sân bóng","pos":"dt."},{"zh":"为了","py":"wèile","vi":"vì, để","pos":"giới."},{"zh":"运动会","py":"yùndònghuì","vi":"đại hội thể dục thể thao","pos":"dt."},{"zh":"男生","py":"nánshēng","vi":"nam sinh, nam giới","pos":"dt."},{"zh":"练","py":"liàn","vi":"luyện, tập","pos":"đgt."},{"zh":"参加","py":"cānjiā","vi":"tham gia","pos":"đgt."},{"zh":"网球","py":"wǎngqiú","vi":"quần vợt, tennis","pos":"dt."},{"zh":"比赛","py":"bǐsài","vi":"trận đấu, thi đấu","pos":"dt./đgt."},{"zh":"练习","py":"liànxí","vi":"luyện tập, bài tập","pos":"đgt./dt."},{"zh":"好多","py":"hǎoduō","vi":"khá nhiều","pos":"số."},{"zh":"几乎","py":"jīhū","vi":"hầu như","pos":"phó."},{"zh":"只是","py":"zhǐshì","vi":"chỉ là, nhưng","pos":"phó./liên."},{"zh":"啤酒","py":"píjiǔ","vi":"bia","pos":"dt."},{"zh":"回","py":"huí","vi":"vụ, lần","pos":"lượng."},{"zh":"紧张","py":"jǐnzhāng","vi":"căng thẳng, hồi hộp","pos":"tt."},{"zh":"主要","py":"zhǔyào","vi":"chủ yếu, chính","pos":"tt."},{"zh":"受到","py":"shòudào","vi":"bị, nhận, chịu, nhận được","pos":"đgt."},{"zh":"影响","py":"yǐngxiǎng","vi":"sự ảnh hưởng, ảnh hưởng","pos":"dt./đgt."},{"zh":"得分","py":"défēn","vi":"ghi điểm, ghi bàn, tỉ số","pos":"đgt./dt."},{"zh":"体育","py":"tǐyù","vi":"thể dục, thể thao","pos":"dt."},{"zh":"世界","py":"shìjiè","vi":"thế giới","pos":"dt."},{"zh":"运动员","py":"yùndòngyuán","vi":"vận động viên","pos":"dt."},{"zh":"得到","py":"dédào","vi":"đạt được, nhận được","pos":"đgt."},{"zh":"成绩","py":"chéngjì","vi":"thành tích, kết quả","pos":"dt."},{"zh":"奥运会","py":"Àoyùnhuì","vi":"Thế vận hội Olympic","pos":"dt. riêng"},{"zh":"刘长春","py":"Liú Chángchūn","vi":"Lưu Trường Xuân","pos":"dt. riêng"}],"dialog":[{"section":"Bài khóa 1","context":"在图书馆门口，李文向白家月跑过去。Ở trước cửa thư viện, Lý Văn chạy về phía Bạch Gia Nguyệt.","audio":"09-1.mp3","speaker":"李文","name":"Lý Văn","zh":"家月，对不起，我昨天忘了还你校园卡了。","py":"Jiāyuè, duìbuqǐ, wǒ zuótiān wàngle huán nǐ xiàoyuánkǎ le.","vi":"Gia Nguyệt, xin lỗi hôm qua anh đã quên trả thẻ sinh viên cho em."},{"section":"Bài khóa 1","context":"","audio":"09-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"没关系。你怎么这么快就过来了？","py":"Méi guānxi. Nǐ zěnme zhème kuài jiù guòlái le?","vi":"Không sao đâu. Sao anh đến đây nhanh thế?"},{"section":"Bài khóa 1","context":"","audio":"09-1.mp3","speaker":"李文","name":"Lý Văn","zh":"我正在球场打球呢，接了你的电话就跑过来了。","py":"Wǒ zhèngzài qiúchǎng dǎqiú ne, jiēle nǐ de diànhuà jiù pǎo guòlái le.","vi":"Anh đang chơi bóng rổ trên sân, nhận điện thoại của em xong liền chạy tới đây ngay."},{"section":"Bài khóa 1","context":"","audio":"09-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"听说为了准备运动会，你们几个男生每天都练球。","py":"Tīngshuō wèile zhǔnbèi yùndònghuì, nǐmen jǐ gè nánshēng měitiān dōu liàn qiú.","vi":"Nghe nói để chuẩn bị cho Đại hội thể dục thể thao, các anh ngày nào cũng tập luyện."},{"section":"Bài khóa 1","context":"","audio":"09-1.mp3","speaker":"李文","name":"Lý Văn","zh":"是啊！你打算参加运动会吗？","py":"Shì a! Nǐ dǎsuàn cānjiā yùndònghuì ma?","vi":"Đúng vậy! Em có định tham gia Đại hội thể dục thể thao không?"},{"section":"Bài khóa 1","context":"","audio":"09-1.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我想参加网球比赛，最近一直在练习。","py":"Wǒ xiǎng cānjiā wǎngqiú bǐsài, zuìjìn yìzhí zài liànxí.","vi":"Em định tham gia thi quần vợt, gần đây em đã luyện tập liên tục."},{"section":"Bài khóa 1","context":"","audio":"09-1.mp3","speaker":"李文","name":"Lý Văn","zh":"好，到时候我去看你的比赛。","py":"Hǎo, dào shíhou wǒ qù kàn nǐ de bǐsài.","vi":"Tuyệt, tới lúc đó anh sẽ đến xem trận đấu của em nhé."},{"section":"Bài khóa 2","context":"在校园里，李文和白家月在聊天儿。Lý Văn và Bạch Gia Nguyệt đang trò chuyện trong công viên.","audio":"09-3.mp3","speaker":"李文","name":"Lý Văn","zh":"家月，你跟我们一起打羽毛球吧？","py":"Jiāyuè, nǐ gēn wǒmen yìqǐ dǎ yǔmáoqiú ba?","vi":"Gia Nguyệt, em đến chơi cầu lông cùng bọn anh nhé?"},{"section":"Bài khóa 2","context":"","audio":"09-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我好多多年没打羽毛球了，几乎忘了怎么打了。","py":"Wǒ hǎoduō nián méi dǎ yǔmáoqiú le, jīhū wàngle zěnme dǎ le.","vi":"Đã nhiều năm rồi em không chơi cầu lông, gần như quên mất cách chơi rồi."},{"section":"Bài khóa 2","context":"","audio":"09-3.mp3","speaker":"李文","name":"Lý Văn","zh":"不是比赛，打不好没关系。","py":"Bú shì bǐsài, dǎ bu hǎo méi guānxi.","vi":"Có phải thi đấu đâu, chơi không tốt cũng không sao mà."},{"section":"Bài khóa 2","context":"","audio":"09-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"这么多同学一起打，如果总是接不住球，就太不好意思了。","py":"Zhème duō tóngxué yìqǐ dǎ, rúguǒ zǒngshì jiē bu zhù qiú, jiù tài bù hǎoyìsi le.","vi":"Nhiều người cùng chơi thế kia, lỡ em không đỡ được quả nào thì ngại lắm."},{"section":"Bài khóa 2","context":"","audio":"09-3.mp3","speaker":"李文","name":"Lý Văn","zh":"你想得太多了！大家打球只是为了锻炼身体。","py":"Nǐ xiǎng de tài duō le! Dàjiā dǎqiú zhǐshì wèile duànliàn shēntǐ.","vi":"Em nghĩ nhiều quá rồi! Mọi người chơi cầu chỉ để rèn luyện sức khoẻ thôi mà."},{"section":"Bài khóa 2","context":"","audio":"09-3.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"我先自己练练吧，下周再跟你们一起打。","py":"Wǒ xiān zìjǐ liànlian ba, xià zhōu zài gēn nǐmen yìqǐ dǎ.","vi":"Em sẽ tự tập luyện trước đã, tuần sau em sẽ tham gia cùng các anh."},{"section":"Bài khóa 2","context":"","audio":"09-3.mp3","speaker":"李文","name":"Lý Văn","zh":"我在教天中打羽毛球，你可以过来跟我们一起练。","py":"Wǒ zài jiāo Tiānzhōng dǎ yǔmáoqiú, nǐ kěyǐ guòlái gēn wǒmen yìqǐ liàn.","vi":"Anh đang dạy Thiên Trung chơi cầu lông, em có thể đến tập cùng bọn anh nhé."},{"section":"Bài khóa 3","context":"在李文家，李文、白家月和陈天中一起看电视。Lý Văn xem phim cùng Bạch Gia Nguyệt và Trần Thiên Trung tại nhà của anh ấy.","audio":"09-5.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"足球比赛已经开始了，快过来看吧！","py":"Zúqiú bǐsài yǐjīng kāishǐ le, kuài guòlái kàn ba!","vi":"Trận đấu bóng đá đã bắt đầu rồi, mau lại đây xem đi!"},{"section":"Bài khóa 3","context":"","audio":"09-5.mp3","speaker":"李文","name":"Lý Văn","zh":"你们先看，冰箱里有啤酒和饮料，我去拿一下。","py":"Nǐmen xiān kàn, bīngxiāng li yǒu píjiǔ hé yǐnliào, wǒ qù ná yíxià.","vi":"Các bạn cứ xem trước đi, trong tủ lạnh có bia và đồ uống, mình đi lấy nhé."},{"section":"Bài khóa 3","context":"","audio":"09-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"今天怎么回事？总是踢不进去！","py":"Jīntiān zěnme huí shì? Zǒngshì tī bu jìnqù!","vi":"Hôm nay bị sao vậy nhỉ? Họ sút mãi mà chẳng vào!"},{"section":"Bài khóa 3","context":"","audio":"09-5.mp3","speaker":"陈天中","name":"Trần Thiên Trung","zh":"几个老球员生病了，新球员第一次参加这么重要的比赛，太紧张了。","py":"Jǐ gè lǎo qiúyuán shēngbìng le, xīn qiúyuán dì-yī cì cānjiā zhème zhòngyào de bǐsài, tài jǐnzhāng le.","vi":"Mấy cầu thủ kỳ cựu bị ốm, các cầu thủ mới thì quá căng thẳng vì đây là lần đầu họ tham gia một trận đấu quan trọng."},{"section":"Bài khóa 3","context":"","audio":"09-5.mp3","speaker":"李文","name":"Lý Văn","zh":"是啊，主要的球员没参加比赛，所以大家也都受到影响了。","py":"Shì a, zhǔyào de qiúyuán méi cānjiā bǐsài, suǒyǐ dàjiā yě dōu shòudào yǐngxiǎng le.","vi":"Đúng rồi, các cầu thủ chủ lực không thi đấu nên những người khác cũng bị ảnh hưởng theo."},{"section":"Bài khóa 3","context":"","audio":"09-5.mp3","speaker":"白家月","name":"Bạch Gia Nguyệt","zh":"越看越着急。我不看了，你们告诉我得分吧。","py":"Yuè kàn yuè zháojí. Wǒ bú kàn le, nǐmen gàosu wǒ défēn ba.","vi":"Càng xem càng thấy sốt ruột. Mình không xem nữa đâu, lát các bạn báo mình tỉ số nhé."},{"section":"Bài khóa 4","context":"在家里，李文准备演讲稿。Lý Văn chuẩn bị bài phát biểu ở trong nhà.","audio":"09-7.mp3","speaker":"李文","name":"Lý Văn","zh":"我喜欢看体育比赛，最爱看的就是奥运会。奥运会是世界上影响最大的体育比赛。从1896年到2024年，每次奥运会都有非常多的运动员参加。第一位参加奥运会的中国运动员是刘长春，他1932年参加了100米和200米短跑比赛。虽然他没有得到好成绩，但是他让世界认识了中国。","py":"Wǒ xǐhuan kàn tǐyù bǐsài, zuì ài kàn de jiùshì Àoyùnhuì. Àoyùnhuì shì shìjiè shang yǐngxiǎng zuì dà de tǐyù bǐsài. Cóng yībājiǔliù nián dào èrlíng\u0027èrsì nián, měi cì Àoyùnhuì dōu yǒu fēicháng duō de yùndòngyuán cānjiā. Dì-yī wèi cānjiā Àoyùnhuì de Zhōngguó yùndòngyuán shì Liú Chángchūn, tā yījiǔsān\u0027èr nián cānjiāle yībǎi mǐ hé èrbǎi mǐ duǎnpǎo bǐsài. Suīrán tā méiyǒu dédào hǎo chéngjì, dànshì tā ràng shìjiè rènshile Zhōngguó.","vi":"Tôi thích xem các trận thi đấu thể thao, thích xem nhất là Thế vận hội Olympic. Thế vận hội Olympic là giải thi đấu thể thao có sức ảnh hưởng lớn nhất trên thế giới. Từ năm 1896 đến 2024, mỗi kỳ Thế vận hội Olympic đều có rất nhiều vận động viên tham gia. Vận động viên Trung Quốc đầu tiên tham gia Olympic là Lưu Trường Xuân, ông đã thi đấu ở các cự ly chạy 100m và 200m vào năm 1932. Mặc dù ông không đạt được kết quả cao, nhưng ông đã khiến cả thế giới biết đến Trung Quốc."}],"dialogQuestions":[],"grammar":{"g1":{"han":"目的复句“为了……，……”","py":"Mùdì fùjù “wèile..., ...”","title":"Câu ghép chỉ mục đích “为了……，……”","explain":"目的复句“为了……，……”中，“为了”后面的小句表示目的，另一个小句表示为了达到目的采取的行动。\nTrong câu ghép chỉ mục đích “为了……，……”, mệnh đề đứng sau “为了” biểu thị mục đích, mệnh đề còn lại biểu thị hành động được thực hiện để đạt mục đích đó.","examples":[{"zh":"听说为了准备运动会，你们几个男生每天都练球。","py":"Tīngshuō wèile zhǔnbèi yùndònghuì, nǐmen jǐ gè nánshēng měitiān dōu liàn qiú.","vi":"Nghe nói để chuẩn bị đại hội thể thao, mấy bạn nam ngày nào cũng tập bóng.","hl":"为了"},{"zh":"为了考上大学，她每天努力学习。","py":"Wèile kǎoshàng dàxué, tā měitiān nǔlì xuéxí.","vi":"Để thi đỗ đại học, ngày nào cô ấy cũng chăm chỉ học tập.","hl":"为了"},{"zh":"为了早点儿到家，我打算坐飞机回去。","py":"Wèile zǎo diǎnr dàojiā, wǒ dǎsuàn zuò fēijī huíqù.","vi":"Để về nhà sớm một chút, tôi dự định đi máy bay về.","hl":"为了"}],"struct":"为了 + Mục đích，+ Chủ ngữ + Hành động","note":"Vế chỉ mục đích đặt trước hoặc có thể đảo sau động từ chính."},"g2":{"han":"可能补语","py":"Kěnéng bǔyǔ","title":"Bổ ngữ khả năng","explain":"在动词和结果补语或趋向补语之间插入“得”或“不”构成可能补语，表示条件是否容许实现某种结果或趋向。肯定形式是“动词+得+补语”，否定形式是“动词+不+补语”，疑问形式是“动词+得+补语+动词+不+补语”或者“动词+得+补语+吗”。\nThêm “得” hoặc “不” vào giữa động từ và bổ ngữ kết quả hoặc bổ ngữ xu hướng để tạo thành bổ ngữ khả năng, biểu thị điều kiện có cho phép thực hiện một kết quả hoặc phương hướng nào đó hay không.","examples":[{"zh":"打不好没关系。","py":"Dǎ bu hǎo méi guānxi.","vi":"Chơi không tốt cũng không sao.","hl":"打不好"},{"zh":"这本书你看得懂看不懂？","py":"Zhè běn shū nǐ kàn de dǒng kàn bu dǒng?","vi":"Quyển sách này bạn có đọc hiểu không?","hl":"看得懂看不懂"},{"zh":"你只有一个星期的时间，学得会游泳吗？","py":"Nǐ zhǐ yǒu yí gè xīngqī de shíjiān, xué de huì yóuyǒng ma?","vi":"Bạn chỉ có thời gian một tuần, liệu có học được bơi không?","hl":"学得会……吗"}],"struct":"Khẳng định: Động từ + 得 + Bổ ngữ | Phủ định: Động từ + 不 + Bổ ngữ | Nghi vấn: Động từ + 得 + Bổ ngữ + Động từ + 不 + Bổ ngữ / ...吗？","note":"Trong bài khóa có các ví dụ tiêu biểu: 打不好, 接不住, 踢不进去."},"g3":{"han":"固定格式“越A越B”","py":"Gùdìng géshì “yuè A yuè B”","title":"Cấu trúc cố định “越 A 越 B”","explain":"固定格式“越A越B”的句子中，A和B可以都是动词性短语或形容词性短语，也可以是一个是动词性短语，另一个是形容词性短语，表示B随着A的变化而变化。\nTrong câu sử dụng cấu trúc cố định “越 A 越 B”, A và B có thể đều là cụm động từ hoặc cụm tính từ, cũng có thể A là cụm động từ, B là cụm tính từ, để biểu thị B thay đổi theo sự thay đổi của A.","examples":[{"zh":"今天的足球比赛我越看越着急。","py":"Jīntiān de zúqiú bǐsài wǒ yuè kàn yuè zháojí.","vi":"Trận bóng đá hôm nay tôi càng xem càng sốt ruột.","hl":"越看越着急"},{"zh":"妈妈越说，他越不高兴。","py":"Māma yuè shuō, tā yuè bù gāoxìng.","vi":"Mẹ càng nói, cậu ấy càng không vui.","hl":"越说……越不高兴"},{"zh":"我想认识中国朋友，越多越好。","py":"Wǒ xiǎng rènshi Zhōngguó péngyou, yuè duō yuè hǎo.","vi":"Tôi muốn làm quen với bạn Trung Quốc, càng nhiều càng tốt.","hl":"越多越好"}],"struct":"(Chủ ngữ +) 越 + A + (Chủ ngữ 2 +) 越 + B","note":"Chú ý nếu có hai chủ ngữ khác nhau thì mỗi chủ ngữ đứng trước “越” tương ứng."}},"grammarQuiz":[{"id":"hsk3_b9_q1","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"我的腿不舒服，所以没 (____) 这次网球比赛。","opts":[{"t":"参加","ok":true},{"t":"世界","ok":false},{"t":"成绩","ok":false},{"t":"球场","ok":false},{"t":"影响","ok":false}],"exp":"Đáp án D (参加): ‘Chân tôi không khoẻ nên không tham gia giải đấu quần vợt lần này.’"},{"id":"hsk3_b9_q2","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"学校的 (____) 上，每天都有很多同学在那儿做运动。","opts":[{"t":"球场","ok":true},{"t":"世界","ok":false},{"t":"成绩","ok":false},{"t":"参加","ok":false},{"t":"影响","ok":false}],"exp":"Đáp án C (球场): ‘Trên sân bóng của trường ngày nào cũng có rất nhiều bạn học tập thể dục ở đó.’"},{"id":"hsk3_b9_q3","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"运动员们为了得到好 (____)，每天要练十多个小时。","opts":[{"t":"成绩","ok":true},{"t":"世界","ok":false},{"t":"球场","ok":false},{"t":"参加","ok":false},{"t":"影响","ok":false}],"exp":"Đáp án B (成绩): ‘Các vận động viên để giành được thành tích tốt, mỗi ngày phải tập hơn chục tiếng đồng hồ.’"},{"id":"hsk3_b9_q4","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"受到天气的 (____)，今天的足球比赛要晚两个小时开始。","opts":[{"t":"影响","ok":true},{"t":"世界","ok":false},{"t":"成绩","ok":false},{"t":"球场","ok":false},{"t":"参加","ok":false}],"exp":"Đáp án E (影响): ‘Bị ảnh hưởng bởi thời tiết, trận bóng đá hôm nay sẽ bắt đầu muộn hơn hai tiếng.’"},{"id":"hsk3_b9_q5","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"这位运动员觉得 (____) 上最重要的运动会就是奥运会。","opts":[{"t":"世界","ok":true},{"t":"成绩","ok":false},{"t":"球场","ok":false},{"t":"参加","ok":false},{"t":"影响","ok":false}],"exp":"Đáp án A (世界): ‘Vận động viên này cảm thấy đại hội thể thao quan trọng nhất trên thế giới chính là Thế vận hội Olympic.’"},{"id":"hsk3_b9_q6","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 她游泳游得快吗？\nB: 她 (____) 每天都游，现在游得特别快。","opts":[{"t":"几乎","ok":true},{"t":"只是","ok":false},{"t":"主要","ok":false},{"t":"得到","ok":false},{"t":"受到","ok":false}],"exp":"Đáp án B (几乎): ‘Cô ấy hầu như ngày nào cũng bơi, bây giờ bơi cực kỳ nhanh.’"},{"id":"hsk3_b9_q7","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 他们以前每年都是第一名，为什么今年成绩这么不好？\nB: 我觉得 (____) 是因为好多老球员病了。","opts":[{"t":"主要","ok":true},{"t":"只是","ok":false},{"t":"几乎","ok":false},{"t":"得到","ok":false},{"t":"受到","ok":false}],"exp":"Đáp án C (主要): ‘Tôi thấy chủ yếu là do rất nhiều cầu thủ kỳ cựu bị ốm.’"},{"id":"hsk3_b9_q8","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 你打得这么好，是羽毛球运动员吗？\nB: 打羽毛球 (____) 我的兴趣，我不是运动员。","opts":[{"t":"只是","ok":true},{"t":"几乎","ok":false},{"t":"主要","ok":false},{"t":"得到","ok":false},{"t":"受到","ok":false}],"exp":"Đáp án A (只是): ‘Chơi cầu lông chỉ là sở thích của tôi thôi, tôi không phải vận động viên.’"},{"id":"hsk3_b9_q9","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: (____) 我爸爸的影响，我十几岁就开始打网球了。\nB: 现在你也开始影响我，我也喜欢上了打网球。","opts":[{"t":"受到","ok":true},{"t":"只是","ok":false},{"t":"几乎","ok":false},{"t":"主要","ok":false},{"t":"得到","ok":false}],"exp":"Đáp án E (受到): ‘Chịu ảnh hưởng từ bố tôi, mười mấy tuổi tôi đã bắt đầu chơi quần vợt rồi.’"},{"id":"hsk3_b9_q10","qtype":"fill","prompt":"Chọn từ thích hợp điền vào chỗ trống (综合练习):","q":"A: 我听说你参加了学校的运动会？\nB: 是的。虽然没有 (____) 很好的成绩，但是我认识了很多新朋友。","opts":[{"t":"得到","ok":true},{"t":"只是","ok":false},{"t":"几乎","ok":false},{"t":"主要","ok":false},{"t":"受到","ok":false}],"exp":"Đáp án D (得到): ‘Tuy không giành được thành tích cao nhưng tôi đã quen được nhiều bạn mới.’"},{"id":"hsk3_b9_q11","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"李文昨天忘了做什么了？","opts":[{"t":"B 还白家月校园卡","ok":true},{"t":"A 去学校打球","ok":false},{"t":"C 给白家月打电话","ok":false}],"exp":"Lý Văn nói: “家月，对不起，我昨天忘了还你校园卡了。”"},{"id":"hsk3_b9_q12","qtype":"fill","prompt":"Nghe bài khóa 1 và chọn đáp án đúng:","q":"运动会的时候，李文要做什么？","opts":[{"t":"C 看白家月的比赛","ok":true},{"t":"A 游泳","ok":false},{"t":"B 踢足球","ok":false}],"exp":"Lý Văn nói: “好，到时候我去看你的比赛。”"},{"id":"hsk3_b9_q13","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"李文和白家月在说什么？","opts":[{"t":"C 打羽毛球","ok":true},{"t":"A 运动会","ok":false},{"t":"B 打网球","ok":false}],"exp":"Lý Văn rủ Bạch Gia Nguyệt chơi cầu lông: “家月，你跟我们一起打羽毛球吧？”"},{"id":"hsk3_b9_q14","qtype":"fill","prompt":"Nghe bài khóa 2 và chọn đáp án đúng:","q":"大家为什么一起打球？","opts":[{"t":"B 为了锻炼身体","ok":true},{"t":"A 为了比赛","ok":false},{"t":"C 为了参加运动会","ok":false}],"exp":"Lý Văn nói: “大家打球只是为了锻炼身体。”"},{"id":"hsk3_b9_q15","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"他们在做什么？","opts":[{"t":"A 看足球比赛","ok":true},{"t":"B 准备踢足球","ok":false},{"t":"C 准备参加比赛","ok":false}],"exp":"Trần Thiên Trung gọi hai bạn lại xem trận đấu bóng đá trên TV."},{"id":"hsk3_b9_q16","qtype":"fill","prompt":"Nghe bài khóa 3 và chọn đáp án đúng:","q":"白家月为什么着急？","opts":[{"t":"B 球一直踢不进去","ok":true},{"t":"A 老球员生病了","ok":false},{"t":"C 看不到比赛的得分","ok":false}],"exp":"Bạch Gia Nguyệt nói: “今天怎么回事？总是踢不进去！”"},{"id":"hsk3_b9_q17","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"李文在说什么体育比赛？","opts":[{"t":"A 奥运会","ok":true},{"t":"B 短跑比赛","ok":false},{"t":"C 中国的体育比赛","ok":false}],"exp":"Bài khóa 4 giới thiệu về Thế vận hội Olympic (“最爱看的就是奥运会”)."},{"id":"hsk3_b9_q18","qtype":"fill","prompt":"Nghe bài khóa 4 và chọn đáp án đúng:","q":"刘长春参加了哪个比赛？","opts":[{"t":"A 100米短跑","ok":true},{"t":"B 200米游泳","ok":false},{"t":"C 5000米长跑","ok":false}],"exp":"Bài khóa 4: “他1932年参加了100米和200米短跑比赛。”"}],"chars":["校","园","卡","球","场","为","了","运","动","会","男","生","练","参","加","网","比","赛","习","好","多","几","乎","只","是","啤","酒","回","紧","张","主","要","受","到","影","响","得","分","体","育","世","界","员","成","绩","奥","刘","长","春","打","不","没","关","系"],"rhyme":null,"notes":["Tiểu Ngữ giúp sức (trang 79): “接”的本义是托住、承受，这里“接球”的意思是回球或者把球打回去。Nghĩa gốc của “接” là đỡ, nhận, tiếp nhận; “接球” trong trường hợp này có nghĩa là trả bóng hoặc đánh bóng trả lại.","Tổng kết học tập Bài 7–9 (trang 84–85): 9 điểm ngữ pháp gồm 连动句(2), 比较句(10) A不比B+形容词, 程度补语(3) 极了, 递进复句 不但……，而且……, 趋向补语的引申用法(1) 下去, 离合词(2), 时量补语(2), ……以前/以后/前/后, 为了……，……, 可能补语 và 越A越B.","Câu hỏi thảo luận Bài khóa 1: (1) 李文为什么来得很快？ (2) 李文每天在做什么？ (3) 白家月最近在做什么？","Câu hỏi thảo luận Bài khóa 2: (1) 李文叫白家月一起做什么？ (2) 白家月为什么不想去？ (3) 白家月想先做什么？","Câu hỏi thảo luận Bài khóa 3: (1) 李文要去冰箱里拿什么？ (2) 今天的足球比赛踢得怎么样？ (3) 球员们受到什么影响了？","Câu hỏi thảo luận Bài khóa 4: (1) 奥运会是一个什么样的体育比赛？ (2) 1932年，中国运动员的比赛成绩怎么样？ (3) 刘长春的影响是什么？"],"workbook":null}};
